VRT_L("tle-d-chimie-r01",{"duree":20,"titre":"Les alcools et le sodium","accroche":"Une réaction vive, qui révèle l'hydrogène mobile de l'alcool.","intro":"Le groupe hydroxyle des alcools réagit avec le sodium, comme le fait l'eau, mais plus doucement.","objectifs":["écrire l'équation de la réaction","identifier le gaz dégagé","nommer l'alcoolate formé"],"parties":[{"t":"La réaction","html":"<div class='def'><b>Définition</b>Un <strong>alcool</strong> possède un groupe hydroxyle −OH porté par un carbone tétragonal. Il réagit avec le sodium en libérant du dihydrogène et en formant un <strong>alcoolate</strong> : <strong>2 R−OH + 2 Na → 2 (R−O⁻ + Na⁺) + H₂</strong>.</div>"},{"t":"Mise en évidence","html":"<p>Le dihydrogène détone à l'approche d'une flamme. L'alcoolate donne une solution basique.</p><div class='ex'><b>Exemple</b>Avec l'éthanol, on forme l'éthanolate de sodium.</div>","labo":{"type":"equilibre","reactifs":[{"f":"C₂H₅OH","at":{"C":2,"H":6,"O":1}},{"f":"Na","at":{"Na":1}}],"produits":[{"f":"C₂H₅ONa","at":{"C":2,"H":5,"O":1,"Na":1}},{"f":"H₂","at":{"H":2}}]}},{"t":"Sécurité","html":"<div class='attention'><b>Sécurité</b>Le sodium réagit violemment avec l'eau : il se manipule en petite quantité, sous la conduite du professeur.</div>","retenir":"Un alcoolate est une base forte."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le groupe caractéristique des alcools est :</p><ol type='a'><li>le groupe hydroxyle −OH porté par un carbone tétragonal</li><li>le groupe carbonyle C=O porté par un carbone trigonal</li><li>le groupe carboxyle −COOH porté par un carbone terminal</li><li>le groupe amine −NH₂ porté par un carbone tétragonal</li></ol><details><summary>Voir la réponse</summary><p><strong>le groupe hydroxyle −OH porté par un carbone tétragonal</strong>. Le carbone qui porte −OH n'est lié qu'à des atomes par liaisons simples.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Quel volume de H₂ (CNTP) se forme avec 0,2 mol d'éthanol ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 0,1 mol, soit 2,24 L.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Au laboratoire d'un lycée de Bafoussam, un flacon contient un monoalcool saturé inconnu. On fait réagir 2,3 g de cet alcool avec un excès de sodium : il se dégage 0,56 L de dihydrogène (volume molaire 22,4 L/mol). Akono affirme qu'il s'agit du propan-1-ol ; Bella, de l'éthanol. M(C) = 12 ; M(H) = 1 ; M(O) = 16 g/mol.</p><p><strong>Consigne 1.</strong> Écris l'équation de la réaction de l'alcool sur le sodium.</p><p><strong>Consigne 2.</strong> À l'aide d'une démarche scientifique, départage Akono et Bella.</p><details><summary>Voir une réponse attendue</summary><p>2 R-OH + 2 Na → 2 R-O⁻ + 2 Na⁺ + H₂. n(H₂) = 0,56/22,4 = 0,025 mol, donc n(alcool) = 0,05 mol et M = 2,3/0,05 = 46 g/mol. CₙH₂ₙ₊₁OH : 14n + 18 = 46, n = 2 : c'est l'éthanol. Bella a raison.</p></details></div>","retenir":"Savoir-être mobilisé : Souci de la sécurité au laboratoire."}],"revision":["R−OH + Na : alcoolate + H₂.","Test du H₂ : détonation."],"exo":"<p>Quel volume de H₂ (CNTP) se forme avec 0,2 mol d'éthanol ? <em>(Réponse : 0,1 mol, soit 2,24 L.)</em></p>","quiz":[{"q":"Le groupe caractéristique des alcools est :","r":["le groupe hydroxyle −OH porté par un carbone tétragonal","le groupe carbonyle C=O porté par un carbone trigonal","le groupe carboxyle −COOH porté par un carbone terminal","le groupe amine −NH₂ porté par un carbone tétragonal"],"b":0,"e":"Le carbone qui porte −OH n'est lié qu'à des atomes par liaisons simples."},{"q":"La formule générale des alcools saturés non cycliques est :","r":["CₙH₂ₙO₂","CₙH₂ₙ₊₁OH","CₙH₂ₙ","CₙH₂ₙ₊₂"],"b":1,"e":"Ex. : C₂H₅OH, l'éthanol."},{"q":"Le propan-2-ol est un alcool :","r":["primaire","tertiaire","secondaire","aromatique"],"b":2,"e":"Le carbone fonctionnel est lié à deux atomes de carbone."},{"q":"Le 2-méthylpropan-2-ol est un alcool :","r":["primaire","secondaire","phénolique","tertiaire"],"b":3,"e":"Le carbone fonctionnel est lié à trois atomes de carbone."},{"q":"Le sodium réagit avec un alcool en donnant :","r":["un alcoolate et du dihydrogène","un ester et de l'eau, de façon limitée","un aldéhyde et du dihydrogène","un alcène, de l'eau et du dioxygène gazeux"],"b":0,"e":"2 R−OH + 2 Na → 2 R−O⁻ + 2 Na⁺ + H₂."},{"q":"Le gaz dégagé par l'action du sodium sur l'éthanol :","r":["trouble l'eau de chaux en formant un précipité","produit une légère détonation à la flamme","ravive une bûchette qui présente un point incandescent","est incolore, inodore et ne réagit pas à la flamme"],"b":1,"e":"C'est le test du dihydrogène."},{"q":"Le nom de CH₃−CH₂−CH₂−OH est :","r":["propan-2-ol","éthanol","propan-1-ol","butan-1-ol"],"b":2,"e":"La chaîne a trois carbones et −OH sur le carbone 1."},{"q":"L'ion éthanolate C₂H₅O⁻ est :","r":["un acide fort","un oxydant","un sel neutre","une base forte"],"b":3,"e":"Il réagit totalement avec l'eau."},{"q":"La réaction du sodium avec l'éthanol est moins vive qu'avec l'eau car :","r":["l'éthanol est un acide plus faible que l'eau","l'éthanol est un acide plus fort que l'eau","le sodium ne réagit pas avec l'éthanol, contrairement à l'eau","l'éthanol est un gaz à la température ordinaire"],"b":0,"e":"La liaison O−H de l'éthanol est moins polarisée."},{"q":"Les alcools ont des températures d'ébullition élevées en raison :","r":["de leur masse molaire très élevée","des liaisons hydrogène entre molécules","de leur couleur et de leur odeur","de l'absence de toute liaison entre molécules"],"b":1,"e":"Le groupe −OH crée des liaisons hydrogène."}],"c":"Tle D","m":"chimie","rang":1,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un laborantin d'un lycée de Bafoussam doit vérifier si un flacon non étiqueté contient un alcool.","tache":"Propose un test et écris l'équation avec l'éthanol."},"gratuit":true});
VRT_L("tle-d-chimie-r02",{"duree":20,"titre":"La déshydratation des alcools","accroche":"Selon la température, on obtient un alcène ou un éther.","intro":"En retirant de l'eau, l'alcool se transforme. La température décide du produit.","objectifs":["distinguer déshydratations intra et intermoléculaire","écrire les équations","prévoir le produit"],"parties":[{"t":"Déshydratation intramoléculaire","html":"<div class='def'><b>Définition</b>La <strong>déshydratation intramoléculaire</strong> élimine une molécule d'eau à partir d'une molécule d'alcool, et forme un <strong>alcène</strong>.</div><p class='formule'>CH₃−CH₂OH → CH₂=CH₂ + H₂O (vers 170 °C, en milieu acide)</p>"},{"t":"Déshydratation intermoléculaire","verrou":true},{"t":"Choisir les conditions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":2,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un technicien de Douala dispose d'éthanol et doit obtenir de l'éthène pour une synthèse.","tache":"Indique les conditions à choisir."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r03",{"duree":25,"titre":"L'oxydation des alcools","accroche":"Le vin de palme qui tourne au vinaigre : une oxydation ménagée.","intro":"La classe d'un alcool détermine le produit de son oxydation. Cette question revient très souvent au bac.","objectifs":["définir l'oxydation ménagée","prévoir le produit selon la classe","identifier un aldéhyde et une cétone"],"parties":[{"t":"Combustion et oxydation ménagée","html":"<div class='def'><b>Définition</b>L'<strong>oxydation ménagée</strong> est une oxydation qui s'effectue sans destruction de la chaîne carbonée. La combustion, elle, la détruit.</div>"},{"t":"Selon la classe","verrou":true},{"t":"Les tests","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":3,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une vendeuse de vin de palme à Bafia remarque que sa boisson devient acide au bout de quelques jours.","tache":"Explique la transformation de l'éthanol."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r04",{"duree":25,"titre":"L'estérification","accroche":"Lente, limitée, athermique : les trois mots du bac.","intro":"Un acide et un alcool forment un ester et de l'eau. Le rendement dépend de la classe de l'alcool.","objectifs":["écrire la réaction","citer ses caractéristiques","améliorer le rendement"],"parties":[{"t":"La réaction","html":"<div class='def'><b>Définition</b>L'<strong>estérification</strong> est la réaction entre un acide carboxylique et un alcool, formant un <strong>ester</strong> et de l'eau : <strong>R−COOH + R'−OH ⇌ R−COO−R' + H₂O</strong>.</div><p>La formule générale d'un ester saturé est CₙH₂ₙO₂.</p>"},{"t":"Caractéristiques","verrou":true},{"t":"Améliorer le rendement","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":4,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un artisan de Limbé fabrique un arôme fruité à partir d'acide éthanoïque et d'éthanol, mais il trouve son rendement trop faible.","tache":"Propose deux moyens de l'améliorer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r05",{"duree":20,"titre":"Préparation des alcools","accroche":"Du maïs à l'alcool : la fermentation.","intro":"Les alcools s'obtiennent à partir d'alcènes ou par fermentation. Une boisson mal distillée peut être mortelle.","objectifs":["écrire l'hydratation d'un alcène","appliquer la règle de Markovnikov","écrire la fermentation"],"parties":[{"t":"Hydratation d'un alcène","html":"<div class='def'><b>Définition</b>L'<strong>hydratation d'un alcène</strong> fixe une molécule d'eau sur la double liaison et forme un alcool.</div><p>Règle de Markovnikov : l'hydrogène se fixe de préférence sur le carbone le plus hydrogéné.</p>"},{"t":"Fermentation alcoolique","verrou":true},{"t":"Danger du méthanol","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":5,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Dans un village de l'Extrême-Nord, une famille prépare du bili-bili à partir de sorgho.","tache":"Écris l'équation de la fermentation du glucose et calcule la quantité d'éthanol obtenue avec 2 mol de glucose."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r06",{"duree":20,"titre":"Les acides carboxyliques : structure et nomenclature","accroche":"Le goût piquant du vinaigre vient d'un groupe précis.","intro":"Les acides carboxyliques portent un groupe carboxyle. Ils se nomment à partir de la chaîne la plus longue.","objectifs":["reconnaître le groupe carboxyle","nommer un acide","citer des propriétés physiques"],"parties":[{"t":"Structure","html":"<div class='def'><b>Définition</b>Un <strong>acide carboxylique</strong> possède le groupe carboxyle <strong>−COOH</strong>. Sa formule générale saturée est CₙH₂ₙO₂.</div>"},{"t":"Nomenclature","verrou":true},{"t":"Propriétés physiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":6,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un élève de Kumba doit identifier le composant du vinaigre d'un flacon.","tache":"Donne sa formule et son nom systématique."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r07",{"duree":25,"titre":"Acides carboxyliques : chlorures d'acyle et anhydrides","accroche":"Des dérivés bien plus réactifs que l'acide.","intro":"Les acides carboxyliques sont des acides faibles. Leurs dérivés permettent des synthèses efficaces, dont celle de l'aspirine.","objectifs":["écrire la dissociation d'un acide","préparer un chlorure d'acyle","former un anhydride"],"parties":[{"t":"Propriétés acides","html":"<div class='def'><b>Définition</b>Un <strong>acide faible</strong> ne réagit que partiellement avec l'eau : <strong>R−COOH + H₂O ⇌ R−COO⁻ + H₃O⁺</strong>.</div>"},{"t":"Chlorures d'acyle","verrou":true},{"t":"Anhydrides","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":7,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Dans un laboratoire pharmaceutique de Yaoundé, on veut préparer de l'aspirine avec un excellent rendement.","tache":"Explique pourquoi on choisit l'anhydride éthanoïque plutôt que l'acide éthanoïque."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r08",{"duree":25,"titre":"Amides, polycondensation et saponification","accroche":"L'huile de palme et la soude donnent du savon.","intro":"Les dérivés d'acides conduisent aux amides, aux polyamides et aux savons, très présents dans notre quotidien.","objectifs":["former un amide","définir la polycondensation","écrire la saponification"],"parties":[{"t":"Les amides","html":"<div class='def'><b>Définition</b>Un <strong>amide</strong> contient le groupe −CO−N&lt;. On l'obtient en faisant réagir une amine ou l'ammoniac avec un chlorure d'acyle ou un anhydride.</div>"},{"t":"Polycondensation","verrou":true},{"t":"La saponification","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":8,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une coopérative de femmes à Mbanga fabrique du savon à partir d'huile de palme et de soude.","tache":"Écris le principe de la réaction et dis pourquoi elle est préférable à une réaction réversible."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r09",{"duree":20,"titre":"Les amines : généralités","accroche":"L'odeur du poisson a une origine chimique.","intro":"Les amines dérivent de l'ammoniac. Leur classe dépend du nombre de groupes fixés sur l'azote.","objectifs":["reconnaître une amine","donner sa classe","nommer une amine"],"parties":[{"t":"Définition et classe","html":"<div class='def'><b>Définition</b>Une <strong>amine</strong> dérive de NH₃ par remplacement d'atomes d'hydrogène par des groupes carbonés. Elle est <strong>primaire</strong>, <strong>secondaire</strong> ou <strong>tertiaire</strong>.</div>"},{"t":"Nomenclature","verrou":true},{"t":"Propriétés physiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":9,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une technicienne de Kribi analyse les composés responsables de l'odeur du poisson au port.","tache":"Classe la triméthylamine."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r10",{"duree":20,"titre":"Propriétés chimiques des amines","accroche":"Un doublet libre, et l'amine devient base et nucléophile.","intro":"Le doublet non liant de l'azote explique le caractère basique et nucléophile des amines.","objectifs":["expliquer le caractère basique","écrire l'alkylation","écrire l'acylation"],"parties":[{"t":"Caractère basique","html":"<div class='def'><b>Propriété</b>Grâce au doublet libre de l'azote, une amine est une <strong>base faible</strong> : <strong>R−NH₂ + H₂O ⇌ R−NH₃⁺ + HO⁻</strong>.</div>"},{"t":"Alkylation","verrou":true},{"t":"Acylation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":10,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une équipe de contrôle de Douala teste un produit de nettoyage contenant une amine.","tache":"Écris sa réaction avec l'eau et le caractère de la solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r11",{"duree":20,"titre":"Acides α-aminés","accroche":"Les briques de toutes nos protéines.","intro":"Les acides α-aminés portent deux fonctions qui leur donnent une propriété originale, l'ion dipolaire.","objectifs":["reconnaître un acide α-aminé","écrire l'amphion","connaître la configuration naturelle"],"parties":[{"t":"Structure","html":"<div class='def'><b>Définition</b>Un <strong>acide α-aminé</strong> possède un groupe carboxyle et un groupe amino portés par le même carbone : <strong>R−CH(NH₂)−COOH</strong>.</div>"},{"t":"L'amphion","verrou":true},{"t":"Chiralité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":11,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une nutritionniste de Maroua explique que les protéines du niébé sont formées d'acides aminés.","tache":"Écris la forme dipolaire de l'alanine."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r12",{"duree":25,"titre":"La synthèse des polypeptides","accroche":"Une liaison répétée construit une protéine.","intro":"La liaison peptidique unit deux acides α-aminés. Une synthèse contrôlée suppose de protéger certaines fonctions.","objectifs":["écrire une liaison peptidique","compter les dipeptides","décrire le blocage et l'activation"],"parties":[{"t":"La liaison peptidique","html":"<div class='def'><b>Définition</b>La <strong>liaison peptidique</strong> −CO−NH− résulte de la condensation du groupe carboxyle d'un acide α-aminé sur le groupe amino d'un autre.</div>"},{"t":"Les dipeptides possibles","verrou":true},{"t":"La synthèse contrôlée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":12,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un laboratoire de recherche à Yaoundé veut fabriquer uniquement le dipeptide Gly-Ala.","tache":"Présente les étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r13",{"duree":15,"titre":"L'isomérie de constitution","accroche":"Mêmes atomes, liens différents, propriétés différentes.","intro":"Des composés de même formule brute peuvent être très différents.","objectifs":["définir l'isomérie","distinguer les trois types","écrire des isomères"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Des <strong>isomères de constitution</strong> ont la même formule brute, mais un enchaînement d'atomes différent.</div>"},{"t":"Les types","html":"<ul><li>De chaîne.</li><li>De position.</li><li>De fonction.</li></ul>","labo":{"type":"trier","invite":"Choisis un type.","items":[["De chaîne","squelette différent."],["De position","groupe fonctionnel déplacé."],["De fonction","groupe fonctionnel différent."]]}},{"t":"Exemple","html":"<p>C₂H₆O : éthanol CH₃−CH₂OH et méthoxyméthane CH₃−O−CH₃ sont isomères de fonction.</p>","retenir":"Même formule brute, formules développées différentes."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Des isomères ont :</p><ol type='a'><li>la même formule développée et des formules brutes différentes</li><li>la même formule brute et des formules développées différentes</li><li>des masses molaires différentes</li><li>des formules brutes différentes et la même fonction</li></ol><details><summary>Voir la réponse</summary><p><strong>la même formule brute et des formules développées différentes</strong>. Ils ont des propriétés différentes.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Butan-1-ol et butan-2-ol : quel type d'isomérie ?</p><details><summary>Voir la réponse</summary><p>(Réponse : de position.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Lors d'un bac blanc, on demande tous les isomères de formule C₄H₁₀O. Un élève en trouve quatre ; un autre affirme qu'il y en a sept.</p><p><strong>Consigne 1.</strong> Écris les formules semi-développées et nomme tous les isomères.</p><p><strong>Consigne 2.</strong> Départage les deux élèves en précisant les types d'isomérie.</p><details><summary>Voir une réponse attendue</summary><p>Alcools : butan-1-ol, butan-2-ol, 2-méthylpropan-1-ol, 2-méthylpropan-2-ol. Éthers : méthoxypropane, 2-méthoxypropane, éthoxyéthane. Sept isomères : isomérie de chaîne, de position et de fonction (alcool/éther). Le second élève a raison.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Même formule brute.","Chaîne, position, fonction."],"exo":"<p>Butan-1-ol et butan-2-ol : quel type d'isomérie ? <em>(Réponse : de position.)</em></p>","quiz":[{"q":"Des isomères ont :","r":["la même formule développée et des formules brutes différentes","la même formule brute et des formules développées différentes","des masses molaires différentes","des formules brutes différentes et la même fonction"],"b":1,"e":"Ils ont des propriétés différentes."},{"q":"Le butane et le méthylpropane sont des isomères :","r":["de fonction","de position","de chaîne","optiques"],"b":2,"e":"Ils diffèrent par la structure de la chaîne carbonée."},{"q":"Le propan-1-ol et le propan-2-ol sont des isomères :","r":["de chaîne","de fonction","géométriques","de position"],"b":3,"e":"Le groupe OH n'est pas sur le même carbone."},{"q":"L'éthanol et le méthoxyméthane sont des isomères :","r":["de fonction","de position","de chaîne","optiques"],"b":0,"e":"Ils ont la formule C₂H₆O mais des fonctions différentes."},{"q":"Le propanal et la propanone sont des isomères :","r":["de chaîne","de fonction","géométriques","optiques"],"b":1,"e":"Aldéhyde et cétone de formule C₃H₆O."},{"q":"Le nombre d'isomères de formule C₄H₁₀ est :","r":["1","3","2","4"],"b":2,"e":"Le butane et le méthylpropane."},{"q":"L'isomérie de constitution concerne :","r":["l'orientation dans l'espace seulement","la couleur","l'état physique","l'enchaînement des atomes"],"b":3,"e":"Les atomes sont liés différemment."},{"q":"Le nombre d'alcools isomères de formule C₃H₈O est :","r":["2","1","3","4"],"b":0,"e":"Propan-1-ol et propan-2-ol."},{"q":"Les isomères de fonction ont :","r":["les mêmes propriétés chimiques et la même fonction","des propriétés chimiques différentes","la même fonction chimique","la même formule développée plane"],"b":1,"e":"Leurs groupes caractéristiques diffèrent."},{"q":"La formule C₂H₄O₂ peut correspondre à :","r":["l'éthanol ou l'éthanal, son produit d'oxydation","l'éthène","l'acide éthanoïque ou le méthanoate de méthyle","l'éthanal"],"b":2,"e":"Acide et ester sont isomères de fonction."}],"c":"Tle D","m":"chimie","rang":13,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Deux flacons d'un laboratoire de Dschang portent la même formule C₄H₁₀O. Le liquide A réagit avec le sodium (dégagement gazeux) et bout à 118 °C ; le liquide B ne réagit pas avec le sodium et bout à 35 °C.","tache":"Explique ce qui les distingue et propose une formule pour chacun."},"gratuit":true});
VRT_L("tle-d-chimie-r14",{"duree":25,"titre":"La stéréo-isomérie","accroche":"Deux molécules comme une main droite et une main gauche.","intro":"Des molécules de même enchaînement peuvent différer par leur disposition dans l'espace.","objectifs":["distinguer Z et E","reconnaître un carbone asymétrique","représenter des énantiomères"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Des <strong>stéréo-isomères</strong> ont le même enchaînement d'atomes, mais une disposition différente dans l'espace.</div>"},{"t":"Isomérie Z/E","verrou":true},{"t":"Énantiomérie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":14,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un parfumeur de Douala reçoit deux échantillons d'un arôme, le 2-méthylbutan-1-ol, qui dévient la lumière polarisée en sens opposés. Son assistant pense qu'il s'agit d'une erreur de mesure.","tache":"Montre que la molécule est chirale en identifiant le carbone concerné et réponds à l'assistant."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r15",{"duree":25,"titre":"Évolution d'un système et vitesse de réaction","accroche":"Une vitesse se lit sur une tangente.","intro":"La cinétique étudie la rapidité des réactions. Elle est au programme du bac sous forme de graphiques.","objectifs":["définir réaction rapide et lente","calculer une vitesse","relier les vitesses à l'équation"],"parties":[{"t":"Réactions rapides et lentes","html":"<div class='def'><b>Définitions</b>Une <strong>réaction rapide</strong> paraît achevée dès que les réactifs sont mis en contact. Une <strong>réaction lente</strong> dure de quelques secondes à plusieurs heures.</div>"},{"t":"Vitesse instantanée","verrou":true},{"t":"Suivre une réaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":15,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Au laboratoire d'un lycée de Bafoussam, on suit la formation de diiode en prélevant des échantillons toutes les 5 minutes.","tache":"Explique pourquoi on plonge chaque prélèvement dans la glace."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r16",{"duree":20,"titre":"Les facteurs cinétiques","accroche":"Pourquoi les aliments se gardent mieux au froid.","intro":"La température, la concentration et le catalyseur modifient la vitesse des réactions.","objectifs":["définir un facteur cinétique","citer les facteurs","définir un catalyseur"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>facteur cinétique</strong> est un paramètre qui modifie la vitesse d'une réaction : température, concentration, catalyseur.</div>"},{"t":"Influence","verrou":true},{"t":"Le catalyseur","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":16,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Une vendeuse de Ngaoundéré conserve sa viande dans la glace pour la vendre le lendemain.","tache":"Explique l'effet du froid sur les réactions de dégradation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r17",{"duree":20,"titre":"L'eau, l'autoprotolyse et le pH","accroche":"Une eau neutre n'a pas toujours un pH de 7.","intro":"L'eau pure contient un peu d'ions. Leur produit dépend de la température.","objectifs":["écrire l'autoprotolyse","utiliser Ke","calculer un pH neutre"],"parties":[{"t":"Autoprotolyse","html":"<div class='def'><b>Définition</b>L'<strong>autoprotolyse</strong> de l'eau est la réaction : <strong>2 H₂O ⇌ H₃O⁺ + HO⁻</strong>. Le produit ionique est <strong>Ke = [H₃O⁺][HO⁻]</strong>, soit 10⁻¹⁴ à 25 °C.</div>"},{"t":"pH","verrou":true},{"t":"Effet de la température","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":17,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Un technicien d'hôpital à Douala s'étonne qu'une solution neutre à 37 °C n'ait pas un pH de 7.","tache":"Explique ce fait avec pKe = 13,72."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r18",{"duree":15,"titre":"Les acides forts","accroche":"Une réaction totale avec l'eau.","intro":"Le pH d'un acide fort se calcule directement à partir de sa concentration.","objectifs":["définir un acide fort","calculer un pH","écrire l'équation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Selon Brönsted, un <strong>acide</strong> est une espèce capable de céder un proton. Un <strong>acide fort</strong> réagit totalement avec l'eau.</div><p class='formule'>HCl + H₂O → H₃O⁺ + Cl⁻</p>"},{"t":"Le pH","verrou":true},{"t":"Dilution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":18,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Un technicien d'une usine de Bassa, à Douala, doit vérifier une solution d'acide chlorhydrique étiquetée à 0,01 mol/L.","tache":"Dis quel pH il devrait mesurer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r19",{"duree":15,"titre":"Les bases fortes","accroche":"De la soude à l'eau de Javel, attention au pH élevé.","intro":"Le pH d'une base forte se calcule à partir de sa concentration et de Ke.","objectifs":["définir une base forte","calculer un pH","manipuler avec prudence"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Selon Brönsted, une <strong>base</strong> est une espèce capable de capter un proton. Une <strong>base forte</strong> réagit totalement avec l'eau.</div>"},{"t":"Le pH","verrou":true},{"t":"Sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":19,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Une savonnerie artisanale de Mbanga utilise une solution de soude à 0,1 mol/L.","tache":"Calcule son pH et indique la protection nécessaire."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r20",{"duree":25,"titre":"Acides faibles et bases faibles","accroche":"Une réaction limitée, plusieurs espèces à calculer.","intro":"Un acide faible coexiste avec sa base conjuguée. Les bac réclament l'inventaire complet des concentrations.","objectifs":["faire l'inventaire des espèces","écrire électroneutralité et conservation","calculer une concentration"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>acide faible</strong> réagit partiellement avec l'eau : <strong>AH + H₂O ⇌ A⁻ + H₃O⁺</strong>.</div>"},{"t":"Méthode du bac","verrou":true},{"t":"Comparer","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":20,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Un flacon de jus de citron analysé à Bafoussam présente un pH plus élevé que celui d'un acide fort de même concentration.","tache":"Conclus sur la nature de l'acide."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r21",{"duree":25,"titre":"Couples acide/base et domaines de prédominance","accroche":"pH = pKa : les deux formes sont à égalité.","intro":"Le pKa indique la force d'un acide et permet de prévoir quelle forme domine.","objectifs":["définir Ka et pKa","appliquer la relation d'Henderson","tracer un domaine de prédominance"],"parties":[{"t":"Constante d'acidité","html":"<div class='def'><b>Définition</b>Pour un couple AH/A⁻ : <strong>Ka = [A⁻][H₃O⁺] / [AH]</strong> et <strong>pKa = −log Ka</strong>.</div>"},{"t":"La relation","verrou":true},{"t":"Prédominance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":21,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Pour contrôler un flacon, un élève de Limbé compare son pKa calculé (4,2) à un tableau de pKa d'acides connus.","tache":"Explique comment identifier l'acide."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r22",{"duree":25,"titre":"Dosage acide fort - base forte","accroche":"Trois zones, un saut de pH, et un calcul simple.","intro":"Un dosage détermine une concentration inconnue. La courbe présente une forme caractéristique.","objectifs":["écrire la réaction de dosage","déterminer l'équivalence","calculer une concentration"],"parties":[{"t":"Le dosage","html":"<div class='def'><b>Définition</b>Un <strong>dosage</strong> détermine la concentration d'une solution à l'aide d'une réaction totale. À l'<strong>équivalence</strong>, les réactifs sont dans les proportions stœchiométriques.</div><p class='formule'>H₃O⁺ + HO⁻ → 2 H₂O</p>"},{"t":"Équivalence","html":"<p class='formule'>C_a V_a = C_b V_bE</p><p>Pour un dosage acide fort - base forte à 25 °C, le pH à l'équivalence vaut 7.</p>","labo":{"type":"dosage","mode":"fort"}},{"t":"Trouver le point","html":"<p>La méthode des tangentes parallèles donne le point d'équivalence. Un indicateur coloré dont la zone de virage contient pH 7 convient.</p>","retenir":"À l'équivalence : C_a V_a = C_b V_bE."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Au cours du dosage d'un acide fort par une base forte, à l'équivalence :</p><ol type='a'><li>le pH vaut 4,0</li><li>le pH vaut 10,0 à toute température</li><li>le pH vaut 0</li><li>le pH vaut 7 à 25 °C</li></ol><details><summary>Voir la réponse</summary><p><strong>le pH vaut 7 à 25 °C</strong>. La solution ne contient que de l'eau et un sel neutre.</p></details><p><strong>Application directe des savoirs.</strong></p><p>V_a = 20 mL, C_b = 0,1 mol/L, V_bE = 10 mL : C_a ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 0,05 mol/L.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un détartrant est une solution concentrée d'acide chlorhydrique. On la dilue 10 fois ; 10 mL de solution diluée sont dosés par une soude à 0,10 mol/L : Véq = 12 mL. L'étiquette indique 1,0 mol/L.</p><p><strong>Consigne 1.</strong> Écris l'équation du dosage et calcule la concentration du détartrant.</p><p><strong>Consigne 2.</strong> L'étiquette est-elle exacte ? Quel indicateur coloré utiliser ?</p><details><summary>Voir une réponse attendue</summary><p>H₃O⁺ + HO⁻ → 2 H₂O. C(diluée) = 0,10 × 12/10 = 0,12 mol/L ; C = 1,2 mol/L. L'étiquette est inexacte : la solution est plus concentrée que les 1,0 mol/L annoncés (écart de 20 % par rapport à l'étiquette). Équivalence à pH 7 : bleu de bromothymol.</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique face aux résultats."}],"revision":["Réaction totale.","C_a V_a = C_b V_bE.","pH = 7."],"exo":"<p>V_a = 20 mL, C_b = 0,1 mol/L, V_bE = 10 mL : C_a ? <em>(Réponse : 0,05 mol/L.)</em></p>","quiz":[{"q":"Au cours du dosage d'un acide fort par une base forte, à l'équivalence :","r":["le pH vaut 4,0","le pH vaut 10,0 à toute température","le pH vaut 0","le pH vaut 7 à 25 °C"],"b":3,"e":"La solution ne contient que de l'eau et un sel neutre."},{"q":"À l'équivalence, on a :","r":["Ca Va = Cb VbE","Ca = Cb","Va = VbE toujours","Ca Vb = Cb Va"],"b":0,"e":"Les quantités d'acide et de base apportées sont égales."},{"q":"10 mL d'acide chlorhydrique sont dosés par de la soude à 0,1 mol/L ; VbE = 15 mL. Ca vaut :","r":["0,1 mol/L","0,15 mol/L","0,067 mol/L","1,5 mol/L"],"b":1,"e":"Ca = 0,1 × 15/10."},{"q":"La courbe pH = f(Vb) d'un dosage acide fort-base forte présente :","r":["une droite croissante, sans aucun saut","aucun saut de pH","un saut de pH important autour de l'équivalence","un pH constant"],"b":2,"e":"Le pH passe brusquement de 4 à 10 environ."},{"q":"L'équivalence se repère graphiquement par :","r":["le premier point de la courbe de dosage","le dernier point de la courbe","l'origine des axes","la méthode des tangentes parallèles"],"b":3,"e":"On trace deux tangentes parallèles et leur médiane."},{"q":"Un indicateur convenable pour ce dosage est :","r":["le bleu de bromothymol (virage 6,0-7,6)","l'hélianthine seule, toujours (virage 3,1-4,4)","aucun","l'eau iodée"],"b":0,"e":"Sa zone de virage contient le pH à l'équivalence."},{"q":"La réaction de dosage s'écrit :","r":["H₃O⁺ + Cl⁻ → HCl","H₃O⁺ + HO⁻ → 2 H₂O","Na⁺ + Cl⁻ → NaCl","H₂O → H⁺ + HO⁻"],"b":1,"e":"C'est une réaction totale et rapide."},{"q":"Avant l'équivalence, le réactif en excès est :","r":["la base","l'eau","l'acide","aucun"],"b":2,"e":"La base versée est entièrement consommée."},{"q":"On utilise pour verser la solution titrante :","r":["un bécher","une éprouvette non graduée","une pipette jaugée","une burette graduée"],"b":3,"e":"Elle permet de lire le volume versé."},{"q":"Un dosage conductimétrique se repère par :","r":["un changement de pente de la conductance","un changement de couleur de la solution titrée","un pH de 7 exactement","aucun signal mesurable"],"b":0,"e":"Les ions remplacés ont des conductivités différentes."}],"c":"Tle D","m":"chimie","rang":22,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Un lycée de Douala reçoit un lot d'acide chlorhydrique étiqueté 0,1 mol/L. Deux élèves veulent vérifier le titre.","tache":"20 mL d'acide nécessitent 20 mL de soude à 0,1 mol/L. Conclus."},"gratuit":true});
VRT_L("tle-d-chimie-r23",{"duree":25,"titre":"Dosage acide faible - base forte","accroche":"À la demi-équivalence, la courbe donne le pKa.","intro":"Ce dosage est le plus fréquent aux examens. La courbe révèle à la fois la concentration et le pKa.","objectifs":["décrire la courbe","déterminer la concentration","lire le pKa"],"parties":[{"t":"La réaction","html":"<div class='def'><b>Définition</b>La réaction de dosage est totale : <strong>AH + HO⁻ → A⁻ + H₂O</strong>. À l'équivalence, le pH est <strong>supérieur à 7</strong>.</div>"},{"t":"La demi-équivalence","verrou":true},{"t":"Exploiter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":23,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Des sachets d'aspirine reçus par une infirmerie scolaire sont étiquetés 100 mg. Deux élèves veulent vérifier la masse réelle.","tache":"Explique comment un dosage acide-base permet de vérifier l'étiquette."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r24",{"duree":25,"titre":"Dosage base faible - acide fort","accroche":"Une courbe descendante, le même raisonnement.","intro":"Le dosage d'une base faible par un acide fort s'analyse comme celui d'un acide faible.","objectifs":["écrire la réaction","déterminer l'équivalence","lire le pKa"],"parties":[{"t":"La réaction","html":"<div class='def'><b>Définition</b>La réaction de dosage est totale : <strong>B + H₃O⁺ → BH⁺ + H₂O</strong>. À l'équivalence, le pH est <strong>inférieur à 7</strong>.</div>"},{"t":"La courbe","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":24,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Une usine de produits ménagers à Douala veut contrôler la concentration d'une solution ammoniacale.","tache":"Présente les grandes étapes du dosage."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-chimie-r25",{"duree":20,"titre":"Les solutions tampons","accroche":"Pourquoi le pH du sang reste presque constant.","intro":"Une solution tampon résiste aux variations de pH. Elle joue un rôle essentiel dans les organismes.","objectifs":["définir une solution tampon","calculer son pH","citer une préparation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>solution tampon</strong> est une solution dont le pH varie peu par addition modérée d'acide, de base, ou par dilution.</div>"},{"t":"Préparation","verrou":true},{"t":"Rôle biologique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"chimie","rang":25,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Une biologiste d'un laboratoire de Yaoundé doit maintenir un milieu à pH proche de 4,8 pour une culture.","tache":"Propose une solution adaptée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r01",{"duree":20,"titre":"Le concept de relations internationales","accroche":"Le Cameroun n'est pas seul au monde.","intro":"Aucun État ne vit isolé : il échange des biens, des idées, des personnes et des services avec les autres. Ces échanges forment les relations internationales.","objectifs":["définir les relations internationales","identifier leurs acteurs","distinguer leurs domaines"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>relations internationales</strong> sont l'ensemble des rapports (politiques, économiques, culturels, militaires, humanitaires) qui se nouent entre les États et les autres acteurs au-delà des frontières nationales.</div>"},{"t":"Les acteurs","html":"<ul><li><strong>les États</strong>, acteurs principaux, représentés par leurs chefs d'État, ministres des Relations extérieures et ambassadeurs ;</li><li><strong>les organisations internationales</strong> : ONU, Union africaine, CEMAC ;</li><li><strong>les ONG</strong> : Croix-Rouge, Médecins sans frontières ;</li><li><strong>les entreprises multinationales</strong> ;</li><li><strong>les individus</strong> : diaspora, sportifs, artistes.</li></ul>","retenir":"États, organisations, ONG, entreprises, individus.","labo":{"type":"trier","invite":"Choisis un acteur.","items":[["États","acteurs principaux, représentés par les diplomates."],["Organisations internationales","ONU, Union africaine, CEMAC."],["ONG","Croix-Rouge, Médecins sans frontières."],["Multinationales","entreprises présentes dans plusieurs pays."]]}},{"t":"Les domaines et les instruments","html":"<p>Domaines : politique et diplomatique, économique et commercial, culturel et scientifique, militaire et sécuritaire, humanitaire. Instruments : la <strong>diplomatie</strong> (ambassades, consulats, visites officielles), les <strong>traités</strong> et accords, les <strong>organisations</strong> internationales. Au Cameroun, la politique étrangère est définie par le président de la République et mise en œuvre par le ministère des Relations extérieures.</p><div class='attention'><b>Attention</b>ne pas confondre relations internationales (l'ensemble des rapports) et diplomatie (l'instrument de conduite de ces rapports).</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Les relations internationales sont les rapports qui se nouent :</p><ol type='a'><li>entre États et autres acteurs au-delà des frontières</li><li>entre les membres d'une même famille et leurs voisins du quartier</li><li>entre les élèves d'un même lycée</li><li>entre les communes d'un même département</li></ol><details><summary>Voir la réponse</summary><p><strong>entre États et autres acteurs au-delà des frontières</strong>. Elles dépassent le cadre national.</p></details><p><strong>Exercice.</strong></p><p>Cite deux acteurs non étatiques des relations internationales.</p><details><summary>Voir la réponse</summary><p>(Réponse : les ONG, comme la Croix-Rouge, et les entreprises multinationales.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Document : une ONG internationale finance une clinique à Bertoua ; une multinationale exploite le bois de l'Est ; le Cameroun signe un accord commercial avec le Nigeria.</p><p><strong>Consigne 1.</strong> Identifie l'acteur et le domaine de chaque fait.</p><p><strong>Consigne 2.</strong> Montre la diversité des relations internationales.</p><details><summary>Voir une réponse attendue</summary><p>ONG : acteur non étatique, domaine sanitaire et humanitaire ; multinationale : acteur économique ; Cameroun : État, domaine commercial et diplomatique. Les relations internationales mêlent acteurs publics et privés dans des domaines variés.</p></details></div>","retenir":"Savoir-être mobilisé : Ouverture au monde."}],"revision":["Relations internationales : rapports entre États et acteurs au-delà des frontières.","Acteurs : États, organisations, ONG, multinationales, individus.","Instruments : diplomatie, traités, organisations."],"exo":"<p>Cite deux acteurs non étatiques des relations internationales. <em>(Réponse : les ONG, comme la Croix-Rouge, et les entreprises multinationales.)</em></p>","quiz":[{"q":"Les relations internationales sont les rapports qui se nouent :","r":["entre États et autres acteurs au-delà des frontières","entre les membres d'une même famille et leurs voisins du quartier","entre les élèves d'un même lycée","entre les communes d'un même département"],"b":0,"e":"Elles dépassent le cadre national."},{"q":"L'acteur principal des relations internationales est :","r":["la tontine","l'État","le chef de quartier","le syndicat d'enseignants"],"b":1,"e":"Les États restent les acteurs majeurs."},{"q":"Une ONG est :","r":["un organe de l'armée nationale chargé de l'aide","une organisation de l'État","une organisation non gouvernementale","une entreprise publique"],"b":2,"e":"Exemple : la Croix-Rouge."},{"q":"La politique étrangère du Cameroun est définie par :","r":["le maire de Yaoundé, capitale politique","le gouverneur du Centre","le président du Sénat","le président de la République"],"b":3,"e":"Le MINREX la met en œuvre."},{"q":"Le ministère chargé de la diplomatie au Cameroun est :","r":["le ministère des Relations extérieures","le ministère de l'Administration territoriale","le ministère du Commerce","le ministère des Sports"],"b":0,"e":"Le ministère des Relations extérieures (MINREX) met en œuvre la politique étrangère."},{"q":"Un traité est :","r":["une loi votée par une commune","un accord écrit entre États","une décision d'un tribunal local","un discours présidentiel"],"b":1,"e":"Il crée des obligations entre les parties."},{"q":"La diplomatie est :","r":["l'ensemble des relations internationales d'un pays avec les autres","une organisation régionale","l'instrument de conduite des relations entre États","une forme de guerre"],"b":2,"e":"On ne la confond pas avec les relations internationales."},{"q":"Une entreprise multinationale est :","r":["limitée à une seule ville","propriété d'une tontine","un service de l'État","présente dans plusieurs pays"],"b":3,"e":"Elle est un acteur économique international."},{"q":"Un domaine des relations internationales est :","r":["le domaine humanitaire","le domaine familial","le domaine scolaire local","le domaine municipal"],"b":0,"e":"Aide aux victimes de crises."},{"q":"Un footballeur camerounais célèbre à l'étranger est un acteur :","r":["étatique des relations internationales","individuel des relations internationales","judiciaire international","militaire international"],"b":1,"e":"Les individus participent aussi aux échanges."}],"c":"Tle D","m":"ecm","rang":1,"apc":{"module":"Les principes de la diplomatie camerounaise","famille":"Le Cameroun dans le monde","agir":"Défendre les intérêts et l'image du Cameroun dans ses relations avec les autres","situation":"Un footballeur camerounais évoluant en Europe finance une école dans son village ; la même semaine, le ministre des Relations extérieures signe un accord avec un pays voisin et une ONG distribue des vivres aux déplacés de l'Extrême-Nord.","tache":"Identifie l'acteur et le domaine des relations internationales dans chacun des trois faits."},"gratuit":true});
VRT_L("tle-d-ecm-r02",{"duree":20,"titre":"Les aspects et les formes de la coopération internationale","accroche":"Travailler ensemble pour se développer.","intro":"La coopération internationale est la forme pacifique et organisée des relations entre États. Elle peut associer deux pays ou plusieurs, et concerner de nombreux domaines.","objectifs":["définir la coopération internationale","distinguer coopération bilatérale et multilatérale","citer ses domaines"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>coopération internationale</strong> est l'ensemble des actions concertées par lesquelles des États ou des organisations unissent leurs moyens pour atteindre des objectifs communs : développement, paix, échanges.</div>"},{"t":"Les formes","verrou":true},{"t":"Les aspects (domaines)","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":2,"apc":{"module":"Les principes de la diplomatie camerounaise","famille":"Le Cameroun dans le monde","agir":"Défendre les intérêts et l'image du Cameroun dans ses relations avec les autres","situation":"En une année, le Cameroun reçoit des bourses d'études d'un pays asiatique, signe avec ses voisins un accord contre le terrorisme dans le cadre d'une organisation régionale, et la commune d'Ebolowa se jumelle avec une ville européenne.","tache":"Pour chaque fait, identifie la forme et le domaine de coopération, puis montre l'intérêt de cette diversité pour le Cameroun."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r03",{"duree":20,"titre":"Dossier : l'assistance humanitaire","accroche":"Secourir les populations en détresse.","intro":"Conflits, catastrophes et épidémies plongent des populations dans la détresse. L'assistance humanitaire leur apporte un secours immédiat. Le Cameroun en reçoit et en donne.","objectifs":["définir l'assistance humanitaire","citer ses principes et ses acteurs","analyser la situation humanitaire au Cameroun"],"parties":[{"t":"Définition et principes","html":"<div class='def'><b>Définition</b>L'<strong>assistance humanitaire</strong> est l'aide matérielle et médicale apportée d'urgence aux victimes de conflits, de catastrophes naturelles ou d'épidémies pour sauver des vies et soulager les souffrances.</div><p>Principes : <strong>humanité</strong>, <strong>neutralité</strong> (ne pas prendre parti), <strong>impartialité</strong> (aider selon les besoins seuls), <strong>indépendance</strong>.</p>"},{"t":"Les acteurs","verrou":true},{"t":"La situation au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":3,"apc":{"module":"Les principes de la diplomatie camerounaise","famille":"Le Cameroun dans le monde","agir":"Défendre les intérêts et l'image du Cameroun dans ses relations avec les autres","situation":"Après des inondations, 1 200 familles d'un quartier de Maroua sont sans abri ; une ONG ne veut distribuer des vivres qu'aux familles d'une seule religion.","tache":"Explique quel principe humanitaire cette ONG viole et propose trois actions d'assistance d'urgence adaptées."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r04",{"duree":20,"titre":"Les principes de la diplomatie camerounaise","accroche":"Les règles qui guident le Cameroun face au monde.","intro":"Depuis l'indépendance, la diplomatie camerounaise repose sur des principes constants, souvent résumés par le choix de la paix, du dialogue et de l'ouverture.","objectifs":["énoncer les principes de la diplomatie camerounaise","les illustrer par des exemples","identifier les acteurs de la diplomatie"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>diplomatie</strong> est l'art et la pratique de conduire les relations entre États par la négociation. Les <strong>principes de la diplomatie camerounaise</strong> sont les règles fondamentales qui orientent la politique étrangère du pays.</div>"},{"t":"Les principes","verrou":true},{"t":"Les acteurs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":4,"apc":{"module":"Les principes de la diplomatie camerounaise","famille":"Le Cameroun dans le monde","agir":"Défendre les intérêts et l'image du Cameroun dans ses relations avec les autres","situation":"Un pays voisin traverse une crise politique ; certains internautes camerounais demandent que le Cameroun « choisisse un camp » et envoie des troupes soutenir l'opposition de ce pays.","tache":"Explique, à l'aide de deux principes de la diplomatie camerounaise, pourquoi le Cameroun ne peut pas agir ainsi, et propose une attitude conforme à ces principes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r05",{"duree":20,"titre":"Le Cameroun et l'Organisation des Nations unies","accroche":"Membre de l'ONU depuis le 20 septembre 1960.","intro":"L'ONU est la grande organisation de la coopération mondiale. Le Cameroun, dont l'indépendance a été préparée sous tutelle de l'ONU, y est admis le 20 septembre 1960.","objectifs":["présenter l'ONU","décrire les relations entre le Cameroun et l'ONU","citer les institutions spécialisées présentes au Cameroun"],"parties":[{"t":"L'ONU","html":"<div class='def'><b>Définition</b>L'<strong>Organisation des Nations unies</strong> (ONU) est une organisation internationale créée le 24 octobre 1945 par la Charte de San Francisco pour maintenir la paix et la sécurité internationales et favoriser la coopération entre les nations.</div><p>Ses organes principaux : l'<strong>Assemblée générale</strong>, le <strong>Conseil de sécurité</strong>, le <strong>Secrétariat</strong>, la <strong>Cour internationale de justice</strong>, le <strong>Conseil économique et social</strong>.</p>"},{"t":"Le Cameroun à l'ONU","verrou":true},{"t":"Les agences de l'ONU au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":5,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Dans ton village de l'Adamaoua, une campagne de vaccination est appuyée par l'OMS et l'UNICEF, et la cantine de l'école reçoit des vivres du PAM ; un habitant affirme que « l'ONU ne sert à rien pour nous ».","tache":"Montre-lui, à l'aide de ces exemples et du cours, trois apports de l'ONU au Cameroun."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r06",{"duree":20,"titre":"Dossier : la participation du Cameroun aux missions des Nations unies","accroche":"Les Casques bleus camerounais.","intro":"Le Cameroun contribue au maintien de la paix en envoyant des militaires et des policiers dans les missions de l'ONU, notamment en République centrafricaine.","objectifs":["définir une opération de maintien de la paix","présenter la participation camerounaise","évaluer ses apports et ses difficultés"],"parties":[{"t":"Les opérations de maintien de la paix","html":"<div class='def'><b>Définition</b>Une <strong>opération de maintien de la paix</strong> est une mission décidée par le Conseil de sécurité de l'ONU, qui déploie des militaires, des policiers et des civils (les Casques bleus) pour protéger les civils et aider un pays à sortir d'un conflit.</div>"},{"t":"La participation camerounaise","verrou":true},{"t":"Apports et difficultés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":6,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Un sous-officier de Ngaoundéré, de retour d'une mission en Centrafrique, raconte avoir escorté des convois humanitaires et protégé un camp de déplacés ; son jeune frère se demande « pourquoi risquer sa vie chez les autres ».","tache":"Explique deux intérêts de cette participation pour le Cameroun et deux pour la population centrafricaine."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r07",{"duree":20,"titre":"Le Cameroun et l'Union européenne","accroche":"Un partenaire commercial et financier majeur.","intro":"L'Union européenne est l'un des principaux partenaires commerciaux et financiers du Cameroun. Leur coopération repose sur des accords successifs et sur l'Accord de partenariat économique.","objectifs":["présenter l'Union européenne","décrire les domaines de coopération","analyser l'Accord de partenariat économique"],"parties":[{"t":"L'Union européenne","html":"<div class='def'><b>Définition</b>L'<strong>Union européenne</strong> (UE) est une union politique et économique de pays européens, qui partagent un marché commun et des institutions communes (Commission, Parlement, Conseil).</div><p>Le Cameroun coopère avec elle dans le cadre des accords entre l'UE et les pays d'Afrique, des Caraïbes et du Pacifique : accords de Lomé, puis de <strong>Cotonou</strong> (2000).</p>"},{"t":"Les domaines de coopération","verrou":true},{"t":"L'Accord de partenariat économique (APE)","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":7,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Une coopérative de bananes de la région du Moungo exporte vers l'Europe sans droits de douane, mais une usine de jus de Douala se plaint de la concurrence de jus européens importés à bas prix.","tache":"À partir de ces deux exemples, présente un avantage et un inconvénient de l'APE, puis propose une mesure pour en tirer davantage profit."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r08",{"duree":20,"titre":"Le Cameroun, la Francophonie, le Commonwealth et l'Organisation de la coopération islamique","accroche":"Trois réseaux, une même ouverture.","intro":"Grâce à son héritage bilingue et à la diversité de sa population, le Cameroun appartient à la fois à la Francophonie, au Commonwealth et à l'Organisation de la coopération islamique.","objectifs":["présenter ces trois organisations","expliquer l'appartenance du Cameroun","identifier les avantages pour le pays"],"parties":[{"t":"L'Organisation internationale de la Francophonie","html":"<div class='def'><b>Définition</b>L'<strong>Organisation internationale de la Francophonie</strong> (OIF) regroupe des États et gouvernements ayant le français en partage, pour promouvoir la langue française, la diversité culturelle, la paix, la démocratie et l'éducation.</div><p>Le Cameroun en est membre ; il bénéficie de programmes d'éducation, de formation et d'observation électorale, et accueille des institutions comme l'Agence universitaire de la Francophonie.</p>"},{"t":"Le Commonwealth","verrou":true},{"t":"L'Organisation de la coopération islamique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":8,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Ton camarade affirme qu'appartenir à la fois à la Francophonie et au Commonwealth est « contradictoire » et qu'il faudrait choisir l'une des deux organisations.","tache":"Réfute son affirmation en trois arguments tirés du cours."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r09",{"duree":20,"titre":"Le Cameroun et la France, le Cameroun et la Grande-Bretagne","accroche":"Deux partenaires hérités de l'histoire.","intro":"Anciennes puissances de tutelle, la France et la Grande-Bretagne restent des partenaires importants du Cameroun dans de nombreux domaines, dans le cadre d'une coopération entre États souverains.","objectifs":["présenter l'histoire de ces relations","décrire les domaines de coopération","porter un regard critique sur ces relations"],"parties":[{"t":"L'héritage historique","html":"<div class='def'><b>Définition</b>La <strong>coopération bilatérale</strong> est la relation organisée entre deux États. Avec la France et la Grande-Bretagne, elle prolonge des liens historiques : protectorat allemand jusqu'en 1916, puis partage du territoire entre la France et la Grande-Bretagne sous mandat de la SDN puis sous tutelle de l'ONU.</div>"},{"t":"Le Cameroun et la France","verrou":true},{"t":"Le Cameroun et la Grande-Bretagne","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":9,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Un article indique qu'une partie de la dette du Cameroun envers la France a été convertie en financements de routes, d'écoles et de projets agricoles ; un internaute y voit « un cadeau sans contrepartie ».","tache":"Explique le mécanisme du C2D et montre ses avantages et ses limites pour le Cameroun."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r10",{"duree":20,"titre":"Le Cameroun et les pays asiatiques : la Chine, le Japon","accroche":"Des partenaires venus de l'Est.","intro":"Depuis quelques décennies, l'Asie occupe une place croissante dans les relations du Cameroun, notamment la Chine pour les infrastructures et le Japon pour l'aide technique.","objectifs":["décrire la coopération sino-camerounaise","décrire la coopération nippo-camerounaise","évaluer ces partenariats"],"parties":[{"t":"Le Cameroun et la Chine","html":"<div class='def'><b>Définition</b>La <strong>coopération sino-camerounaise</strong> est la relation entre le Cameroun et la République populaire de Chine, avec laquelle il a établi des relations diplomatiques le 26 mars 1971.</div><ul><li>infrastructures : Palais des Congrès et Palais polyvalent des sports de Yaoundé, barrage de Memve'ele, port en eau profonde de Kribi, routes ;</li><li>prêts et dons ;</li><li>bourses, Institut Confucius et coopération médicale ;</li><li>commerce : la Chine est devenue l'un des premiers partenaires commerciaux du Cameroun.</li></ul>"},{"t":"Le Cameroun et le Japon","verrou":true},{"t":"Évaluation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":10,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Sur un chantier routier financé par un prêt étranger à l'Est du Cameroun, un tiers seulement des ouvriers sont camerounais ; les jeunes du village réclament des emplois.","tache":"Analyse deux avantages et deux limites de ce type de coopération et propose deux clauses à exiger dans les futurs accords."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r11",{"duree":20,"titre":"Le Cameroun et les pays d'Amérique : les États-Unis, le Brésil","accroche":"Coopérer avec l'Amérique du Nord et du Sud.","intro":"Les États-Unis sont un partenaire politique, sécuritaire et économique du Cameroun ; le Brésil, grand pays du Sud, est un partenaire de la coopération Sud-Sud.","objectifs":["décrire la coopération avec les États-Unis","décrire la coopération avec le Brésil","comparer ces deux partenariats"],"parties":[{"t":"Le Cameroun et les États-Unis","html":"<div class='def'><b>Définition</b>La <strong>coopération américano-camerounaise</strong> est la relation bilatérale entre le Cameroun et les États-Unis d'Amérique, qui couvre les domaines politique, sécuritaire, commercial, sanitaire et éducatif.</div><ul><li>commerce dans le cadre de l'<strong>AGOA</strong> (loi américaine de 2000 sur la croissance et les opportunités en Afrique), qui ouvre le marché américain à certains produits africains ;</li><li>santé : lutte contre le VIH-sida et le paludisme ;</li><li>éducation : bourses et volontaires du Corps de la paix ;</li><li>sécurité : appui à la lutte contre le terrorisme.</li></ul>"},{"t":"Le Cameroun et le Brésil","verrou":true},{"t":"Comparer les partenariats","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":11,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Une entreprise de Douala qui exporte des vêtements vers les États-Unis grâce à l'AGOA craint de perdre cet avantage ; un groupe d'agriculteurs de l'Ouest souhaite profiter de l'expérience brésilienne sur le café et le soja.","tache":"Explique la nature de chacune des deux coopérations et propose une action pour sécuriser ou développer chacune d'elles."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r12",{"duree":20,"titre":"Dossier : l'aide au développement","accroche":"Une aide utile, à condition d'être bien utilisée.","intro":"Le Cameroun reçoit des aides de ses partenaires pour financer son développement. Ce dossier analyse leurs formes, leurs apports et leurs limites.","objectifs":["définir l'aide au développement","en distinguer les formes","analyser ses effets"],"parties":[{"t":"Définition et formes","html":"<div class='def'><b>Définition</b>L'<strong>aide publique au développement</strong> est l'ensemble des ressources (dons et prêts à conditions favorables) fournies par des États ou des organisations à des pays en développement pour améliorer le bien-être de leur population.</div><ul><li><strong>dons</strong> : sommes non remboursables ;</li><li><strong>prêts concessionnels</strong> : taux faibles, longues durées ;</li><li><strong>aide technique</strong> : experts, formations ;</li><li><strong>aide en nature</strong> : vivres, médicaments, matériel ;</li><li><strong>allègement de la dette</strong>.</li></ul>"},{"t":"Les bailleurs","verrou":true},{"t":"Apports et limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":12,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Un projet d'adduction d'eau de 900 millions de F, financé par un bailleur, a démarré avec deux ans de retard à cause de la lenteur des fonds de contrepartie nationaux et d'une passation de marché contestée ; le village attend toujours l'eau potable.","tache":"Analyse deux causes et deux conséquences de ce retard, puis propose deux mesures pour améliorer l'efficacité de l'aide."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r13",{"duree":20,"titre":"Le Cameroun et l'Union africaine","accroche":"Membre fondateur de l'unité africaine.","intro":"Membre fondateur de l'Organisation de l'unité africaine en 1963, le Cameroun participe à l'Union africaine qui lui a succédé en 2002.","objectifs":["présenter l'OUA et l'UA","citer les organes de l'UA","décrire la contribution du Cameroun"],"parties":[{"t":"De l'OUA à l'UA","html":"<div class='def'><b>Définition</b>L'<strong>Union africaine</strong> (UA) est l'organisation panafricaine qui regroupe les États africains pour promouvoir l'unité, la paix, la sécurité et le développement du continent. Elle a été lancée à Durban le 9 juillet 2002 et a son siège à Addis-Abeba.</div><p>Elle a succédé à l'<strong>Organisation de l'unité africaine</strong> (OUA), créée le 25 mai 1963 à Addis-Abeba, dont le Cameroun était membre fondateur.</p>"},{"t":"Les organes et les objectifs","verrou":true},{"t":"La contribution du Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":13,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"La zone de libre-échange continentale africaine doit permettre à une entreprise de jus de fruits de Bafoussam de vendre au Kenya ou au Sénégal avec des droits de douane réduits ; son directeur hésite à investir.","tache":"Présente deux objectifs de l'UA liés à ce projet et deux conditions pour que l'entreprise en profite."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r14",{"duree":20,"titre":"Le Cameroun dans sa sous-région","accroche":"Le Cameroun, carrefour de l'Afrique centrale.","intro":"Par sa position, sa population et son économie, le Cameroun joue un rôle central en Afrique centrale. Il appartient à plusieurs organisations sous-régionales.","objectifs":["citer les organisations sous-régionales du Cameroun","décrire leurs objectifs","évaluer la place du Cameroun et les obstacles à l'intégration"],"parties":[{"t":"Les organisations","html":"<div class='def'><b>Définition</b>L'<strong>intégration sous-régionale</strong> est le processus par lequel des États voisins mettent en commun des politiques et des institutions pour former un espace économique et politique plus uni.</div><ul><li>la <strong>CEMAC</strong> (Communauté économique et monétaire de l'Afrique centrale), créée en 1994, siège à Bangui : Cameroun, Centrafrique, Congo, Gabon, Guinée équatoriale, Tchad ; monnaie commune (franc CFA) gérée par la <strong>BEAC</strong>, dont le siège est à Yaoundé ;</li><li>la <strong>CEEAC</strong> (Communauté économique des États de l'Afrique centrale), créée en 1983 ;</li><li>la <strong>Commission du bassin du lac Tchad</strong> ;</li><li>la <strong>Commission du golfe de Guinée</strong>.</li></ul>"},{"t":"La place du Cameroun","verrou":true},{"t":"Les obstacles à l'intégration","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":14,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Une commerçante de Kye-Ossi, à la frontière du Gabon et de la Guinée équatoriale, se plaint de contrôles multiples et de paiements non officiels qui allongent son trajet de vingt-quatre heures.","tache":"Identifie l'obstacle à l'intégration illustré par ce cas et propose trois solutions."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r15",{"duree":20,"titre":"Dossier : le COPAX, Conseil de paix et de sécurité de l'Afrique centrale","accroche":"Prévenir et gérer les conflits entre voisins.","intro":"Pour faire face aux crises de la sous-région, les États de la CEEAC ont créé le Conseil de paix et de sécurité de l'Afrique centrale (COPAX), dont le protocole a été signé à Malabo le 24 février 2000.","objectifs":["présenter le COPAX","décrire ses organes","évaluer son action"],"parties":[{"t":"Présentation","html":"<div class='def'><b>Définition</b>Le <strong>COPAX</strong> est le mécanisme de la CEEAC chargé de la promotion, du maintien et de la consolidation de la paix et de la sécurité en Afrique centrale.</div><p>Son protocole a été signé à <strong>Malabo</strong> le 24 février 2000. Le Cameroun en est membre.</p>"},{"t":"Les organes techniques","verrou":true},{"t":"Action et limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":15,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Des pirates attaquent des chalutiers au large du golfe de Guinée ; les pêcheurs de Limbé et d'Idenau ne sortent plus en mer et le prix du poisson augmente au marché.","tache":"Montre en quoi le COPAX peut contribuer à résoudre ce problème et propose deux mesures sous-régionales."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r16",{"duree":20,"titre":"TD : la contribution du Cameroun dans la gestion des conflits en Afrique","accroche":"Médiateur, soldat de la paix, terre d'accueil.","intro":"Ce travail dirigé recense et analyse les actions du Cameroun pour prévenir et gérer les conflits en Afrique, en s'appuyant sur des exemples concrets.","objectifs":["recenser les formes de contribution","analyser des exemples","rédiger une synthèse argumentée"],"parties":[{"t":"Les formes de contribution","html":"<div class='def'><b>Définition</b>La <strong>gestion des conflits</strong> est l'ensemble des actions destinées à prévenir une crise, à y mettre fin et à reconstruire la paix.</div><ul><li>le <strong>règlement pacifique</strong> de ses propres différends (Bakassi) ;</li><li>l'envoi de <strong>contingents</strong> dans les missions de paix (MINUSCA) ;</li><li>la <strong>lutte commune</strong> contre Boko Haram au sein de la Force multinationale mixte ;</li><li>l'<strong>accueil des réfugiés</strong> centrafricains et nigérians ;</li><li>la <strong>formation</strong> des personnels de paix à l'EIFORCES ;</li><li>la participation au COPAX et au Conseil de paix et de sécurité de l'UA.</li></ul>"},{"t":"Analyser un exemple","verrou":true},{"t":"Rédiger la synthèse","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":16,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Ton professeur te demande de préparer, pour l'exposé de la semaine prochaine, une fiche sur « le Cameroun, acteur de paix en Afrique » ; tu disposes d'une heure et de trois exemples : Bakassi, la MINUSCA et le camp de Minawao.","tache":"Propose un plan détaillé de l'exposé et rédige l'introduction en cinq lignes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-ecm-r17",{"duree":20,"titre":"Dossier : les problèmes du Cameroun dans les relations internationales","accroche":"Les défis d'un pays ouvert sur le monde.","intro":"Malgré ses atouts, le Cameroun rencontre des difficultés économiques, politiques et sécuritaires dans ses relations avec le reste du monde. Ce dossier les analyse, comme le demandent les sujets du baccalauréat.","objectifs":["identifier les problèmes du Cameroun dans les relations internationales","en expliquer les causes et les conséquences","proposer des solutions"],"parties":[{"t":"Les problèmes économiques","html":"<div class='def'><b>Définition</b>Un <strong>problème du Cameroun dans les relations internationales</strong> est une difficulté qui limite sa capacité à défendre ses intérêts ou à tirer profit de ses échanges avec les autres.</div><ul><li><strong>la dépendance aux matières premières</strong> (pétrole, cacao, bois) dont les prix varient ;</li><li><strong>l'endettement</strong> extérieur ;</li><li><strong>le déséquilibre de la balance commerciale</strong> : importations supérieures aux exportations ;</li><li><strong>la faible transformation locale</strong> des produits ;</li><li><strong>les conditions imposées</strong> par certains bailleurs.</li></ul>"},{"t":"Les problèmes politiques et sécuritaires","verrou":true},{"t":"Des solutions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"ecm","rang":17,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Un tableau indique que le Cameroun exporte surtout du pétrole brut, du cacao en fèves et du bois, et importe des produits manufacturés, du riz et du poisson congelé ; lorsque le cours du cacao baisse, les revenus des planteurs du Centre et du Sud-Ouest chutent.","tache":"Analyse deux problèmes économiques révélés par ce tableau (causes et conséquences) et propose deux solutions."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r01",{"duree":20,"titre":"Écriture algébrique et calculs dans ℂ","accroche":"Un nombre dont le carré vaut −1 ouvre un monde nouveau.","intro":"Dans ℝ, l'équation x² = −1 n'a pas de solution. Les nombres complexes sont nés pour la résoudre.","objectifs":["écrire un complexe sous forme algébrique","additionner et multiplier","calculer un quotient"],"parties":[{"t":"L'ensemble ℂ","html":"<div class='def'><b>Définition</b>Un <strong>nombre complexe</strong> s'écrit de façon unique <strong>z = a + ib</strong>, avec a et b réels et i² = −1. a est la partie réelle, b la partie imaginaire.</div>"},{"t":"Les calculs","html":"<p class='formule'>(2 + 3i)(1 − i) = 2 − 2i + 3i − 3i² = 5 + i</p><p>Deux complexes sont égaux si leurs parties réelles et imaginaires sont égales.</p>","retenir":"On calcule comme dans ℝ, en remplaçant i² par −1.","labo":{"type":"complexe","a":3,"b":4}},{"t":"Le quotient","html":"<p>On multiplie par le conjugué du dénominateur :</p><p class='formule'>1 / (1 + i) = (1 − i) / 2 = 1/2 − (1/2)i</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> i² vaut :</p><ol type='a'><li>−1</li><li>1</li><li>i</li><li>0</li></ol><details><summary>Voir la réponse</summary><p><strong>−1</strong>. C'est la propriété qui définit le nombre i.</p></details><p><strong>Exercice.</strong></p><p>Écris (3 − i)² sous forme algébrique.</p><details><summary>Voir la réponse</summary><p>(Réponse : 8 − 6i.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Deux dipôles d'impédances Z₁ = 2 − 3i et Z₂ = 1 + 2i sont montés en parallèle ; l'impédance équivalente vaut Z = Z₁Z₂/(Z₁ + Z₂).</p><p><strong>Tâche 1.</strong> Calcule Z₁Z₂ et Z₁/Z₂ sous forme algébrique.</p><p><strong>Tâche 2.</strong> Calcule Z sous forme algébrique.</p><details><summary>Voir une réponse attendue</summary><p>Z₁Z₂ = 2 + 4i − 3i + 6 = 8 + i. Z₁/Z₂ = (2 − 3i)(1 − 2i)/5 = (−4 − 7i)/5. Z₁ + Z₂ = 3 − i ; Z = (8 + i)(3 + i)/10 = (23 + 11i)/10 = 2,3 + 1,1i.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["z = a + ib ; i² = −1.","Égalité : parties réelles et imaginaires.","Quotient : conjugué du dénominateur."],"exo":"<p>Écris (3 − i)² sous forme algébrique. <em>(Réponse : 8 − 6i.)</em></p>","quiz":[{"q":"i² vaut :","r":["−1","1","i","0"],"b":0,"e":"C'est la propriété qui définit le nombre i."},{"q":"La partie réelle de z = 3 − 2i est :","r":["−2","3","2","−2i"],"b":1,"e":"z = a + ib avec a = 3 et b = −2."},{"q":"La partie imaginaire de z = 3 − 2i est :","r":["3","−2i","−2","2"],"b":2,"e":"La partie imaginaire est le réel b, sans le i."},{"q":"(2 + i) + (1 − 3i) vaut :","r":["3 + 4i","1 + 4i","2 − 3i","3 − 2i"],"b":3,"e":"On additionne séparément parties réelles et imaginaires."},{"q":"(2 + i)(1 − i) vaut :","r":["3 − i","2 − i","3 + i","1 − i"],"b":0,"e":"2 − 2i + i − i² = 2 − i + 1 = 3 − i."},{"q":"(1 + i)² vaut :","r":["2","2i","1 + i²","0"],"b":1,"e":"1 + 2i + i² = 1 + 2i − 1 = 2i."},{"q":"i³ vaut :","r":["i","1","−i","−1"],"b":2,"e":"i³ = i² × i = −i."},{"q":"i⁴ vaut :","r":["−1","i","−i","1"],"b":3,"e":"i⁴ = (i²)² = (−1)² = 1."},{"q":"Un nombre complexe z est réel si et seulement si :","r":["sa partie imaginaire est nulle","sa partie réelle est nulle","son module vaut 1","z = i"],"b":0,"e":"z = a + 0i = a."},{"q":"Un nombre complexe z est imaginaire pur si :","r":["sa partie imaginaire est nulle","sa partie réelle est nulle","z est réel","z = 1"],"b":1,"e":"z = ib avec b réel."}],"c":"Tle D","m":"maths","rang":1,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un ingénieur stagiaire à la centrale de Song Loulou note une impédance sous la forme 3 + 4i et doit la multiplier par 1 − i pour un calcul de circuit.","tache":"Effectue le produit sous forme algébrique."},"gratuit":true});
VRT_L("tle-d-maths-r02",{"duree":15,"titre":"Les nombres complexes conjugués","accroche":"Un simple changement de signe, et le produit devient réel.","intro":"Le conjugué d'un complexe est un outil de calcul, notamment pour les quotients.","objectifs":["calculer un conjugué","utiliser ses propriétés","reconnaître un réel ou un imaginaire pur"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>conjugué</strong> de z = a + ib est <strong>z̄ = a − ib</strong>.</div>"},{"t":"Propriétés","verrou":true},{"t":"Caractériser un complexe","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":2,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un technicien en formation dans un poste électrique de Bafoussam obtient l'impédance Z = (3 + 4i)/(1 − 2i) + (3 − 4i)/(1 + 2i) et affirme que le résultat est réel.","tache":"Dis quel critère utiliser avec le conjugué et vérifie son affirmation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r03",{"duree":15,"titre":"Le module d'un nombre complexe","accroche":"La longueur cachée derrière un nombre complexe.","intro":"Le module mesure la distance d'un point à l'origine. Il joue le rôle de la valeur absolue dans ℂ.","objectifs":["calculer un module","utiliser ses propriétés","interpréter géométriquement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>module</strong> de z = a + ib est <strong>|z| = √(a² + b²)</strong>.</div><div class='ex'><b>Exemple</b>|3 + 4i| = 5.</div>"},{"t":"Propriétés","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":3,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sur le plan d'un quartier de Douala, une antenne est au point d'affixe 2 + i et un client à 5 + 5i, en kilomètres.","tache":"Calcule la distance entre l'antenne et le client."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r04",{"duree":25,"titre":"Équations de degré 2 et 3 dans ℂ","accroche":"Dans ℂ, toute équation du second degré a des solutions.","intro":"Le discriminant négatif n'est plus un obstacle : les racines deviennent complexes.","objectifs":["résoudre une équation de degré 2","factoriser une équation de degré 3","vérifier ses solutions"],"parties":[{"t":"Degré 2","html":"<div class='def'><b>Théorème</b>L'équation az² + bz + c = 0, à coefficients réels et Δ = b² − 4ac < 0, admet deux solutions conjuguées : <strong>z = (−b ± i√|Δ|) / 2a</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Degré 3","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":4,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour un logo à trois branches identiques, une graphiste de Mbouda place trois points sur un cercle de rayon 1, aux images des solutions de z³ = 1.","tache":"Résous z³ − 1 = 0 et donne la nature du triangle obtenu."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r05",{"duree":20,"titre":"Limites des fonctions trigonométriques et irrationnelles","accroche":"Quand x approche 0, sin x ressemble à x.","intro":"Les formes indéterminées se résolvent avec des limites de référence ou l'expression conjuguée.","objectifs":["utiliser les limites de référence","lever une indétermination","utiliser l'expression conjuguée"],"parties":[{"t":"Limites de référence","html":"<div class='def'><b>Limites à connaître</b>En 0 : <strong>sin x / x → 1</strong>, <strong>(1 − cos x) / x² → 1/2</strong>, <strong>tan x / x → 1</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Fonctions irrationnelles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":5,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour vérifier un calcul d'angle très petit sur un chantier à Limbé, un technicien remplace sin x par x.","tache":"Justifie cette approximation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r06",{"duree":20,"titre":"Fonction continue sur un intervalle","accroche":"Une courbe qu'on trace sans lever le crayon garantit une solution.","intro":"Le théorème des valeurs intermédiaires assure l'existence de solutions sans même les calculer.","objectifs":["définir la continuité","appliquer le théorème des valeurs intermédiaires","encadrer une solution"],"parties":[{"t":"Continuité","html":"<div class='def'><b>Définition</b>f est <strong>continue en a</strong> si lim (x→a) f(x) = f(a). Elle est continue sur un intervalle si elle l'est en tout point.</div>"},{"t":"Théorème des valeurs intermédiaires","verrou":true},{"t":"Dichotomie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":6,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un technicien cherche à quel instant la température d'une chambre froide, à Douala, atteint exactement 4 °C entre deux relevés.","tache":"Dis pourquoi on est sûr qu'un tel instant existe, si la température varie de façon continue."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r07",{"duree":20,"titre":"Fonction continue et strictement monotone","accroche":"Avec la monotonie, la solution devient unique.","intro":"La continuité donne l'existence ; la stricte monotonie donne l'unicité.","objectifs":["énoncer le théorème de la bijection","prouver l'unicité","donner l'intervalle image"],"parties":[{"t":"Le théorème","html":"<div class='def'><b>Théorème</b>Si f est <strong>continue et strictement monotone</strong> sur un intervalle I, alors f réalise une <strong>bijection</strong> de I sur J = f(I).</div>"},{"t":"Conséquence","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":7,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sur le marché du cacao de Kumba, l'offre vaut f(p) = p³ + p − 10 (en tonnes) selon le prix p (en milliers de F/kg) ; l'équilibre est atteint quand f(p) = 0, pour p entre 1 et 3.","tache":"Montre que ce prix d'équilibre existe et est unique, puis encadre-le à 0,1 près."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r08",{"duree":25,"titre":"Dérivabilité de la réciproque et accroissements finis","accroche":"Encadrer une différence sans la calculer.","intro":"Deux résultats puissants : la dérivée d'une fonction réciproque, et un encadrement fondé sur la dérivée.","objectifs":["dériver une réciproque","énoncer les inégalités des accroissements finis","appliquer à un encadrement"],"parties":[{"t":"La réciproque","html":"<div class='def'><b>Formule</b>Si f est bijective, dérivable et si f'(f⁻¹(y)) ≠ 0, alors <strong>(f⁻¹)'(y) = 1 / f'(f⁻¹(y))</strong>.</div>"},{"t":"Accroissements finis","verrou":true},{"t":"Application","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":8,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sans calculatrice, un candidat doit encadrer √101 lors d'une épreuve pratique.","tache":"Utilise l'inégalité des accroissements finis."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r09",{"duree":25,"titre":"Représentations graphiques des fonctions","accroche":"Une courbe entière se devine à partir de quelques détails.","intro":"Dérivée, limites, asymptotes et symétries permettent de construire une courbe avec précision.","objectifs":["étudier une fonction","trouver des asymptotes","exploiter une symétrie"],"parties":[{"t":"Plan d'étude","html":"<div class='def'><b>Méthode</b>L'<strong>étude d'une fonction</strong> comporte : domaine, limites, dérivée, tableau de variation, asymptotes, points remarquables, tracé.</div>"},{"t":"Asymptotes","verrou":true},{"t":"Symétries","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":9,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un lycéen de Bertoua doit représenter le coût moyen d'une production, modélisé par x + 1/x, afin de trouver son minimum.","tache":"Dis pour quelle valeur positive le coût est minimal."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r10",{"duree":20,"titre":"Tableaux d'effectifs et nuage de points","accroche":"Deux séries, un nuage de points, une tendance.","intro":"Pour relier deux caractères, on place les données dans un repère et on observe leur forme.","objectifs":["construire un nuage de points","calculer le point moyen","lire un tableau à double entrée"],"parties":[{"t":"Le nuage de points","html":"<div class='def'><b>Définition</b>Pour une série double (xᵢ ; yᵢ), le <strong>nuage de points</strong> est l'ensemble des points Mᵢ(xᵢ ; yᵢ).</div>"},{"t":"Le point moyen","verrou":true},{"t":"Tableau à double entrée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":10,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une coopérative de Foumban note, sur 5 mois, l'engrais utilisé et la récolte de café obtenue.","tache":"Calcule le point moyen pour x : 1, 2, 3, 4, 5 et y : 2, 3, 5, 6, 9."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r11",{"duree":25,"titre":"Ajustements linéaires","accroche":"Trouver la droite qui résume des données pour prévoir l'avenir.","intro":"Une droite d'ajustement permet de faire une prévision à partir d'une tendance observée.","objectifs":["calculer covariance et coefficient","écrire la droite de régression","faire une prévision"],"parties":[{"t":"La droite des moindres carrés","html":"<div class='def'><b>Formules</b>La <strong>droite de régression</strong> de y en x passe par G : <strong>y − ȳ = a(x − x̄)</strong>, avec <strong>a = cov(x ; y) / V(x)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Corrélation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":11,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La même coopérative veut prévoir la récolte si elle consacre 6 unités d'engrais.","tache":"Calcule l'estimation avec y = 1,7x − 0,1."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r12",{"duree":20,"titre":"Le raisonnement par récurrence","accroche":"Comme une rangée de dominos : le premier tombe, tous tombent.","intro":"Pour prouver une propriété valable pour tout entier, il suffit de deux étapes.","objectifs":["rédiger une récurrence","prouver une formule","éviter les erreurs de rédaction"],"parties":[{"t":"Le principe","html":"<div class='def'><b>Principe</b>Pour démontrer P(n) pour tout n ≥ n₀ : <strong>initialisation</strong>, P(n₀) est vraie ; <strong>hérédité</strong>, si P(n) est vraie, alors P(n + 1) l'est aussi.</div>"},{"t":"Exemple","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":12,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour la cérémonie de fin d'année à Yaoundé, on dispose des chaises : 1 au premier rang, 2 au deuxième, et ainsi de suite.","tache":"Exprime le nombre total pour n rangs et justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r13",{"duree":20,"titre":"Suites monotones et suites bornées","accroche":"Une suite qui monte sans dépasser un plafond finit par se stabiliser.","intro":"Connaître le sens de variation et les bornes d'une suite renseigne sur son comportement.","objectifs":["étudier le sens de variation","majorer ou minorer","utiliser le théorème de convergence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>Une suite est <strong>croissante</strong> si uₙ₊₁ ≥ uₙ pour tout n. Elle est <strong>majorée</strong> par M si uₙ ≤ M pour tout n.</div>"},{"t":"Étudier le sens","verrou":true},{"t":"Le théorème","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":13,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"L'épargne d'une tontine de Bafia augmente chaque mois, mais la caisse est plafonnée.","tache":"Dis ce que l'on peut déduire si le montant mensuel forme une suite croissante et majorée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r14",{"duree":25,"titre":"Convergence de suites définies par récurrence","accroche":"uₙ₊₁ = f(uₙ) : où va la suite ?","intro":"Une suite auxiliaire géométrique permet souvent de calculer directement la limite.","objectifs":["trouver un point fixe","introduire une suite auxiliaire","calculer une limite"],"parties":[{"t":"Le point fixe","html":"<div class='def'><b>Propriété</b>Si uₙ₊₁ = f(uₙ) converge vers L et si f est continue en L, alors <strong>L = f(L)</strong>.</div>"},{"t":"La suite auxiliaire","verrou":true},{"t":"La limite","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":14,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un réservoir à Maroua, on retire la moitié de l'eau chaque jour, puis on ajoute 1 000 L.","tache":"Dis vers quel volume se stabilise le réservoir."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r15",{"duree":15,"titre":"Graphes : le vocabulaire","accroche":"Des villes et des routes deviennent des points et des traits.","intro":"Les graphes modélisent des réseaux de routes, de téléphone ou d'amis.","objectifs":["définir sommet et arête","calculer un degré","lire une matrice d'adjacence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>Un <strong>graphe</strong> est un ensemble de <strong>sommets</strong> reliés par des <strong>arêtes</strong>. Le <strong>degré</strong> d'un sommet est le nombre d'arêtes qui en partent.</div>"},{"t":"Propriété","verrou":true},{"t":"La matrice d'adjacence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":15,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une société de transport relie Douala, Yaoundé, Bafoussam et Kribi selon quatre liaisons directes.","tache":"Représente ce réseau et calcule la somme des degrés."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r16",{"duree":25,"titre":"Graphes : propriétés et algorithmes","accroche":"Trouver le plus court chemin entre deux villes.","intro":"Euler, en se promenant, a posé les bases de la théorie des graphes. Dijkstra a formalisé la recherche du plus court chemin.","objectifs":["appliquer le théorème d'Euler","utiliser l'algorithme de Dijkstra","interpréter un résultat"],"parties":[{"t":"Le théorème d'Euler","html":"<div class='def'><b>Théorème</b>Un graphe connexe admet une <strong>chaîne eulérienne</strong> s'il a 0 ou 2 sommets de degré impair. Il admet un <strong>cycle eulérien</strong> s'il en a 0.</div>"},{"t":"Le plus court chemin","verrou":true},{"t":"Lire le résultat","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":16,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un livreur à Yaoundé doit emprunter toutes les rues d'un quartier une seule fois.","tache":"Dis quelle condition sur les degrés rend cela possible."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r17",{"duree":15,"titre":"Image et affixe d'un nombre complexe","accroche":"Chaque complexe a son adresse dans le plan.","intro":"Les nombres complexes se lisent dans le plan : ils relient calcul et géométrie.","objectifs":["placer l'image d'un complexe","calculer l'affixe d'un vecteur","calculer l'affixe d'un milieu"],"parties":[{"t":"Image et affixe","html":"<div class='def'><b>Définition</b>Dans un repère orthonormé, le point M(a ; b) est l'<strong>image</strong> de z = a + ib, et z est l'<strong>affixe</strong> de M.</div>"},{"t":"Vecteurs","verrou":true},{"t":"Milieu et barycentre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":17,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sur le plan d'un champ de Foumban, on repère deux bornes par des affixes pour placer un puits à mi-distance.","tache":"Donne l'affixe du puits, si les bornes sont 1 + i et 3 − i."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r18",{"duree":25,"titre":"Forme trigonométrique et notation exponentielle","accroche":"Avec eⁱᶿ, multiplier revient à tourner.","intro":"La forme exponentielle rend les produits et les puissances très simples.","objectifs":["calculer un argument","écrire la forme exponentielle","appliquer la formule de Moivre"],"parties":[{"t":"Forme trigonométrique","html":"<div class='def'><b>Définition</b>Tout complexe non nul s'écrit <strong>z = r(cos θ + i sin θ) = r eⁱᶿ</strong>, où r = |z| et θ est un argument de z.</div><div class='ex'><b>Exemple</b>1 + i = √2 e^(iπ/4).</div>"},{"t":"Règles de calcul","verrou":true},{"t":"Formule de Moivre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":18,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour étudier la rotation d'une pale d'un moulin à vent expérimental à Maroua, on utilise la forme exponentielle.","tache":"Écris 1 + i sous forme exponentielle."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r19",{"duree":25,"titre":"Linéarisation et racines n-ièmes","accroche":"Les racines d'un complexe dessinent un polygone régulier.","intro":"Les formules d'Euler transforment des puissances de sinus et cosinus en sommes, plus faciles à intégrer.","objectifs":["utiliser les formules d'Euler","linéariser","calculer des racines n-ièmes"],"parties":[{"t":"Formules d'Euler","html":"<div class='def'><b>Formules</b><strong>cos θ = (eⁱᶿ + e⁻ⁱᶿ) / 2</strong> et <strong>sin θ = (eⁱᶿ − e⁻ⁱᶿ) / 2i</strong>.</div>"},{"t":"Linéariser","verrou":true},{"t":"Racines n-ièmes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":19,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une décoration en étoile doit placer 6 points réguliers sur un cercle pour un logo de l'association du lycée à Dschang.","tache":"Explique quelle équation donne ces points."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r20",{"duree":25,"titre":"Complexes et géométrie","accroche":"Un quotient d'affixes dit tout d'un triangle.","intro":"Le calcul complexe démontre l'alignement, le parallélisme et la nature d'un triangle.","objectifs":["interpréter un quotient d'affixes","déterminer la nature d'un triangle","prouver un alignement"],"parties":[{"t":"Le quotient","html":"<div class='def'><b>Propriété</b>Soit Z = (z_C − z_A) / (z_B − z_A). Alors <strong>|Z| = AC / AB</strong> et <strong>arg Z = (vecteur AB ; vecteur AC)</strong>.</div>"},{"t":"Conséquences","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":20,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un géomètre de Kribi veut vérifier qu'un terrain forme un angle droit en A, à partir des affixes de trois bornes.","tache":"Dis quel calcul effectuer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r21",{"duree":15,"titre":"Primitives d'une fonction continue","accroche":"Remonter de la vitesse à la distance.","intro":"Une primitive est une opération inverse de la dérivation.","objectifs":["définir une primitive","vérifier une primitive","trouver une primitive avec condition"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>F est une <strong>primitive</strong> de f sur I si <strong>F' = f</strong> sur I. Toute fonction continue sur un intervalle admet des primitives.</div>"},{"t":"Toutes les primitives","html":"<p>Si F est une primitive de f, les autres sont de la forme F + k, où k est une constante.</p>","labo":{"type":"courbe","fn":"x2","xmin":-3,"xmax":3,"ymin":-2,"ymax":9,"x0":1}},{"t":"Avec une condition","html":"<div class='ex'><b>Exemple</b>Primitive de 2x + 3 qui s'annule en 1.</div><p>F(x) = x² + 3x + k, et F(1) = 0 donne k = −4. Donc F(x) = x² + 3x − 4.</p>","retenir":"Pour vérifier une primitive, on la dérive."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Toute fonction continue sur un intervalle admet :</p><ol type='a'><li>une seule primitive</li><li>aucune primitive</li><li>des primitives sur cet intervalle</li><li>une primitive nulle en tout point de l'intervalle</li></ol><details><summary>Voir la réponse</summary><p><strong>des primitives sur cet intervalle</strong>. C'est un théorème fondamental.</p></details><p><strong>Exercice.</strong></p><p>Donne la primitive de 3x² qui vaut 2 en 0.</p><details><summary>Voir la réponse</summary><p>(Réponse : x³ + 2.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> La vitesse d'une moto est v(t) = 3t² − 4t + 2 (m/s) ; sa position à t = 0 vaut 5 m. On étudie aussi g(x) = (2x + 1)/(x² + x + 1)².</p><p><strong>Tâche 1.</strong> Détermine la position x(t) et calcule x(2).</p><p><strong>Tâche 2.</strong> Détermine la primitive G de g qui vaut 1 en 0.</p><details><summary>Voir une réponse attendue</summary><p>x(t) = t³ − 2t² + 2t + 5 ; x(2) = 8 − 8 + 4 + 5 = 9 m. g est de la forme u'/u² : G(x) = −1/(x² + x + 1) + c ; G(0) = −1 + c = 1 donne c = 2.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["F' = f.","F + k.","Condition : trouver k."],"exo":"<p>Donne la primitive de 3x² qui vaut 2 en 0. <em>(Réponse : x³ + 2.)</em></p>","quiz":[{"q":"Toute fonction continue sur un intervalle admet :","r":["une seule primitive","aucune primitive","des primitives sur cet intervalle","une primitive nulle en tout point de l'intervalle"],"b":2,"e":"C'est un théorème fondamental."},{"q":"Deux primitives d'une même fonction sur un intervalle diffèrent :","r":["d'un facteur","de x","de rien","d'une constante"],"b":3,"e":"Leur dérivée est la même."},{"q":"Une primitive de cos x est :","r":["sin x","−sin x","cos x","−cos x"],"b":0,"e":"La dérivée de sin x est cos x."},{"q":"Une primitive de sin x est :","r":["cos x","−cos x","sin x","−sin x"],"b":1,"e":"La dérivée de −cos x est sin x."},{"q":"La primitive de 2x qui vaut 3 en 0 est :","r":["x²","2x + 3","x² + 3","x² − 3"],"b":2,"e":"x² + k avec k = 3."},{"q":"Une primitive de 1/x² sur ]0 ; +∞[ est :","r":["1/x","ln x","−2/x³","−1/x"],"b":3,"e":"La dérivée de −1/x est 1/x²."},{"q":"La fonction x ↦ ∫ₐˣ f(t) dt est :","r":["la primitive de f qui s'annule en a","la dérivée de f","une constante","f elle-même, prise en a"],"b":0,"e":"C'est le théorème fondamental de l'analyse."},{"q":"Une primitive de (2x + 1)³ est :","r":["(2x + 1)⁴/4","(2x + 1)⁴/8","3(2x + 1)²","(2x + 1)⁴"],"b":1,"e":"On divise par 4 × 2 = 8."},{"q":"Une primitive de 1/√x sur ]0 ; +∞[ est :","r":["√x","1/(2√x)","2√x","−2√x"],"b":2,"e":"La dérivée de 2√x est 1/√x."},{"q":"Une primitive de cos(2x) est :","r":["sin(2x)","2 sin(2x)","−(1/2) sin(2x)","(1/2) sin(2x)"],"b":3,"e":"La dérivée de sin(2x) est 2 cos(2x)."}],"c":"Tle D","m":"maths","rang":21,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La vitesse d'un car sur la route Douala-Édéa est modélisée par v(t) = 2t + 3 (unités du problème).","tache":"Donne la position, sachant qu'elle est nulle à t = 1."},"gratuit":true});
VRT_L("tle-d-maths-r22",{"duree":20,"titre":"Déterminer des primitives","accroche":"Reconnaître une forme, c'est déjà avoir la primitive.","intro":"Le tableau des primitives usuelles et quelques formes composées suffisent dans la plupart des cas.","objectifs":["utiliser le tableau usuel","reconnaître u'uⁿ","reconnaître u'/u²"],"parties":[{"t":"Primitives usuelles","html":"<div class='def'><b>Tableau</b>xⁿ → xⁿ⁺¹/(n + 1) ; 1/x² → −1/x ; 1/√x → 2√x ; cos x → sin x ; sin x → −cos x.</div>"},{"t":"Formes composées","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":22,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Le débit d'une pompe de Garoua est d(t) = 2t(t² + 1)³, en litres par minute ; on cherche le volume pompé V(t), primitive de d avec V(0) = 0.","tache":"Identifie u, donne une primitive de d et calcule V(1)."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r23",{"duree":25,"titre":"Le logarithme népérien","accroche":"Transformer les produits en sommes.","intro":"Le logarithme népérien répond à une question : quelle est la primitive de 1/x ?","objectifs":["définir ln","utiliser ses propriétés","dériver ln u"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La fonction <strong>logarithme népérien</strong>, notée ln, est la primitive de 1/x sur ]0 ; +∞[ qui s'annule en 1.</div>"},{"t":"Propriétés","verrou":true},{"t":"Limites et dérivée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":23,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une micro-finance de Bafoussam place 100 000 F à intérêts composés. On veut savoir en combien de temps le capital double.","tache":"Écris l'équation à résoudre avec un taux annuel de 10 %."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r24",{"duree":20,"titre":"Autres fonctions logarithmes","accroche":"Du pH à la magnitude : le logarithme décimal partout.","intro":"Le logarithme décimal permet de manipuler des nombres de tailles très différentes.","objectifs":["définir log de base a","calculer un logarithme décimal","résoudre une équation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Pour a > 0 et a ≠ 1, le <strong>logarithme de base a</strong> est <strong>log_a x = ln x / ln a</strong>. Le logarithme décimal est celui de base 10.</div>"},{"t":"Propriétés","verrou":true},{"t":"Applications","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":24,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un technicien de laboratoire à Yaoundé mesure [H₃O⁺] = 10⁻⁴ mol/L dans une eau de source.","tache":"Calcule le pH."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r25",{"duree":15,"titre":"Le vocabulaire des probabilités","accroche":"Avant de calculer une chance, il faut nommer ce que l'on regarde.","intro":"Un vocabulaire précis évite les erreurs de raisonnement.","objectifs":["définir univers et événement","utiliser ∩, ∪ et contraire","reconnaître des événements incompatibles"],"parties":[{"t":"Vocabulaire","html":"<div class='def'><b>Définitions</b>L'<strong>univers</strong> Ω est l'ensemble des issues d'une expérience aléatoire. Un <strong>événement</strong> est une partie de Ω.</div>"},{"t":"Opérations","verrou":true},{"t":"Incompatibles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":25,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Au tirage d'une tombola de fin d'année au lycée de Sangmélima, on s'intéresse à un ticket pair ou supérieur à 50.","tache":"Écris l'événement avec les symboles."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r26",{"duree":25,"titre":"Calculer la probabilité d'un événement","accroche":"Compter les cas favorables, sans en oublier ni en compter deux fois.","intro":"Dans une situation d'équiprobabilité, une probabilité est un rapport de deux dénombrements.","objectifs":["calculer en équiprobabilité","utiliser les combinaisons","utiliser les formules"],"parties":[{"t":"Équiprobabilité","html":"<div class='def'><b>Formule</b>En cas d'<strong>équiprobabilité</strong>, <strong>P(A) = card A / card Ω</strong>.</div>"},{"t":"Formules","verrou":true},{"t":"Combinaisons","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":26,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un comité de 5 élèves dont 3 filles, à Kumba, on tire 2 délégués au hasard.","tache":"Calcule la probabilité que les 2 délégués soient des filles."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r27",{"duree":25,"titre":"Probabilités conditionnelles","accroche":"Une information nouvelle change la probabilité.","intro":"Sachant qu'un événement s'est produit, on recalcule les chances des autres. C'est le cœur de nombreux problèmes de bac.","objectifs":["calculer une probabilité conditionnelle","construire un arbre","appliquer la formule des probabilités totales"],"parties":[{"t":"Définition","html":"<div class='def'><b>Formule</b>Si P(A) ≠ 0, <strong>P_A(B) = P(A ∩ B) / P(A)</strong>. A et B sont <strong>indépendants</strong> si P(A ∩ B) = P(A) P(B).</div>"},{"t":"Probabilités totales","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":27,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un lycée de Douala, 60 % des candidats au bac sont des filles. 70 % d'entre elles réussissent, contre 50 % des garçons.","tache":"Calcule le taux global de réussite."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r28",{"duree":20,"titre":"Variables aléatoires","accroche":"Un jeu est-il équitable ? L'espérance répond.","intro":"Une variable aléatoire associe un nombre à chaque issue, comme un gain à un jeu.","objectifs":["établir une loi de probabilité","calculer l'espérance","calculer variance et écart-type"],"parties":[{"t":"Loi de probabilité","html":"<div class='def'><b>Définition</b>Une <strong>variable aléatoire</strong> X associe un réel à chaque issue. Sa <strong>loi</strong> donne P(X = xᵢ) pour chaque valeur.</div>"},{"t":"Espérance","verrou":true},{"t":"Variance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":28,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un ticket de loterie du comité des fêtes de Bafang coûte 100 F. Les gains sont 0, 100 ou 500 F avec probabilités 0,7 ; 0,2 ; 0,1.","tache":"Dis si le jeu est favorable au joueur."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r29",{"duree":25,"titre":"Épreuves de Bernoulli et loi binomiale","accroche":"Répéter une expérience à deux issues suit une loi très précise.","intro":"Combien de chances d'obtenir 2 succès en 5 essais ? La loi binomiale le dit.","objectifs":["reconnaître un schéma de Bernoulli","appliquer la loi binomiale","calculer E et V"],"parties":[{"t":"Le schéma de Bernoulli","html":"<div class='def'><b>Définition</b>Une <strong>épreuve de Bernoulli</strong> a deux issues, succès (p) et échec (1 − p). Répétée n fois de manière indépendante, le nombre X de succès suit la <strong>loi binomiale B(n ; p)</strong>.</div>"},{"t":"La formule","verrou":true},{"t":"Espérance et variance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":29,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un lot de semences à Dschang, chaque graine germe avec une probabilité de 0,8. Un paysan en sème 5.","tache":"Calcule la probabilité qu'aucune ne germe."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r30",{"duree":20,"titre":"Similitudes directes : expressions complexes","accroche":"Agrandir et tourner avec une seule formule.","intro":"Une similitude directe combine rotation et homothétie. Elle s'exprime très simplement avec les complexes.","objectifs":["reconnaître l'écriture z' = az + b","trouver l'expression analytique","calculer une image"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>similitude directe</strong> est une transformation du plan d'écriture complexe <strong>z' = az + b</strong>, avec a ≠ 0.</div>"},{"t":"Expression analytique","verrou":true},{"t":"Déterminer une similitude","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":30,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sur une maquette d'architecte à Yaoundé, un motif est tourné et agrandi avant impression.","tache":"Calcule l'image du point d'affixe 1 + i par z' = 2z + i."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r31",{"duree":25,"titre":"Propriétés des similitudes directes","accroche":"Centre, rapport, angle : la carte d'identité d'une similitude.","intro":"Toute similitude directe qui n'est pas une translation possède un centre, un rapport et un angle.","objectifs":["trouver centre, rapport et angle","utiliser les propriétés","décomposer une similitude"],"parties":[{"t":"Éléments caractéristiques","html":"<div class='def'><b>Propriété</b>Pour z' = az + b, avec a ≠ 1 : <strong>rapport k = |a|</strong>, <strong>angle θ = arg a</strong>, <strong>centre ω = b / (1 − a)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Propriétés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":31,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un motif de pagne fabriqué à Garoua est reproduit par une similitude de rapport 2.","tache":"Dis comment l'aire du motif est modifiée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r32",{"duree":25,"titre":"La fonction exponentielle népérienne","accroche":"La seule fonction égale à sa propre dérivée.","intro":"La fonction exponentielle décrit les croissances rapides : intérêts, populations, épidémies.","objectifs":["définir exp","utiliser ses propriétés","connaître ses limites"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La fonction <strong>exponentielle</strong> est la réciproque de ln. Elle est définie sur ℝ, à valeurs strictement positives, et vérifie <strong>exp' = exp</strong> et exp(0) = 1.</div>"},{"t":"Propriétés","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":32,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Le nombre de bactéries d'une culture, au laboratoire d'un hôpital de Douala, est modélisé par N(t) = 100 e^(0,5t).","tache":"Calcule au bout de combien de temps le nombre double."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r33",{"duree":25,"titre":"Étude de fonctions définies à l'aide de l'exponentielle","accroche":"Un maximum caché derrière x e⁻ˣ.","intro":"Les fonctions du type u(x)e^v(x) reviennent régulièrement dans les problèmes de bac.","objectifs":["dériver e^u","étudier un produit","tracer la courbe"],"parties":[{"t":"Dérivée","html":"<div class='def'><b>Formule</b>Si u est dérivable, <strong>(e^u)' = u' e^u</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":33,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La concentration d'un médicament dans le sang est modélisée par C(t) = t e⁻ᵗ (unités du problème).","tache":"Détermine à quel moment la concentration est maximale."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r34",{"duree":20,"titre":"L'intégrale : définition et propriétés","accroche":"Additionner une infinité de tranches très fines.","intro":"L'intégrale relie deux idées : aire sous une courbe et primitive.","objectifs":["définir l'intégrale","utiliser la linéarité","utiliser la relation de Chasles"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Si F est une primitive de f sur [a ; b], <strong>∫ₐᵇ f(x) dx = F(b) − F(a)</strong>.</div><div class='ex'><b>Exemple</b>∫₀² x² dx = 8/3.</div>"},{"t":"Propriétés","html":"<ul><li>Linéarité : ∫(αf + βg) = α∫f + β∫g.</li><li>Chasles : ∫ₐᶜ f = ∫ₐᵇ f + ∫ᵦᶜ f.</li></ul>","labo":{"type":"integrale","fn":"x2","a":0,"b":2,"amin":0,"xmax":3,"ymax":9}},{"t":"Inverser les bornes","html":"<p class='formule'>∫ₐᵇ f = −∫ᵦₐ f</p>","retenir":"Le résultat ne dépend pas de la primitive choisie."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Si F est une primitive de f continue sur [a ; b], ∫ₐᵇ f(x) dx vaut :</p><ol type='a'><li>F(b) − F(a)</li><li>F(a) − F(b)</li><li>F(a) × F(b)</li><li>F(b) + F(a)</li></ol><details><summary>Voir la réponse</summary><p><strong>F(b) − F(a)</strong>. C'est le théorème fondamental.</p></details><p><strong>Exercice.</strong></p><p>Calcule ∫₁² 3x² dx.</p><details><summary>Voir la réponse</summary><p>(Réponse : 7.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Le débit d'une source à Dschang est d(t) = 3t² − 2t + 1 (m³/h).</p><p><strong>Tâche 1.</strong> Calcule le volume écoulé entre t = 0 et t = 2.</p><p><strong>Tâche 2.</strong> Calcule le débit moyen sur cette période.</p><details><summary>Voir une réponse attendue</summary><p>V = ∫₀² (3t² − 2t + 1) dt = [t³ − t² + t]₀² = 8 − 4 + 2 = 6 m³. Débit moyen : 6/2 = 3 m³/h.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["F(b) − F(a).","Linéarité.","Chasles."],"exo":"<p>Calcule ∫₁² 3x² dx. <em>(Réponse : 7.)</em></p>","quiz":[{"q":"Si F est une primitive de f continue sur [a ; b], ∫ₐᵇ f(x) dx vaut :","r":["F(b) − F(a)","F(a) − F(b)","F(a) × F(b)","F(b) + F(a)"],"b":0,"e":"C'est le théorème fondamental."},{"q":"∫₀¹ x dx vaut :","r":["1","1/2","0","2"],"b":1,"e":"[x²/2] de 0 à 1 = 1/2."},{"q":"∫₀² 3x² dx vaut :","r":["12","6","8","4"],"b":2,"e":"[x³] de 0 à 2 = 8."},{"q":"∫ₐᵃ f(x) dx vaut :","r":["f(a)","1","a","0"],"b":3,"e":"Les bornes sont égales."},{"q":"∫ₐᵇ f(x) dx est égal à :","r":["−∫ᵦᵃ f(x) dx","∫ᵦᵃ f(x) dx","0","f(b) − f(a)"],"b":0,"e":"Échanger les bornes change le signe."},{"q":"La relation de Chasles s'écrit :","r":["∫ₐᶜ f = ∫ₐᵇ f × ∫ᵦᶜ f","∫ₐᶜ f = ∫ₐᵇ f + ∫ᵦᶜ f","∫ₐᶜ f = 0","∫ₐᵇ f = ∫ᵦᶜ f"],"b":1,"e":"Elle découpe l'intervalle d'intégration."},{"q":"∫₀^π sin x dx vaut :","r":["0","1","2","π"],"b":2,"e":"[−cos x] de 0 à π = 1 + 1."},{"q":"∫₁^e (1/x) dx vaut :","r":["e","0","e − 1","1"],"b":3,"e":"[ln x] de 1 à e = 1."},{"q":"L'intégrale est linéaire, donc ∫(2f + 3g) =","r":["2∫f + 3∫g","5∫(f + g)","∫f × ∫g","6∫fg"],"b":0,"e":"On sort les constantes et on sépare les sommes."},{"q":"∫₀¹ eˣ dx vaut :","r":["e","e − 1","1","0"],"b":1,"e":"eˣ est sa propre primitive : e¹ − e⁰ = e − 1."}],"c":"Tle D","m":"maths","rang":34,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Le débit d'une pompe, à Ngaoundéré, varie selon la loi d(t) = 3t² (litres par heure).","tache":"Calcule le volume pompé entre t = 1 et t = 2."},"gratuit":true});
VRT_L("tle-d-maths-r35",{"duree":25,"titre":"Calculs d'aires et de volumes","accroche":"De la formule au nombre de mètres carrés.","intro":"L'intégrale permet de calculer des aires limitées par des courbes et le volume de solides de révolution.","objectifs":["calculer une aire","calculer une aire entre deux courbes","calculer un volume de révolution"],"parties":[{"t":"Aire sous une courbe","html":"<div class='def'><b>Propriété</b>Si f est continue et positive sur [a ; b], l'<strong>aire</strong> du domaine compris entre la courbe, l'axe des abscisses et les droites x = a et x = b vaut <strong>∫ₐᵇ f(x) dx</strong> unités d'aire.</div>"},{"t":"Entre deux courbes","verrou":true},{"t":"Volume de révolution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":35,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un artisan de Bamenda veut calculer la surface d'un dessin délimité par y = x et y = x² sur [0 ; 1], l'unité valant 1 m.","tache":"Calcule cette aire."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r36",{"duree":20,"titre":"Positivité et inégalité de la moyenne","accroche":"Encadrer une intégrale sans la calculer.","intro":"Il n'est pas toujours possible de calculer une intégrale exactement. Les inégalités donnent un encadrement.","objectifs":["utiliser la positivité","appliquer l'inégalité de la moyenne","calculer une valeur moyenne"],"parties":[{"t":"Positivité","html":"<div class='def'><b>Propriété</b>Si a ≤ b et f ≥ 0 sur [a ; b], alors <strong>∫ₐᵇ f ≥ 0</strong>. Si f ≤ g, alors ∫f ≤ ∫g.</div>"},{"t":"Inégalité de la moyenne","verrou":true},{"t":"La valeur moyenne","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":36,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un capteur enregistre la température d'une serre à Dschang, entre 20 °C et 30 °C, sur 10 heures.","tache":"Encadre l'intégrale de la température."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r37",{"duree":25,"titre":"Méthodes de calcul des intégrales","accroche":"Quand aucune primitive n'apparaît, on intègre par parties.","intro":"Les formes composées et l'intégration par parties permettent de calculer de nombreuses intégrales.","objectifs":["reconnaître une forme composée","appliquer l'intégration par parties","linéariser avant d'intégrer"],"parties":[{"t":"Intégration par parties","html":"<div class='def'><b>Formule</b>Si u et v sont dérivables, à dérivées continues, <strong>∫ₐᵇ u v' = [uv]ₐᵇ − ∫ₐᵇ u' v</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Linéarisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":37,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La puissance d'un panneau solaire de Maroua, au démarrage, vaut p(t) = t eᵗ (en kW, t en heures). On veut l'énergie produite pendant la première heure, E = ∫₀¹ t eᵗ dt.","tache":"Calcule E par intégration par parties."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r38",{"duree":20,"titre":"Valeurs approchées d'une intégrale","accroche":"Remplacer une courbe par des rectangles.","intro":"Quand une primitive n'est pas accessible, on approche l'intégrale par des aires simples.","objectifs":["appliquer la méthode des rectangles","appliquer la méthode des trapèzes","comparer les résultats"],"parties":[{"t":"Les rectangles","html":"<div class='def'><b>Méthode</b>On découpe [a ; b] en n intervalles de largeur h = (b − a) / n. L'intégrale est approchée par la <strong>somme des aires de rectangles</strong>.</div>"},{"t":"Les trapèzes","verrou":true},{"t":"Comparer","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":38,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un topographe de Kribi évalue la surface d'une parcelle à bord courbe à partir de mesures tous les 5 m.","tache":"Quelle méthode permet d'estimer cette surface ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r39",{"duree":15,"titre":"Équations différentielles : présentation","accroche":"Une équation dont l'inconnue est une fonction.","intro":"De nombreux phénomènes s'expriment par une relation entre une grandeur et sa vitesse de variation.","objectifs":["définir une équation différentielle","vérifier une solution","comprendre une condition initiale"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>équation différentielle</strong> relie une fonction inconnue y à ses dérivées. Résoudre, c'est trouver toutes les fonctions qui la vérifient.</div>"},{"t":"Vérifier","verrou":true},{"t":"Condition initiale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":39,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une équipe de santé de Bertoua modélise la croissance d'une culture par une équation liant sa taille et sa vitesse de croissance.","tache":"Vérifie que y = e^(2x) convient pour y' = 2y."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r40",{"duree":25,"titre":"Équations y' = ay et y' = ay + b","accroche":"Le refroidissement d'une tasse, en une formule.","intro":"Ces équations décrivent les croissances, les décroissances et les refroidissements.","objectifs":["résoudre y' = ay","résoudre y' = ay + b","utiliser une condition initiale"],"parties":[{"t":"L'équation y' = ay","html":"<div class='def'><b>Théorème</b>Les solutions de <strong>y' = ay</strong> sont les fonctions <strong>y(x) = C e^(ax)</strong>, avec C constante réelle.</div>"},{"t":"L'équation y' = ay + b","verrou":true},{"t":"Condition initiale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":40,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La température d'un bouillon servi à Bafia baisse selon une équation de la forme y' = −0,1 y, où y est l'écart avec la pièce.","tache":"Donne l'expression de y si l'écart initial est 60 °C."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-maths-r41",{"duree":25,"titre":"Équations du type y'' + ay' + by = 0","accroche":"Un ressort qui oscille obéit à cette équation.","intro":"Ces équations décrivent les oscillations mécaniques et électriques.","objectifs":["écrire l'équation caractéristique","résoudre y'' + ω²y = 0","traiter les conditions initiales"],"parties":[{"t":"Équation caractéristique","html":"<div class='def'><b>Méthode</b>L'<strong>équation caractéristique</strong> de y'' + ay' + by = 0 est <strong>r² + ar + b = 0</strong>.</div><ul><li>Δ > 0 : y = Ae^(r₁x) + Be^(r₂x).</li><li>Δ = 0 : y = (Ax + B)e^(rx).</li><li>Δ < 0 : y = e^(αx)(A cos βx + B sin βx).</li></ul>"},{"t":"L'équation y'' + ω²y = 0","verrou":true},{"t":"Conditions initiales","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"maths","rang":41,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour un projet de sismographe artisanal à Limbé, une masse suspendue à un ressort suit l'équation y'' + 4y = 0.","tache":"Exprime y si y(0) = 1 et y'(0) = 0."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r01",{"duree":20,"titre":"Erreur et incertitude sur la mesure","accroche":"Une mesure sans incertitude ne dit pas grand-chose.","intro":"Toute mesure comporte une part d'imprécision. Savoir l'évaluer permet de comparer une valeur à une référence.","objectifs":["distinguer erreur et incertitude","calculer une incertitude relative","présenter un résultat"],"parties":[{"t":"Erreur et incertitude","html":"<div class='def'><b>Définitions</b>L'<strong>incertitude absolue</strong> ΔX est la limite de l'écart possible entre la valeur mesurée et la valeur vraie. L'<strong>incertitude relative</strong> est ΔX / X.</div>"},{"t":"Présenter un résultat","html":"<p class='formule'>X = x ± ΔX</p><div class='ex'><b>Exemple</b>L = 20,0 ± 0,5 cm : l'incertitude relative est de 2,5 %.</div>","labo":{"type":"calcul","f":"incert","vals":{"x":20,"d":0.5}}},{"t":"Propagation","html":"<p>Pour une somme, les incertitudes absolues s'ajoutent. Pour un produit ou un quotient, les incertitudes relatives s'ajoutent.</p>","retenir":"Une erreur peut être systématique ou aléatoire."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> L'incertitude absolue sur une mesure s'exprime :</p><ol type='a'><li>en pourcentage de la valeur mesurée, obligatoirement</li><li>dans la même unité que la grandeur mesurée</li><li>sans unité, car c'est un simple écart</li><li>en secondes, quelle que soit la grandeur</li></ol><details><summary>Voir la réponse</summary><p><strong>dans la même unité que la grandeur mesurée</strong>. Ex. : L = 12,4 cm ± 0,1 cm.</p></details><p><strong>Application directe des savoirs.</strong></p><p>m = 50 ± 1 g : calcule l'incertitude relative.</p><details><summary>Voir la réponse</summary><p>(Réponse : 2 %.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Deux groupes mesurent g avec un pendule. Groupe A : g = (9,79 ± 0,05) m/s² ; groupe B : g = (9,6 ± 0,1) m/s². La valeur de référence au lieu de mesure est 9,78 m/s².</p><p><strong>Consigne 1.</strong> Examine si chaque résultat est compatible avec la valeur de référence.</p><p><strong>Consigne 2.</strong> Calcule l'incertitude relative de chaque groupe et dis lequel est le plus précis.</p><details><summary>Voir une réponse attendue</summary><p>A : [9,74 ; 9,84] contient 9,78, compatible. B : [9,5 ; 9,7] ne la contient pas, non compatible (erreur systématique probable). Incertitudes relatives : A 0,05/9,79 ≈ 0,5 % ; B 0,1/9,6 ≈ 1 % : A est plus précis.</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique face aux résultats."}],"revision":["X = x ± ΔX.","Incertitude relative.","Propagation."],"exo":"<p>m = 50 ± 1 g : calcule l'incertitude relative. <em>(Réponse : 2 %.)</em></p>","quiz":[{"q":"L'incertitude absolue sur une mesure s'exprime :","r":["en pourcentage de la valeur mesurée, obligatoirement","dans la même unité que la grandeur mesurée","sans unité, car c'est un simple écart","en secondes, quelle que soit la grandeur"],"b":1,"e":"Ex. : L = 12,4 cm ± 0,1 cm."},{"q":"L'incertitude relative est :","r":["la différence X − ΔX","le produit X × ΔX","le rapport ΔX / X","toujours égale à 1 %"],"b":2,"e":"Elle s'exprime souvent en pourcentage."},{"q":"L = 20,0 cm ± 0,2 cm : l'incertitude relative vaut :","r":["0,2 %","2 %","10 %","1 %"],"b":3,"e":"0,2 ÷ 20,0 = 0,01."},{"q":"Une erreur systématique :","r":["décale toutes les mesures dans le même sens","varie au hasard d'une mesure à l'autre","disparaît quand on répète les mesures et fait la moyenne","n'existe pas avec un appareil numérique"],"b":0,"e":"Ex. : un zéro mal réglé sur une balance."},{"q":"Une erreur aléatoire se réduit :","r":["en changeant d'unité pour exprimer le résultat","en répétant les mesures et en prenant la moyenne","en arrondissant chaque mesure à l'unité","jamais, l'erreur aléatoire étant toujours la même"],"b":1,"e":"Les écarts dans les deux sens se compensent."},{"q":"Le résultat 9,81 m/s² comporte :","r":["2 chiffres significatifs","4 chiffres significatifs","3 chiffres significatifs","1 chiffre significatif"],"b":2,"e":"9, 8 et 1 sont significatifs."},{"q":"Pour une somme S = A + B, l'incertitude absolue vaut :","r":["ΔA × ΔB","ΔA − ΔB","ΔA / ΔB","ΔA + ΔB"],"b":3,"e":"Les incertitudes absolues s'additionnent."},{"q":"Pour un produit P = A × B, l'incertitude relative vaut :","r":["ΔA/A + ΔB/B","ΔA + ΔB","ΔA × ΔB","ΔA/A − ΔB/B"],"b":0,"e":"Les incertitudes relatives s'additionnent."},{"q":"Un chronomètre gradué au centième de seconde a une incertitude de lecture d'environ :","r":["1 s","0,01 s","0,1 s","0,001 s"],"b":1,"e":"Elle correspond à la plus petite graduation."},{"q":"Le résultat d'une mesure s'écrit :","r":["valeur seule, avec tous les chiffres de la calculatrice","incertitude seule, exprimée en pourcentage","valeur ± incertitude, avec l'unité","valeur ± incertitude, sans unité"],"b":2,"e":"C'est l'écriture scientifique attendue."}],"c":"Tle D","m":"physique","rang":1,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Au lycée de Nkolbisson, deux groupes mesurent la même longueur d'onde et trouvent des valeurs proches. Ils s'interrogent sur leur accord avec l'indication du fabricant.","tache":"Dis comment décider si l'écart est acceptable."},"gratuit":true});
VRT_L("tle-d-physique-r02",{"duree":15,"titre":"Dimensions et homogénéité","accroche":"Vérifier une formule sans refaire la démonstration.","intro":"Une formule juste doit avoir la même dimension des deux côtés. Ce contrôle détecte beaucoup d'erreurs.","objectifs":["écrire une dimension","vérifier l'homogénéité","trouver l'unité d'une constante"],"parties":[{"t":"Dimension","html":"<div class='def'><b>Définition</b>La <strong>dimension</strong> d'une grandeur s'exprime à partir des grandeurs de base : [L], [M], [T], [I]. Une relation est <strong>homogène</strong> si les deux membres ont la même dimension.</div>"},{"t":"Exemples","verrou":true},{"t":"Remarque d'examen","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":2,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un élève de Dschang propose T = 2π√(g/L) pour la période d'un pendule.","tache":"Vérifie si cette formule est possible."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r03",{"duree":20,"titre":"La force de gravitation","accroche":"La même force fait tomber une mangue et tourner la Lune.","intro":"Newton a montré que tous les corps s'attirent selon une même loi.","objectifs":["énoncer la loi d'attraction","calculer une force","représenter les vecteurs"],"parties":[{"t":"La loi","html":"<div class='def'><b>Loi d'attraction universelle</b>Deux corps ponctuels de masses m et m', distants de d, s'attirent avec une force d'intensité <strong>F = G m m' / d²</strong>, où G = 6,67 × 10⁻¹¹ N·m²·kg⁻².</div>"},{"t":"Caractéristiques","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":3,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Pour un club d'astronomie à Maroua, on souhaite comparer l'attraction de la Terre sur un satellite à deux altitudes.","tache":"Explique comment varie la force quand l'altitude augmente."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r04",{"duree":20,"titre":"Le champ de gravitation","accroche":"g n'est pas le même au sommet du mont Cameroun et à Douala.","intro":"Autour d'une planète, chaque point de l'espace est caractérisé par un champ de gravitation.","objectifs":["définir le champ","calculer g en altitude","relier g et g₀"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>champ de gravitation</strong> créé par une masse M à la distance d a pour intensité <strong>g = GM / d²</strong>. Il est dirigé vers le centre de M.</div>"},{"t":"En altitude","verrou":true},{"t":"Rappel","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":4,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un randonneur grimpe sur le mont Cameroun avec un dynamomètre pour comparer son poids.","tache":"Dis comment évolue le poids avec l'altitude."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r05",{"duree":20,"titre":"Charge électrique et loi de Coulomb","accroche":"Une règle frottée attire de petits morceaux de papier.","intro":"Les charges électriques exercent des forces à distance. La loi de Coulomb les quantifie.","objectifs":["expliquer l'électrisation","énoncer la loi de Coulomb","calculer une force"],"parties":[{"t":"L'électrisation","html":"<div class='def'><b>Loi de Coulomb</b>Deux charges ponctuelles q et q', séparées d'une distance d, exercent l'une sur l'autre des forces d'intensité <strong>F = k |q q'| / d²</strong>, avec k = 9 × 10⁹ S.I.</div><p>Les charges de même signe se repoussent, celles de signes contraires s'attirent.</p>"},{"t":"Les modes d'électrisation","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":5,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Par temps sec, à Garoua, un élève reçoit une petite décharge en touchant une poignée métallique.","tache":"Explique le phénomène."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r06",{"duree":20,"titre":"Champ électrostatique et condensateur plan","accroche":"Entre deux plaques, le champ est uniforme.","intro":"Une charge crée un champ électrique. Entre les armatures d'un condensateur plan, ce champ est uniforme.","objectifs":["définir le champ électrique","calculer E dans un condensateur","calculer une force"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>champ électrostatique</strong> E en un point vérifie <strong>F = qE</strong>. Pour une charge ponctuelle Q : E = k|Q| / d².</div>"},{"t":"Condensateur plan","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":6,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un appareil de physique du lycée de Mbouda, on applique 100 V entre deux plaques distantes de 1 cm.","tache":"Calcule le champ électrique."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r07",{"duree":20,"titre":"Force et champ magnétiques d'un courant","accroche":"Un fil parcouru par un courant dévie une boussole.","intro":"Un courant crée un champ magnétique. Ce champ exerce à son tour une force sur d'autres courants.","objectifs":["calculer B d'un fil et d'un solénoïde","appliquer la force de Laplace","orienter les vecteurs"],"parties":[{"t":"Champs créés","html":"<div class='def'><b>Formules</b>Un fil rectiligne crée un champ <strong>B = 2 × 10⁻⁷ I / d</strong>. Dans un solénoïde long : <strong>B = 4π × 10⁻⁷ N I / L</strong>.</div>"},{"t":"Force de Laplace","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":7,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un électricien de Douala observe qu'une boussole dévie près d'un gros câble parcouru par un courant.","tache":"Explique la déviation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r08",{"duree":20,"titre":"Interaction de courants et force de Lorentz","accroche":"Une particule chargée dévie sans ralentir.","intro":"Deux conducteurs parcourus par des courants interagissent. Une charge mobile subit la force de Lorentz.","objectifs":["décrire l'interaction de deux fils","écrire la force de Lorentz","orienter la force"],"parties":[{"t":"Interaction entre fils","html":"<div class='def'><b>Force de Lorentz</b>Une particule de charge q, de vitesse v, dans un champ B, subit la force <strong>F = q v ∧ B</strong>, d'intensité |q| v B sin α.</div><p>Deux fils parallèles parcourus par des courants de même sens s'attirent.</p>"},{"t":"Interaction","verrou":true},{"t":"Propriété","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":8,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un exposé sur les aurores, un élève de Bertoua explique que des particules du Soleil sont déviées par le champ magnétique terrestre.","tache":"Identifie la force responsable."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r11",{"duree":25,"titre":"Mouvement rectiligne d'un solide","accroche":"Un plan incliné, des frottements et une accélération à trouver.","intro":"Le théorème du centre d'inertie permet de trouver l'accélération d'un solide.","objectifs":["appliquer le théorème du centre d'inertie","calculer une accélération","écrire les équations horaires"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Théorème du centre d'inertie</b>Dans un référentiel galiléen, <strong>ΣF = m a</strong>.</div><ol><li>Choisir le système et le référentiel.</li><li>Faire le bilan des forces.</li><li>Projeter.</li></ol>"},{"t":"Plan incliné","verrou":true},{"t":"Équations horaires","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":11,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un mototaxi de Douala freine sur une route en pente. Un élève veut estimer sa décélération.","tache":"Indique la méthode."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r12",{"duree":25,"titre":"Mouvement plan dans le champ de pesanteur","accroche":"La portée maximale d'un tir se calcule.","intro":"Un projectile décrit une parabole. Chaque composante du mouvement s'étudie séparément.","objectifs":["établir les équations horaires","écrire la trajectoire","calculer portée et flèche"],"parties":[{"t":"Équations horaires","html":"<div class='def'><b>Résultat</b>Sans frottement, l'accélération vaut <strong>g</strong>. Pour une vitesse initiale v₀ d'angle α : x = v₀ cos α · t et y = −(1/2) g t² + v₀ sin α · t.</div>"},{"t":"Trajectoire","verrou":true},{"t":"Portée et flèche","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":12,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Lors d'un match au stade de Bafoussam, un joueur frappe le ballon à 20 m/s, sous un angle de 45°.","tache":"Calcule la portée, sans frottement, avec g = 10 m/s²."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r14",{"duree":25,"titre":"Mouvement dans un champ électrique","accroche":"Un faisceau d'électrons dévié sur un écran.","intro":"Une particule chargée dans un champ uniforme se comporte comme un projectile.","objectifs":["calculer l'accélération","établir la trajectoire","calculer une vitesse par l'énergie"],"parties":[{"t":"Accélération","html":"<div class='def'><b>Résultat</b>Une particule de charge q, de masse m, dans un champ E, a pour accélération <strong>a = qE / m</strong>. Le poids est généralement négligé.</div>"},{"t":"Accélération par une tension","html":"<p class='formule'>(1/2) m v² = |q| U</p>","labo":{"type":"calcul","f":"conde","vals":{"U":200,"d":10}}},{"t":"Déviation","html":"<p>Avec une vitesse initiale perpendiculaire à E, la trajectoire est parabolique.</p><p class='formule'>y = q E x² / (2 m v₀²)</p>","retenir":"Une tension accélère les particules chargées."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Une particule chargée entrant parallèlement aux armatures d'un condensateur a une trajectoire :</p><ol type='a'><li>circulaire entre les armatures</li><li>rectiligne et accélérée vers l'armature</li><li>hélicoïdale autour des lignes de champ</li><li>parabolique entre les armatures</li></ol><details><summary>Voir la réponse</summary><p><strong>parabolique entre les armatures</strong>. Le champ uniforme joue le rôle de la pesanteur.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Écris l'expression de v pour un électron accéléré sous U.</p><details><summary>Voir la réponse</summary><p>(Réponse : v = √(2eU/m).)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Dans un oscilloscope, un électron entre à 2,0 × 10⁷ m/s entre deux plaques de 5,0 cm de long, distantes de 2,0 cm, sous 200 V, à égale distance des plaques. e = 1,6 × 10⁻¹⁹ C ; m = 9,1 × 10⁻³¹ kg. Mbida pense qu'il heurtera une plaque.</p><p><strong>Consigne 1.</strong> Calcule l'accélération de l'électron entre les plaques.</p><p><strong>Consigne 2.</strong> Examine si l'électron sort sans toucher les plaques.</p><details><summary>Voir une réponse attendue</summary><p>a = eU/(md) = 1,6 × 10⁻¹⁹ × 200/(9,1 × 10⁻³¹ × 0,02) ≈ 1,76 × 10¹⁵ m/s². Durée de traversée : 0,05/2 × 10⁷ = 2,5 × 10⁻⁹ s ; déviation y = ½at² ≈ 5,5 mm, inférieure à 1 cm : il sort sans toucher, Mbida se trompe.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche scientifique."}],"revision":["a = qE/m.","Énergie : (1/2) mv² = |q|U.","Trajectoire parabolique."],"exo":"<p>Écris l'expression de v pour un électron accéléré sous U. <em>(Réponse : v = √(2eU/m).)</em></p>","quiz":[{"q":"Une particule chargée entrant parallèlement aux armatures d'un condensateur a une trajectoire :","r":["circulaire entre les armatures","rectiligne et accélérée vers l'armature","hélicoïdale autour des lignes de champ","parabolique entre les armatures"],"b":3,"e":"Le champ uniforme joue le rôle de la pesanteur."},{"q":"L'accélération d'une particule de charge q et de masse m dans un champ E vaut :","r":["q E / m","m E / q","q m E","E / q"],"b":0,"e":"On applique F = ma avec F = qE."},{"q":"Un électron accéléré depuis le repos sous une tension U acquiert une vitesse :","r":["eU / m","√(2eU / m)","2eU m","√(m / eU)"],"b":1,"e":"On applique le théorème de l'énergie cinétique : ½mv² = eU."},{"q":"La déviation électrique est utilisée dans :","r":["le moteur à essence à quatre temps","la balance de Roberval","l'oscilloscope à tube cathodique","le thermomètre à mercure"],"b":2,"e":"Le faisceau d'électrons est dévié par des plaques."},{"q":"La déflexion verticale à la sortie des plaques est proportionnelle à :","r":["la masse uniquement","la couleur du faisceau","la longueur du fil d'alimentation","la tension appliquée aux plaques"],"b":3,"e":"C'est le principe de la mesure à l'oscilloscope."},{"q":"Le poids d'un électron est négligeable devant la force électrique car :","r":["sa masse est très petite (9,1 × 10⁻³¹ kg)","sa charge est nulle comparée à sa masse","g est nul dans le vide du tube","E est nul entre les armatures"],"b":0,"e":"mg ≈ 9 × 10⁻³⁰ N contre eE ≈ 10⁻¹⁵ N."},{"q":"Entre les plaques, le mouvement parallèle aux armatures est :","r":["accéléré","uniforme","nul","circulaire"],"b":1,"e":"Aucune force n'agit dans cette direction."},{"q":"Un ion positif est dévié :","r":["en sens contraire de E","pas du tout","dans le sens du champ E","perpendiculairement à E dans le plan des plaques"],"b":2,"e":"F = qE avec q > 0."},{"q":"L'énergie cinétique gagnée par une charge q sous une tension U vaut :","r":["q / U","U / q","q U²","|q| U"],"b":3,"e":"C'est le travail de la force électrique."},{"q":"Un électron accéléré sous 100 V gagne :","r":["100 eV","1 eV","1,6 × 10⁻¹⁷ eV","10 000 eV"],"b":0,"e":"W = eU = 100 eV."}],"c":"Tle D","m":"physique","rang":14,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un ancien téléviseur étudié au lycée technique de Douala, un faisceau d'électrons est dévié.","tache":"Explique pourquoi la trajectoire est courbée."},"gratuit":true});
VRT_L("tle-d-physique-r15",{"duree":25,"titre":"Mouvement dans un champ magnétique","accroche":"Séparer des isotopes grâce à la courbure de leur trajectoire.","intro":"Dans un champ magnétique uniforme, une particule chargée décrit un cercle.","objectifs":["établir le rayon de la trajectoire","calculer une période","appliquer au spectrographe"],"parties":[{"t":"Mouvement circulaire","html":"<div class='def'><b>Résultat</b>Avec v perpendiculaire à B, le mouvement est <strong>circulaire uniforme</strong> de rayon <strong>R = m v / (|q| B)</strong>.</div>"},{"t":"Période","verrou":true},{"t":"Spectrographe de masse","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":15,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Lors d'un concours scientifique, deux candidats, Akono et Benji, cherchent la tension qui dirige des ions dans un trou donné.","tache":"Présente les relations à utiliser."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r16",{"duree":15,"titre":"Généralités sur les systèmes oscillants","accroche":"Un balancier, un ressort, une corde de guitare : même idée.","intro":"Les systèmes oscillants reviennent périodiquement à leur position d'équilibre.","objectifs":["définir une oscillation","définir période et amplitude","lire une élongation"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>Un <strong>système oscillant</strong> effectue un mouvement de va-et-vient autour d'une position d'équilibre. La <strong>période</strong> T est la durée d'une oscillation.</div>"},{"t":"Élongation","verrou":true},{"t":"Types d'oscillations","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":16,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un ingénieur stagiaire de Limbé observe les oscillations d'un pont piéton lorsque des personnes marchent en cadence.","tache":"Dis quel type d'oscillation est en jeu."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r17",{"duree":25,"titre":"Pendule simple, amortissement et résonance","accroche":"La longueur règle le rythme d'un pendule.","intro":"Le pendule simple est un oscillateur classique : sa période dépend seulement de sa longueur et de g.","objectifs":["établir la période","définir l'amortissement","définir la résonance"],"parties":[{"t":"Le pendule simple","html":"<div class='def'><b>Résultat</b>Pour de faibles oscillations, la période d'un <strong>pendule simple</strong> est <strong>T = 2π √(L / g)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Amortissement et résonance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":17,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un horloger du marché Mokolo veut régler une horloge qui retarde.","tache":"Dis s'il doit raccourcir ou allonger le balancier."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r18",{"duree":25,"titre":"Le condensateur : charge, décharge et énergie","accroche":"Le flash d'un appareil photo stocke l'énergie d'un condensateur.","intro":"Un condensateur accumule des charges, puis les libère. Le temps caractéristique dépend de R et C.","objectifs":["relier q, C et U","décrire la charge","calculer l'énergie stockée"],"parties":[{"t":"Capacité","html":"<div class='def'><b>Définition</b>La <strong>capacité</strong> C d'un condensateur relie sa charge à sa tension : <strong>Q = C U</strong>. Elle s'exprime en farads.</div>"},{"t":"Charge et décharge","verrou":true},{"t":"Énergie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":18,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un réparateur de Douala doit changer un condensateur d'un poste radio. Il manipule un condensateur chargé.","tache":"Explique pourquoi il doit d'abord le décharger."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r20",{"duree":15,"titre":"La stroboscopie","accroche":"Un ventilateur qui semble immobile.","intro":"Une lumière clignotante peut donner l'illusion d'un mouvement arrêté ou ralenti.","objectifs":["définir la stroboscopie","obtenir l'immobilité apparente","mesurer une fréquence"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>La <strong>stroboscopie</strong> consiste à éclairer un objet en mouvement périodique par des éclairs brefs et réguliers.</div>"},{"t":"Immobilité apparente","verrou":true},{"t":"Mouvement ralenti","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":20,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un réparateur de ventilateurs de Bafang veut mesurer la vitesse de rotation de son moteur sans le toucher.","tache":"Propose une méthode."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r21",{"duree":25,"titre":"Ondes progressives","accroche":"L'onde avance, la matière reste sur place.","intro":"Une onde mécanique transporte de l'énergie sans transporter de matière.","objectifs":["distinguer ondes transversales et longitudinales","utiliser λ = v/f","comparer le mouvement de deux points"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une <strong>onde mécanique</strong> est la propagation d'une perturbation dans un milieu matériel, sans transport de matière. Elle est <strong>transversale</strong> ou <strong>longitudinale</strong>.</div>"},{"t":"Grandeurs","verrou":true},{"t":"Comparer deux points","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":21,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un musicien de Bafoussam accorde son balafon. Il cherche la longueur d'onde d'un son de 440 Hz dans l'air.","tache":"Calcule-la avec v = 340 m/s."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r22",{"duree":25,"titre":"Superposition et interférences mécaniques","accroche":"Deux ondes peuvent s'additionner ou s'annuler.","intro":"Là où deux ondes se croisent, leurs effets s'additionnent et dessinent des franges.","objectifs":["énoncer le principe de superposition","définir les interférences","calculer un état vibratoire"],"parties":[{"t":"Superposition","html":"<div class='def'><b>Principe</b>En un point atteint par deux ondes, l'élongation résultante est la <strong>somme des élongations</strong>.</div>"},{"t":"Interférences","verrou":true},{"t":"Construction de Fresnel","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":22,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Deux pointes fixées à un diapason de 200 Hz frappent une surface d'eau. La vitesse des ondes est 0,4 m/s.","tache":"Détermine l'état d'un point situé à 18 mm d'une source et à 9 mm de l'autre."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r23",{"duree":25,"titre":"Diffraction et interférences lumineuses","accroche":"La lumière se comporte comme une onde.","intro":"Les expériences de diffraction et d'interférences révèlent la nature ondulatoire de la lumière.","objectifs":["décrire la diffraction","utiliser l'interfrange","calculer une longueur d'onde"],"parties":[{"t":"Diffraction","html":"<div class='def'><b>Définition</b>La <strong>diffraction</strong> est le phénomène d'étalement d'une onde au passage d'un obstacle ou d'une ouverture de faible dimension.</div>"},{"t":"Interférences de Young","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":23,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Le lycée de Nkola a reçu un laser dont la fréquence indiquée doit être vérifiée. Les élèves mesurent 6 interfranges, avec a = 0,2 mm et D = 1,5 m.","tache":"Explique comment calculer la longueur d'onde."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r24",{"duree":25,"titre":"L'effet photoélectrique","accroche":"La lumière peut arracher des électrons à un métal.","intro":"Einstein a expliqué ce phénomène par l'existence de photons.","objectifs":["définir l'effet photoélectrique","énoncer l'équation d'Einstein","calculer une énergie cinétique"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>effet photoélectrique</strong> est l'extraction d'électrons d'un métal éclairé par une radiation de fréquence suffisante.</div>"},{"t":"Équation d'Einstein","html":"<p class='formule'>h c / λ = W₀ + E_c max</p><p>Le <strong>potentiel d'arrêt</strong> U₀ vérifie E_c max = e U₀.</p>","labo":{"type":"calcul","f":"photo","vals":{"l":633,"w":1.8}}},{"t":"Le seuil","html":"<p>Il n'y a pas d'émission si la fréquence est inférieure au seuil ν₀ = W₀ / h, quelle que soit l'intensité.</p>","retenir":"1 eV = 1,6 × 10⁻¹⁹ J."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> L'effet photoélectrique est :</p><ol type='a'><li>l'émission de lumière par un métal chauffé</li><li>la déviation de la lumière</li><li>l'émission d'électrons par un métal éclairé</li><li>la diffraction des électrons</li></ol><details><summary>Voir la réponse</summary><p><strong>l'émission d'électrons par un métal éclairé</strong>. Il a été expliqué par Einstein en 1905.</p></details><p><strong>Application directe des savoirs.</strong></p><p>λ = 500 nm, W₀ = 2 eV. Calcule Ec max.</p><details><summary>Voir la réponse</summary><p>(Réponse : environ 0,48 eV.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> On éclaire une cathode de césium (travail d'extraction 1,9 eV) avec une lumière bleue de 450 nm, puis rouge de 700 nm. hc = 1 240 eV·nm.</p><p><strong>Consigne 1.</strong> Calcule la longueur d'onde seuil du césium.</p><p><strong>Consigne 2.</strong> Examine s'il y a émission d'électrons dans chaque cas et calcule l'énergie cinétique maximale éventuelle.</p><details><summary>Voir une réponse attendue</summary><p>λ₀ = 1 240/1,9 ≈ 653 nm. Bleu : E = 1 240/450 ≈ 2,76 eV > 1,9 eV, émission avec Ec max ≈ 0,86 eV. Rouge : 1 240/700 ≈ 1,77 eV &lt; 1,9 eV, aucune émission, quelle que soit l'intensité.</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique face aux résultats."}],"revision":["Photon : E = hν.","hc/λ = W₀ + Ec.","Seuil."],"exo":"<p>λ = 500 nm, W₀ = 2 eV. Calcule Ec max. <em>(Réponse : environ 0,48 eV.)</em></p>","quiz":[{"q":"L'effet photoélectrique est :","r":["l'émission de lumière par un métal chauffé","la déviation de la lumière","l'émission d'électrons par un métal éclairé","la diffraction des électrons"],"b":2,"e":"Il a été expliqué par Einstein en 1905."},{"q":"L'effet photoélectrique ne se produit que si :","r":["l'intensité lumineuse reçue par le métal dépasse une valeur seuil","le métal est chauffé au-delà de 100 °C","la lumière est blanche et non monochromatique","la fréquence de la lumière dépasse une fréquence seuil"],"b":3,"e":"C'est indépendant de l'intensité."},{"q":"L'énergie d'un photon vaut :","r":["E = h ν","E = h / ν","E = ν / h","E = m c"],"b":0,"e":"h est la constante de Planck."},{"q":"La constante de Planck vaut environ :","r":["1,6 × 10⁻¹⁹ J·s","6,63 × 10⁻³⁴ J·s","3 × 10⁸ J·s","6,67 × 10⁻¹¹ J·s"],"b":1,"e":"C'est une constante fondamentale."},{"q":"Le travail d'extraction W₀ est :","r":["l'énergie du photon incident","l'énergie cinétique maximale de l'électron émis par le métal éclairé","l'énergie minimale pour arracher un électron du métal","la tension appliquée dans le circuit"],"b":2,"e":"Il dépend du métal."},{"q":"L'énergie cinétique maximale des électrons émis vaut :","r":["hν + W₀","W₀ − hν","hν","hν − W₀"],"b":3,"e":"C'est la relation d'Einstein."},{"q":"Augmenter l'intensité lumineuse (au-dessus du seuil) augmente :","r":["le nombre d'électrons émis","l'énergie cinétique de chaque électron","la fréquence seuil","le travail d'extraction"],"b":0,"e":"Plus de photons arrachent plus d'électrons."},{"q":"L'effet photoélectrique montre que la lumière :","r":["est uniquement une onde, sans aspect corpusculaire","est formée de photons (aspect corpusculaire)","n'a pas d'énergie propre","est faite d'électrons"],"b":1,"e":"Il complète l'aspect ondulatoire."},{"q":"1 eV vaut :","r":["1 J","6,63 × 10⁻³⁴ J","1,6 × 10⁻¹⁹ J","9,1 × 10⁻³¹ J"],"b":2,"e":"C'est l'énergie gagnée par un électron sous 1 V."},{"q":"Les cellules photovoltaïques et les capteurs photoélectriques reposent sur :","r":["la gravitation entre le photon et l'électron","la radioactivité du métal éclairé","l'effet Doppler","l'interaction photon-électron"],"b":3,"e":"Les photons libèrent des électrons."}],"c":"Tle D","m":"physique","rang":24,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un laboratoire du lycée de Bafoussam, on éclaire une cellule dont le travail d'extraction est 1,8 eV avec une lumière de 633 nm.","tache":"Dis si des électrons sont émis."},"gratuit":true});
VRT_L("tle-d-physique-r25",{"duree":25,"titre":"Le noyau atomique","accroche":"La masse d'un noyau est inférieure à celle de ses nucléons.","intro":"Le défaut de masse correspond à l'énergie qui lie les nucléons.","objectifs":["décrire le noyau","calculer un défaut de masse","comparer la stabilité"],"parties":[{"t":"Constitution","html":"<div class='def'><b>Définitions</b>Un noyau ᴬ_Z X contient Z protons et N = A − Z neutrons. Des <strong>isotopes</strong> ont le même Z et des A différents.</div>"},{"t":"Énergie de liaison","verrou":true},{"t":"Stabilité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":25,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un cours sur l'énergie à Yaoundé, on compare la stabilité de plusieurs noyaux.","tache":"Dis quelle grandeur permet la comparaison."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r26",{"duree":20,"titre":"La radioactivité : les réactions nucléaires","accroche":"Un noyau peut se transformer spontanément.","intro":"Les noyaux instables se désintègrent en émettant des particules. Leur équation se déduit de lois de conservation.","objectifs":["définir la radioactivité","citer les types","écrire une équation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>radioactivité</strong> est la désintégration spontanée d'un noyau instable, en émettant des particules et souvent un rayonnement γ.</div>"},{"t":"Types","verrou":true},{"t":"Lois de conservation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":26,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un hôpital de Yaoundé, un technicien explique qu'un traceur médical se transforme naturellement dans le temps.","tache":"Écris les règles à respecter pour une équation nucléaire."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r27",{"duree":25,"titre":"Activité et loi de décroissance radioactive","accroche":"La moitié des noyaux disparaît à chaque demi-vie.","intro":"La décroissance radioactive suit une loi exponentielle, utilisée aussi pour la datation.","objectifs":["énoncer la loi","calculer une activité","calculer une date"],"parties":[{"t":"La loi","html":"<div class='def'><b>Loi</b><strong>N(t) = N₀ e^(−λt)</strong>. La demi-vie vaut <strong>T = ln 2 / λ</strong>. L'activité vaut <strong>A = λN</strong>, en becquerels.</div>"},{"t":"Type bac","verrou":true},{"t":"Applications","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":27,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un archéologue de Douala analyse des restes de bois dans un site ancien de l'Adamaoua.","tache":"Explique le principe de datation au carbone 14."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r28",{"duree":20,"titre":"Les réactions nucléaires provoquées","accroche":"Fusion dans le Soleil, fission dans les centrales.","intro":"Une réaction nucléaire peut être provoquée. Elle libère alors une énergie considérable.","objectifs":["distinguer fission et fusion","calculer l'énergie libérée","citer des applications"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>La <strong>fission</strong> est la rupture d'un noyau lourd sous l'impact d'un neutron. La <strong>fusion</strong> est l'union de deux noyaux légers.</div>"},{"t":"Énergie","verrou":true},{"t":"Applications","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":28,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Lors d'un débat, Amina dit que le Soleil fonctionne « comme une centrale nucléaire » ; Paul répond que la centrale casse des noyaux lourds alors que le Soleil assemble des noyaux légers. On donne : ²³⁵U + n → ⁹⁴Sr + ¹⁴⁰Xe + 2n et 4 ¹H → ⁴He + 2 e⁺.","tache":"Départage Amina et Paul en nommant chaque réaction."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r29",{"duree":15,"titre":"Dangers des rayonnements et radioprotection","accroche":"Trois règles : temps, distance, écran.","intro":"Les rayonnements sont utiles en médecine, mais ils peuvent être dangereux. Il faut savoir s'en protéger.","objectifs":["citer les dangers","citer les moyens de protection","connaître les signes de danger"],"parties":[{"t":"Les dangers","html":"<div class='def'><b>Définition</b>L'<strong>exposition aux rayonnements ionisants</strong> peut léser les cellules et causer des brûlures ou des cancers. La dose s'évalue en sieverts.</div>"},{"t":"Se protéger","verrou":true},{"t":"Au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":29,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Des enfants ont trouvé près d'une ancienne décharge à Douala un objet portant le symbole radioactif.","tache":"Indique ce qu'il faut faire."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r09",{"duree":20,"titre":"Les paramètres cinématiques","accroche":"Position, vitesse, accélération : les trois mots du mouvement.","intro":"Pour décrire un mouvement, on choisit un référentiel et on suit la position, la vitesse et l'accélération.","objectifs":["définir les paramètres","dériver les équations","identifier un mouvement"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>La <strong>vitesse</strong> est la dérivée de la position par rapport au temps. L'<strong>accélération</strong> est la dérivée de la vitesse.</div>"},{"t":"Mouvements","verrou":true},{"t":"Relation utile","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":9,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Sur la route Douala-Yaoundé, un car accélère de façon constante sur une portion droite.","tache":"Indique la nature du mouvement."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r10",{"duree":20,"titre":"Les lois de Newton","accroche":"Trois lois pour expliquer tous les mouvements.","intro":"Les lois de Newton relient les forces et les mouvements.","objectifs":["énoncer les trois lois","appliquer le théorème du centre d'inertie","utiliser le théorème de l'énergie cinétique"],"parties":[{"t":"Les trois lois","html":"<div class='def'><b>Lois de Newton</b><strong>Première loi</strong> : dans un référentiel galiléen, si la somme des forces est nulle, le mouvement du centre d'inertie est rectiligne uniforme ou nul. <strong>Deuxième loi</strong> : ΣF = ma. <strong>Troisième loi</strong> : action et réaction sont opposées.</div>"},{"t":"Théorème de l'énergie cinétique","verrou":true},{"t":"Application","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":10,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un car roule à 72 km/h sur l'axe Bertoua-Batouri ; le chauffeur freine brusquement et le car s'arrête en 4 s. Un passager sans ceinture, de 70 kg, est projeté vers l'avant.","tache":"Explique la projection par une loi de Newton et calcule la force que la ceinture aurait dû exercer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r13",{"duree":25,"titre":"Le mouvement d'un satellite","accroche":"Identifier un satellite géostationnaire par le calcul.","intro":"Un satellite en orbite circulaire est soumis uniquement à la gravitation.","objectifs":["calculer la vitesse orbitale","calculer la période","caractériser l'orbite géostationnaire"],"parties":[{"t":"Vitesse orbitale","html":"<div class='def'><b>Résultat</b>Sur une orbite circulaire : <strong>v = R √(g₀ / (R + h))</strong>. La période vaut <strong>T = 2π(R + h) / v</strong>.</div>"},{"t":"Orbite géostationnaire","verrou":true},{"t":"Troisième loi de Kepler","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":13,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Lors d'un concours scientifique, deux candidats, Akono et Benji, doivent identifier un satellite géostationnaire dans une liste.","tache":"Indique comment départager leurs réponses."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-physique-r19",{"duree":25,"titre":"Circuit RLC : impédance et déphasage","accroche":"Une seule formule pour trois composants.","intro":"En régime sinusoïdal, un circuit RLC est caractérisé par son impédance.","objectifs":["calculer une impédance","relier tensions maximale et efficace","calculer un déphasage"],"parties":[{"t":"Impédance","html":"<div class='def'><b>Définition</b>L'<strong>impédance</strong> d'un circuit RLC série est <strong>Z = √(R² + (Lω − 1/(Cω))²)</strong>. On a U = Z I.</div>"},{"t":"Tensions","verrou":true},{"t":"Déphasage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"physique","rang":19,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans une station de radio de Bafoussam, un technicien règle un circuit RLC avec L = 0,1 H, r = 2 Ω et C = 2 µF sous 50 Hz.","tache":"Présente le calcul de l'impédance."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r02",{"duree":20,"titre":"Osmose et dialyse : interpréter les échanges d'eau","accroche":"Une feuille d'oignon plasmolysée dans l'eau salée.","intro":"L'eau traverse la membrane selon la concentration des milieux. C'est un phénomène demandé chaque année.","objectifs":["définir osmose et dialyse","prévoir le sens de l'eau","interpréter turgescence et plasmolyse"],"parties":[{"t":"Osmose et dialyse","html":"<div class='def'><b>Définition</b>L'<strong>osmose</strong> est le passage de l'eau à travers une membrane, du milieu le moins concentré vers le milieu le plus concentré. La <strong>dialyse</strong> est le passage de petites molécules de solutés.</div>"},{"t":"Les trois milieux","verrou":true},{"t":"Le cas des globules rouges","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":2,"apc":{"module":"Échanges et métabolisme","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Ton camarade s'étonne que des cellules animales vivant en eau de mer gardent leur aspect normal, alors qu'une cellule en milieu hypertonique se crénelle.","tache":"Explique ce qui leur permet de limiter la perte d'eau."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r03",{"duree":20,"titre":"Échanges de substances dissoutes","accroche":"Une cellule peut accumuler une substance contre son gradient.","intro":"La membrane contrôle ce qui entre et sort. Le transport peut être passif ou actif.","objectifs":["distinguer transports passif et actif","citer les protéines de transport","expliquer la pompe Na⁺/K⁺"],"parties":[{"t":"Le transport passif","html":"<div class='def'><b>Définition</b>Le <strong>transport passif</strong> s'effectue dans le sens du gradient de concentration, sans dépense d'énergie : diffusion simple ou facilitée.</div>"},{"t":"Le transport actif","verrou":true},{"t":"Importance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":3,"apc":{"module":"Échanges et métabolisme","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Pendant une diarrhée, un infirmier de Maroua conseille à une mère une solution de réhydratation contenant sel et sucre.","tache":"Explique le lien avec les transports intestinaux."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r04",{"duree":20,"titre":"Intégration : les échanges cellulaires","accroche":"Sérum physiologique ou eau pure ?","intro":"Une erreur de perfusion peut être très dangereuse. Cette situation mobilise les échanges cellulaires.","objectifs":["mobiliser les échanges","argumenter","rédiger une réponse"],"parties":[{"t":"Compétence","html":"<div class='def'><b>Définition</b>Une <strong>solution isotonique</strong> au sang ne provoque pas de flux net d'eau pour les globules rouges.</div>"},{"t":"Analyse","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":4,"apc":{"module":"Échanges et métabolisme","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Un aide-soignant de Bertoua veut remplacer une perfusion de sérum physiologique par de l'eau distillée.","tache":"Explique le danger."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r05",{"duree":20,"titre":"Structure de la fibre musculaire","accroche":"Des filaments qui glissent font bouger tout le corps.","intro":"La fibre musculaire est organisée en unités contractiles répétées : les sarcomères.","objectifs":["décrire la fibre musculaire","définir le sarcomère","citer les protéines"],"parties":[{"t":"Le sarcomère","html":"<div class='def'><b>Définition</b>Le <strong>sarcomère</strong> est l'unité contractile de la myofibrille, compris entre deux stries Z. Il contient des filaments d'actine et de myosine.</div>"},{"t":"Composition","verrou":true},{"t":"Bandes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":5,"apc":{"module":"Échanges et métabolisme","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Un sportif de Limbé veut comprendre l'aspect strié de ses muscles observés au microscope.","tache":"Explique cet aspect."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r06",{"duree":20,"titre":"Mécanisme de la contraction musculaire","accroche":"Le muscle raccourcit, mais les filaments ne raccourcissent pas.","intro":"Le raccourcissement du sarcomère résulte du glissement des filaments, grâce au calcium et à l'ATP.","objectifs":["expliquer le glissement","préciser le rôle du Ca²⁺","préciser le rôle de l'ATP"],"parties":[{"t":"Le glissement","html":"<div class='def'><b>Définition</b>La <strong>contraction</strong> résulte du glissement des filaments d'actine entre les filaments de myosine, ce qui raccourcit le sarcomère.</div>"},{"t":"Le calcium","verrou":true},{"t":"L'ATP","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":6,"apc":{"module":"Échanges et métabolisme","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Sur deux électronographies d'un même muscle de sportif, un sarcomère mesure 2,5 µm au repos et 2,0 µm en contraction ; la bande A mesure 1,5 µm dans les deux cas.","tache":"Schématise l'unité contractile dans les deux états et indique les différences à faire ressortir."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r07",{"duree":20,"titre":"Restauration de l'ATP et adaptation à l'effort","accroche":"Un sprint et un marathon n'utilisent pas la même énergie.","intro":"L'ATP doit être renouvelé en permanence par différentes voies.","objectifs":["citer les voies de restauration","comparer les voies","expliquer l'adaptation"],"parties":[{"t":"Les voies","html":"<div class='def'><b>Définition</b>L'<strong>ATP</strong> est restauré par trois voies : la créatine phosphate, la fermentation lactique et la respiration.</div>"},{"t":"Comparaison","verrou":true},{"t":"Adaptation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":7,"apc":{"module":"Échanges et métabolisme","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Un coureur de la course de l'Espoir au mont Cameroun veut adapter son entraînement.","tache":"Dis quelle voie dominera pendant cette longue épreuve."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r08",{"duree":20,"titre":"Intégration : préparer un effort","accroche":"Crampes et fatigue : comprendre avant de s'entraîner.","intro":"Un entraîneur doit expliquer à ses athlètes pourquoi ils s'épuisent.","objectifs":["mobiliser le métabolisme","conseiller","argumenter"],"parties":[{"t":"Compétence","html":"<div class='def'><b>Définition</b>L'<strong>acide lactique</strong> et l'épuisement des réserves participent à la fatigue au cours d'un effort intense.</div>"},{"t":"Conseils","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":8,"apc":{"module":"Échanges et métabolisme","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Un jeune footballeur de Douala se plaint de crampes dès qu'il court longtemps.","tache":"Propose des conseils argumentés."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r09",{"duree":20,"titre":"Structure et rôle des gonades des mammifères","accroche":"Le testicule et l'ovaire ont une double fonction.","intro":"Les gonades produisent les gamètes et des hormones.","objectifs":["décrire testicule et ovaire","citer leurs fonctions","identifier les tissus"],"parties":[{"t":"Les gonades","html":"<div class='def'><b>Définition</b>Les <strong>gonades</strong> sont les organes producteurs de gamètes : le <strong>testicule</strong> chez le mâle et l'<strong>ovaire</strong> chez la femelle.</div>"},{"t":"Le testicule","verrou":true},{"t":"L'ovaire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":9,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Lors d'un TP au lycée de Mbouda, on dissèque un petit mammifère pour observer les organes reproducteurs.","tache":"Indique les précautions et l'objectif."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r10",{"duree":20,"titre":"Gonades des spermaphytes","accroche":"Étamines et pistil : les organes de la fleur.","intro":"Chez les plantes à fleurs, les gamètes se forment dans les organes de la fleur.","objectifs":["décrire la fleur","citer les organes reproducteurs","identifier le pollen et l'ovule"],"parties":[{"t":"La fleur","html":"<div class='def'><b>Définition</b>Chez les <strong>spermaphytes</strong>, l'<strong>étamine</strong> est l'organe mâle et le <strong>pistil</strong> l'organe femelle.</div>"},{"t":"Étamine","verrou":true},{"t":"Pistil","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":10,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Une agricultrice de Foumban observe que ses fleurs de tomate fécondées forment des fruits.","tache":"Identifie l'organe devenu fruit."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r11",{"duree":20,"titre":"La méiose","accroche":"Deux divisions pour passer de 2n à n.","intro":"La méiose produit des cellules haploïdes et brasse l'information génétique.","objectifs":["décrire les deux divisions","expliquer le passage de 2n à n","expliquer les brassages"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>méiose</strong> est une suite de deux divisions qui donne, à partir d'une cellule diploïde (2n), quatre cellules haploïdes (n).</div>"},{"t":"Les divisions","verrou":true},{"t":"Les brassages","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":11,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Un élève de Dschang se demande pourquoi deux frères n'ont pas le même patrimoine génétique.","tache":"Explique le rôle de la méiose."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r12",{"duree":20,"titre":"Gamétogenèse chez les mammifères","accroche":"Spermatogenèse continue, ovogenèse cyclique.","intro":"Les gamètes se forment à la suite de phases successives, différentes chez le mâle et chez la femelle.","objectifs":["décrire la spermatogenèse","décrire l'ovogenèse","comparer"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>gamétogenèse</strong> est la formation des gamètes. Elle comprend les phases de multiplication, d'accroissement, de maturation et, chez le mâle, de différenciation.</div>"},{"t":"Comparaison","verrou":true},{"t":"Rythme","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":12,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Un exposé du club santé au lycée de Bafoussam compare la production de gamètes chez l'homme et la femme.","tache":"Présente deux différences."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r13",{"duree":20,"titre":"Gamétogenèse chez les spermaphytes","accroche":"Un grain de pollen contient un gamétophyte minuscule.","intro":"Chez les plantes à fleurs, les gamètes se forment dans le grain de pollen et le sac embryonnaire.","objectifs":["décrire la formation du pollen","décrire le sac embryonnaire","comparer aux mammifères"],"parties":[{"t":"Pollen","html":"<div class='def'><b>Définition</b>Le <strong>grain de pollen</strong> mûr contient une cellule végétative et une cellule reproductrice, qui donnera deux gamètes mâles.</div>"},{"t":"Sac embryonnaire","verrou":true},{"t":"Rôle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":13,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Au champ-école de Mbalmayo, on explique comment se forme le grain de pollen.","tache":"Dis ce qu'il renferme à maturité."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r14",{"duree":20,"titre":"La fécondation chez les mammifères","accroche":"Une rencontre qui rétablit 2n.","intro":"La fécondation unit deux gamètes et compense la méiose.","objectifs":["décrire les étapes","expliquer le rétablissement de 2n","préciser son importance"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>fécondation</strong> est l'union d'un gamète mâle et d'un gamète femelle, formant une cellule-œuf diploïde.</div>"},{"t":"Les étapes","verrou":true},{"t":"Importance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":14,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Au centre de procréation médicalement assistée de Yaoundé, un biologiste photographie un ovule fécondé in vitro : 1 h, ovocyte entouré de spermatozoïdes ; 6 h, deux pronucléi éloignés ; 12 h, pronucléi accolés ; 24 h, embryon à deux cellules.","tache":"Classe et explique ces étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r15",{"duree":20,"titre":"La fécondation chez les spermaphytes","accroche":"Une double fécondation propre aux plantes à fleurs.","intro":"Chez les angiospermes, deux fécondations se produisent dans l'ovule.","objectifs":["décrire la pollinisation","expliquer la double fécondation","comparer aux mammifères"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>double fécondation</strong> : un gamète mâle féconde l'oosphère (œuf principal, 2n) ; l'autre féconde le noyau secondaire (albumen, 3n).</div>"},{"t":"Le trajet","verrou":true},{"t":"Conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":15,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Un paysan de Dschang demande pourquoi les abeilles sont utiles à sa récolte.","tache":"Explique leur rôle."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r16",{"duree":20,"titre":"Intégration : reproduction et continuité de l'espèce","accroche":"Méiose et fécondation se complètent.","intro":"L'alternance méiose-fécondation maintient le nombre de chromosomes de l'espèce.","objectifs":["relier méiose et fécondation","exploiter un document","argumenter"],"parties":[{"t":"Rappel","html":"<div class='def'><b>Définition</b>La <strong>méiose</strong> divise le nombre de chromosomes par deux ; la <strong>fécondation</strong> le rétablit.</div>"},{"t":"Exploiter un document","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":16,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Dans un exposé à Limbé, un élève affirme que les enfants ont 92 chromosomes, puisqu'ils reçoivent les 46 de leur père et les 46 de leur mère.","tache":"Corrige-le en expliquant le rôle de la méiose et de la fécondation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r17",{"duree":20,"titre":"Monohybridisme avec dominance","accroche":"Les lois de Mendel à partir d'un seul caractère.","intro":"Un croisement entre lignées pures permet de déduire le mode de transmission d'un caractère.","objectifs":["définir les termes","établir un échiquier","analyser un test-cross"],"parties":[{"t":"Vocabulaire","html":"<div class='def'><b>Définition</b>Le <strong>monohybridisme</strong> étudie la transmission d'un seul caractère. Un allèle <strong>dominant</strong> s'exprime chez l'hétérozygote, l'allèle <strong>récessif</strong> y est masqué.</div>"},{"t":"Résultats","verrou":true},{"t":"Test-cross","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":17,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Un éleveur de porcs de Bafia remarque des naissances à longue et courte queue dans une même portée.","tache":"Propose une démarche pour comprendre ce résultat."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r18",{"duree":20,"titre":"Dominance intermédiaire","accroche":"F₁ ne ressemble à aucun des parents.","intro":"Parfois, aucun allèle ne domine l'autre : l'hétérozygote est intermédiaire.","objectifs":["reconnaître l'absence de dominance","établir les proportions","écrire l'échiquier"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>En <strong>dominance intermédiaire</strong> (ou codominance selon le cas), l'hétérozygote présente un phénotype propre.</div>"},{"t":"Résultats","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":18,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Une fleuriste de Buea obtient des fleurs roses en croisant des fleurs rouges et blanches.","tache":"Explique ce résultat."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r19",{"duree":20,"titre":"Monohybridisme gonosomal","accroche":"Le sexe du parent change les résultats.","intro":"Quand un gène est porté par un chromosome sexuel, les résultats diffèrent selon le sens du croisement.","objectifs":["reconnaître une transmission gonosomale","écrire les génotypes","analyser des croisements réciproques"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un gène <strong>gonosomal</strong> est porté par un chromosome sexuel, le plus souvent X.</div>"},{"t":"Indices","verrou":true},{"t":"Écriture","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":19,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Un éleveur de volailles à Bafoussam observe que certains caractères diffèrent selon le sexe.","tache":"Dis ce que cela suggère."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r20",{"duree":20,"titre":"Le dihybridisme","accroche":"Deux caractères, seize cases.","intro":"Le dihybridisme étudie la transmission simultanée de deux caractères.","objectifs":["établir un échiquier","reconnaître 9-3-3-1","interpréter un test-cross"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>dihybridisme</strong> étudie la transmission de deux caractères. Pour des gènes indépendants, on obtient en F₂ les proportions <strong>9/16 - 3/16 - 3/16 - 1/16</strong>.</div>"},{"t":"Test-cross","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":20,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Un agronome de l'Ouest croise deux variétés de maïs différant par deux caractères.","tache":"Dis quels résultats attendre en F₂ si les gènes sont indépendants."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r21",{"duree":20,"titre":"Le trihybridisme","accroche":"Trois caractères, huit types de gamètes.","intro":"En généralisant le raisonnement, on prédit les résultats pour trois caractères.","objectifs":["calculer le nombre de gamètes","calculer des proportions","généraliser"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>Pour n gènes indépendants, un hétérozygote produit <strong>2ⁿ</strong> types de gamètes.</div>"},{"t":"Exemple","verrou":true},{"t":"Proportion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":21,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Un agronome de Kumba croise deux variétés de haricot qui diffèrent par trois caractères (couleur, forme, taille), chacun gouverné par un gène, les trois gènes étant indépendants. La F1 est hétérozygote pour les trois gènes.","tache":"Donne le nombre de types de gamètes de la F1 et la méthode pour le trouver."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r22",{"duree":20,"titre":"Le brassage intrachromosomique","accroche":"Des gènes liés peuvent se séparer.","intro":"Si les gènes sont portés par le même chromosome, les proportions diffèrent.","objectifs":["reconnaître des gènes liés","calculer un pourcentage de recombinaison","expliquer le crossing-over"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Des <strong>gènes liés</strong> sont portés par le même chromosome. Le <strong>crossing-over</strong> produit des gamètes recombinés.</div>"},{"t":"Test-cross","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":22,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Dans une expérience de génétique, un test-cross donne deux phénotypes parentaux à 45 % chacun et deux recombinés à 5 % chacun.","tache":"Conclus."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r23",{"duree":20,"titre":"Quelques exceptions à la monogénie","accroche":"Un caractère n'est pas toujours porté par un seul gène.","intro":"Plusieurs gènes peuvent agir sur un caractère, ou un allèle peut être létal.","objectifs":["reconnaître une épistasie","reconnaître un allèle létal","interpréter les proportions"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>allèle létal</strong> provoque la mort des homozygotes. Il modifie les proportions attendues en 2/3 - 1/3.</div>"},{"t":"Polygénie","verrou":true},{"t":"Interactions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":23,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Un éleveur de porcs de Bafia croise entre eux des porcs au dos ceinturé ; sur 60 porcelets nés vivants, 40 sont ceinturés et 20 non ceinturés, et plusieurs porcelets meurent avant la naissance à chaque portée.","tache":"Propose une hypothèse expliquant ces proportions."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r24",{"duree":20,"titre":"Mutations et importance du brassage","accroche":"Une erreur de copie peut créer un nouvel allèle.","intro":"Les mutations créent les nouveaux allèles ; les brassages les combinent.","objectifs":["définir une mutation","distinguer mutations géniques et chromosomiques","expliquer l'importance"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>mutation</strong> est une modification héréditaire de l'ADN. Elle est <strong>génique</strong> ou <strong>chromosomique</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Importance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":24,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Dans un exposé à Douala, un élève soutient que toutes les mutations sont mauvaises.","tache":"Nuance cette affirmation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r25",{"duree":20,"titre":"Intégration : brassages et unicité génétique","accroche":"Aucun enfant n'est la copie de ses parents.","intro":"Deux parents peuvent donner naissance à des enfants très différents.","objectifs":["mobiliser les brassages","rédiger un argument","proposer un slogan"],"parties":[{"t":"Rappel","html":"<div class='def'><b>Définition</b>Les <strong>brassages</strong> inter et intrachromosomiques, puis la fécondation, créent des individus génétiquement uniques.</div>"},{"t":"Argumenter","verrou":true},{"t":"Méthode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":25,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Dans une famille de Bafang, on reproche à un enfant de ne pas ressembler à ses frères.","tache":"Explique scientifiquement ces différences."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r26",{"duree":20,"titre":"Notion d'arbre généalogique","accroche":"Un dessin qui suit une maladie sur plusieurs générations.","intro":"L'arbre généalogique permet d'analyser la transmission d'un caractère dans une famille.","objectifs":["lire un arbre","déterminer la dominance","déterminer le chromosome porteur"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>arbre généalogique</strong> représente les membres d'une famille et la présence d'un caractère. Les carrés désignent les hommes, les cercles, les femmes.</div>"},{"t":"Méthode","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":26,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Le couple X a des enfants drépanocytaires, alors que les deux parents sont bien portants.","tache":"Explique à l'aide d'un arbre."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r27",{"duree":20,"titre":"Transmissions autosomiques","accroche":"Albinisme, drépanocytose, achondroplasie.","intro":"Certaines maladies se transmettent par des gènes portés par des autosomes.","objectifs":["reconnaître le mode de transmission","écrire les génotypes","calculer un risque"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une transmission <strong>autosomique</strong> concerne un gène porté par un chromosome non sexuel. Elle est récessive ou dominante.</div>"},{"t":"Exemples","verrou":true},{"t":"Risque","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":27,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Dans une campagne à Douala sur la drépanocytose (allèle S récessif), on présente quatre couples : AA × AS ; AS × AS ; AS × SS ; AA × SS.","tache":"Calcule pour chaque couple le risque d'enfant SS et dis quelles unions présenter comme à risque."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r28",{"duree":20,"titre":"Transmissions gonosomiques","accroche":"Daltonisme et hémophilie touchent surtout les garçons.","intro":"Une maladie portée par X s'exprime plus souvent chez l'homme.","objectifs":["reconnaître une transmission liée à X","calculer un risque","expliquer le rôle de la mère"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une transmission <strong>gonosomique récessive</strong> liée à X touche davantage les hommes, qui ne possèdent qu'un chromosome X.</div>"},{"t":"Exemples","verrou":true},{"t":"Risque","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":28,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Une famille de Yaoundé a plusieurs garçons hémophiles et aucune fille atteinte.","tache":"Explique cette répartition."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r29",{"duree":20,"titre":"Évaluer un risque génétique","accroche":"Calculer pour conseiller.","intro":"Le conseil génétique évalue une probabilité pour aider une famille.","objectifs":["calculer une probabilité","distinguer risque et certitude","informer avec respect"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>risque génétique</strong> est la probabilité qu'un enfant présente une maladie héréditaire.</div>"},{"t":"Méthode","verrou":true},{"t":"Respect","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":29,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Un couple de Bafoussam, porteur de l'allèle S, consulte avant de se marier.","tache":"Présente les informations à lui communiquer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r30",{"duree":20,"titre":"Applications de la génétique humaine","accroche":"Dépister tôt pour mieux soigner.","intro":"Les connaissances génétiques permettent le diagnostic, le conseil et de nouveaux traitements.","objectifs":["citer des applications","discuter des limites","respecter l'éthique"],"parties":[{"t":"Applications","html":"<div class='def'><b>Définition</b>La <strong>génétique médicale</strong> utilise le caryotype, l'électrophorèse et l'analyse de l'ADN pour le dépistage et le diagnostic.</div>"},{"t":"Diagnostic prénatal","verrou":true},{"t":"Éthique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":30,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Dans un centre de santé de Kumba, on propose un dépistage de la drépanocytose aux jeunes couples.","tache":"Explique l'intérêt de ce dépistage."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r31",{"duree":20,"titre":"Intégration : limiter les maladies génétiques","accroche":"Causerie, échiquier, affiche et slogan.","intro":"Le bac demande de passer de la connaissance à l'action de sensibilisation.","objectifs":["préparer une causerie","présenter des échiquiers","rédiger un slogan"],"parties":[{"t":"Compétence","html":"<div class='def'><b>Définition</b><strong>Limiter la fréquence d'une maladie génétique</strong>, c'est informer, dépister et conseiller les familles.</div>"},{"t":"La causerie","verrou":true},{"t":"Affiche et slogan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":31,"apc":{"module":"Reproduction et génétique","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques au sein des familles","situation":"Le couple X a cinq enfants drépanocytaires, alors que les parents se disent en bonne santé. Un médecin te sollicite pour une campagne.","tache":"Présente un texte de causerie et un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r32",{"duree":20,"titre":"Structure du tissu nerveux","accroche":"Des milliards de cellules connectées.","intro":"Le tissu nerveux réunit les neurones et leurs cellules de soutien.","objectifs":["décrire un neurone","distinguer substance grise et blanche","préparer une dissection"],"parties":[{"t":"Le neurone","html":"<div class='def'><b>Définition</b>Le <strong>neurone</strong> est la cellule nerveuse. Il comprend un corps cellulaire, des dendrites et un axone.</div>"},{"t":"Substances grise et blanche","verrou":true},{"t":"Le nerf","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":32,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"En TP à Bamenda, un groupe prépare la dissection de l'encéphale d'un petit mammifère.","tache":"Cite trois règles à respecter."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r33",{"duree":20,"titre":"Réflexes innés : les éléments du réflexe médullaire","accroche":"La main se retire avant la douleur.","intro":"Un réflexe est une réponse involontaire, rapide et stéréotypée.","objectifs":["définir le réflexe","nommer les éléments de l'arc réflexe","exploiter une expérience"],"parties":[{"t":"L'arc réflexe","html":"<div class='def'><b>Définition</b>L'<strong>arc réflexe</strong> comprend un récepteur, une voie sensitive, un centre nerveux, une voie motrice et un effecteur.</div>"},{"t":"Le réflexe médullaire","verrou":true},{"t":"Les expériences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":33,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"En cuisine à Ebolowa, une fille retire brusquement sa main d'une marmite très chaude.","tache":"Présente le trajet du message."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r34",{"duree":20,"titre":"Le réflexe myotatique","accroche":"Le médecin frappe le genou, la jambe bouge.","intro":"L'étirement d'un muscle provoque sa contraction : ce réflexe assure la posture.","objectifs":["décrire le réflexe myotatique","expliquer son caractère monosynaptique","préciser son importance"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>réflexe myotatique</strong> est la contraction d'un muscle en réponse à son propre étirement.</div>"},{"t":"Le circuit","verrou":true},{"t":"Importance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":34,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Au dispensaire de Sangmélima, une infirmière teste le réflexe rotulien d'un patient.","tache":"Explique l'intérêt de ce test."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r35",{"duree":20,"titre":"Réflexes acquis ou conditionnels","accroche":"Le chien salive au son de la cloche.","intro":"Un apprentissage peut associer un stimulus neutre à une réponse réflexe.","objectifs":["décrire l'expérience de Pavlov","distinguer réflexe inné et acquis","donner des applications"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>réflexe conditionnel</strong> est une réponse acquise à la suite de l'association répétée d'un stimulus neutre et d'un stimulus absolu.</div>"},{"t":"Conditions","verrou":true},{"t":"Applications","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":35,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un élève de Kribi se réveille chaque matin juste avant la sonnerie de son réveil.","tache":"Propose une explication prudente."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r36",{"duree":20,"titre":"Intégration : les réflexes au service de la sécurité","accroche":"Un réflexe protège, l'alcool le retarde.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Un <strong>réflexe</strong> repose sur un circuit dont le fonctionnement peut être perturbé par des substances.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":36,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un conducteur de moto-taxi de Douala affirme qu'il freine aussi vite après avoir bu.","tache":"Montre-lui que l'alcool augmente le risque d'accident."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r37",{"duree":20,"titre":"Le potentiel de repos","accroche":"Une pile électrique dans chaque neurone.","intro":"Au repos, l'intérieur de la fibre nerveuse est négatif par rapport à l'extérieur.","objectifs":["définir le potentiel de repos","expliquer son origine ionique","lire un enregistrement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>potentiel de repos</strong> est la différence de potentiel d'environ −70 mV entre l'intérieur et l'extérieur d'une fibre au repos.</div>"},{"t":"Origine","html":"<p>La membrane est plus perméable au K⁺. La pompe Na⁺/K⁺ maintient les différences de concentration.</p>","retenir":"Intérieur négatif : environ −70 mV.","labo":{"type":"potentiel"}},{"t":"Mesure","html":"<p>Une microélectrode intracellulaire reliée à un oscilloscope révèle la différence de potentiel.</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Le potentiel de repos d'un neurone vaut environ :</p><ol type='a'><li>+30 mV</li><li>−70 mV</li><li>0 mV</li><li>−200 mV</li></ol><details><summary>Voir la réponse</summary><p><strong>−70 mV</strong>. L'intérieur de la cellule est négatif par rapport à l'extérieur.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Quelle est la valeur approchée du potentiel de repos ?</p><details><summary>Voir la réponse</summary><p>(Réponse : −70 mV.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Comprendre et préserver le système nerveux et les défenses de l'organisme.</p><p><strong>Situation.</strong> En TP, une microélectrode enfoncée dans un axone affiche −70 mV. On place l'axone dans une solution contenant du cyanure, qui bloque la production d'ATP : la valeur diminue lentement vers 0 mV.</p><p><strong>Consigne 1.</strong> Explique l'origine du potentiel de repos.</p><p><strong>Consigne 2.</strong> Interprète l'effet du cyanure.</p><details><summary>Voir une réponse attendue</summary><p>La membrane est polarisée : plus de K⁺ à l'intérieur, plus de Na⁺ à l'extérieur, et la membrane au repos est surtout perméable au K⁺, qui sort. La pompe Na⁺/K⁺, qui consomme de l'ATP, maintient ces différences. Sans ATP, la pompe s'arrête : les ions diffusent, les concentrations s'égalisent et le potentiel s'annule progressivement.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["−70 mV.","K⁺.","Pompe Na⁺/K⁺."],"exo":"<p>Quelle est la valeur approchée du potentiel de repos ? <em>(Réponse : −70 mV.)</em></p>","quiz":[{"q":"Le potentiel de repos d'un neurone vaut environ :","r":["+30 mV","−70 mV","0 mV","−200 mV"],"b":1,"e":"L'intérieur de la cellule est négatif par rapport à l'extérieur."},{"q":"Au repos, l'intérieur de la fibre nerveuse est :","r":["plus riche en Na⁺ et plus pauvre en K⁺ que l'extérieur","identique à l'extérieur en ions Na⁺ et K⁺","plus riche en K⁺ et plus pauvre en Na⁺ que l'extérieur","vide d'ions, seulement rempli de protéines"],"b":2,"e":"Ces différences sont maintenues par la pompe Na⁺/K⁺."},{"q":"La pompe Na⁺/K⁺ :","r":["fait entrer du Na⁺ et sortir du K⁺ sans dépenser aucune énergie","fonctionne sans consommer d'ATP","transporte du glucose dans la fibre","fait sortir du Na⁺ et entrer du K⁺ en consommant de l'ATP"],"b":3,"e":"Elle maintient les gradients ioniques."},{"q":"Le potentiel de repos se mesure avec :","r":["deux électrodes, l'une intracellulaire et l'autre extracellulaire","un thermomètre placé à la surface du nerf isolé","une balance de précision et un chronomètre","deux électrodes posées toutes deux à la surface de la fibre, côte à côte"],"b":0,"e":"On enregistre la différence de potentiel transmembranaire."},{"q":"Au repos, la membrane est surtout perméable :","r":["au Na⁺","au K⁺","aux protéines","au glucose"],"b":1,"e":"La fuite de K⁺ crée la négativité intérieure."},{"q":"Le cyanure, en bloquant la production d'ATP, entraîne à terme :","r":["son augmentation","aucun effet","la disparition du potentiel de repos","une hyperpolarisation permanente"],"b":2,"e":"La pompe Na⁺/K⁺ cesse de fonctionner."},{"q":"Le potentiel de repos est aussi appelé :","r":["potentiel d'action","potentiel postsynaptique","potentiel électrique du cœur","potentiel de membrane"],"b":3,"e":"Il existe dans toutes les cellules."},{"q":"L'oscilloscope affiche au repos :","r":["une ligne horizontale à environ −70 mV","des pics répétés de +30 mV","une courbe en cloche","une ligne horizontale à 0 mV, sans aucun écart"],"b":0,"e":"La tension reste constante."},{"q":"Les protéines intracellulaires chargées négativement :","r":["sortent de la cellule pendant le repos","participent à la négativité de l'intérieur","sont chargées positivement","n'ont aucun rôle électrique"],"b":1,"e":"Elles ne traversent pas la membrane."},{"q":"Le potentiel de repos est indispensable car :","r":["il produit les hormones du système nerveux","il contracte directement le muscle","il permet la naissance du potentiel d'action","il fournit l'ATP à la pompe"],"b":2,"e":"C'est l'état de départ de l'excitation."}],"c":"Tle D","m":"svt","rang":37,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Dans un TP à Bafoussam, l'oscilloscope affiche −70 mV dès l'entrée de l'électrode dans la fibre.","tache":"Interprète ce résultat."},"gratuit":true});
VRT_L("tle-d-svt-r38",{"duree":20,"titre":"Le potentiel d'action","accroche":"Tout ou rien : le neurone ne chuchote pas.","intro":"Une stimulation suffisante provoque une inversion brève du potentiel de membrane.","objectifs":["décrire le potentiel d'action","expliquer les mouvements d'ions","appliquer la loi du tout ou rien"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>potentiel d'action</strong> est une inversion brève et propagée de la polarité membranaire, déclenchée à partir d'un seuil.</div>"},{"t":"Les phases","verrou":true},{"t":"Propriétés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":38,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un élève de Mbalmayo augmente l'intensité d'un stimulus et croit que chaque potentiel d'action devient plus grand.","tache":"Corrige son idée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r39",{"duree":20,"titre":"Naissance du potentiel d'action","accroche":"De la lumière ou d'une pression naît un message nerveux.","intro":"Les récepteurs sensoriels transforment un stimulus en message nerveux.","objectifs":["définir le potentiel de récepteur","expliquer la transduction","préciser la zone d'initiation"],"parties":[{"t":"Le récepteur","html":"<div class='def'><b>Définition</b>La <strong>transduction</strong> est la transformation d'un stimulus en potentiel de récepteur dans un récepteur sensoriel.</div>"},{"t":"Le potentiel de récepteur","verrou":true},{"t":"Au niveau du neurone","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":39,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Une couturière de Garoua sent la piqûre d'une aiguille au bout du doigt.","tache":"Explique la naissance du message."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r40",{"duree":20,"titre":"Propagation du potentiel d'action","accroche":"Jusqu'à plus de 100 m/s sur certaines fibres.","intro":"Le potentiel d'action se propage de proche en proche ou de nœud en nœud.","objectifs":["comparer les conductions","calculer une vitesse","expliquer le rôle de la myéline"],"parties":[{"t":"Les modes de conduction","html":"<div class='def'><b>Définition</b>Dans une fibre sans myéline, la conduction est <strong>de proche en proche</strong>. Dans une fibre myélinisée, elle est <strong>saltatoire</strong>, d'un nœud de Ranvier à l'autre.</div>"},{"t":"La vitesse","verrou":true},{"t":"La période réfractaire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":40,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un enregistrement à deux électrodes sépare de 4 cm un même potentiel d'action, avec un retard de 1 ms.","tache":"Calcule la vitesse."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r41",{"duree":20,"titre":"Intégration : le message nerveux dans la vie courante","accroche":"Le toucher, la douleur, le geste.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Un <strong>message nerveux</strong> est une suite de potentiels d'action.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":41,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un chauffeur blessé à l'avant-bras à Tiko ne sent plus ses doigts.","tache":"Explique cette perte de sensibilité."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r42",{"duree":20,"titre":"La synapse : structure","accroche":"Entre deux neurones, un espace.","intro":"La synapse est la zone de communication entre deux cellules excitables.","objectifs":["décrire une synapse","nommer les éléments","distinguer les types"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>synapse</strong> est une zone de jonction fonctionnelle entre un neurone et une autre cellule.</div>"},{"t":"Éléments","verrou":true},{"t":"Types","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":42,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"En TP à Yaoundé, un élève observe une électronographie de synapse.","tache":"Liste les éléments à légender."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r43",{"duree":20,"titre":"La synapse : fonctionnement","accroche":"Un message électrique devient chimique, puis redevient électrique.","intro":"La transmission synaptique met en jeu un neurotransmetteur.","objectifs":["décrire les étapes","expliquer le rôle du Ca²⁺","distinguer PPSE et PPSI"],"parties":[{"t":"Les étapes","html":"<div class='def'><b>Définition</b>La <strong>transmission synaptique</strong> : l'arrivée du potentiel d'action provoque l'entrée de Ca²⁺, l'exocytose du neurotransmetteur et sa fixation sur des récepteurs postsynaptiques.</div>"},{"t":"PPSE et PPSI","verrou":true},{"t":"Fin du message","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":43,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"On stimule un neurone présynaptique et on enregistre : potentiel d'action présynaptique à t = 0 ; dépolarisation de la cellule postsynaptique à t = 0,5 ms. Sur une même fibre sans synapse, le message parcourt la même distance en 0,01 ms.","tache":"Explique ce délai."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r44",{"duree":20,"titre":"L'intégration neuronale","accroche":"Un neurone additionne avant de répondre.","intro":"Un neurone reçoit de nombreux messages excitateurs et inhibiteurs.","objectifs":["définir la sommation","distinguer spatiale et temporelle","prévoir une réponse"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>intégration neuronale</strong> est l'addition, au niveau du neurone postsynaptique, des potentiels reçus.</div>"},{"t":"Les sommations","verrou":true},{"t":"Le résultat","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":44,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"On enregistre un neurone moteur (repos −70 mV, seuil −55 mV). Un PPSE isolé le porte à −64 mV ; deux PPSE simultanés venant de deux synapses, à −58 mV ; trois PPSE simultanés déclenchent un potentiel d'action.","tache":"Interprète ces résultats."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r45",{"duree":20,"titre":"Substances et transmission synaptique","accroche":"Tramadol, alcool, cannabis : des effets sur la synapse.","intro":"Certaines substances modifient le fonctionnement des synapses et créent une dépendance.","objectifs":["expliquer le mode d'action","citer des substances","prévenir les addictions"],"parties":[{"t":"Les modes d'action","html":"<div class='def'><b>Définition</b>Une substance peut <strong>imiter</strong>, <strong>bloquer</strong> ou <strong>prolonger</strong> l'action d'un neurotransmetteur.</div>"},{"t":"Exemples","verrou":true},{"t":"Dépendance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":45,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"À Maroua, des jeunes consomment du tramadol pour tenir pendant les travaux pénibles.","tache":"Rédige un message de prévention."},"verrou":true,"nq":10,"labo":true});
