VRT_L("tle-d-svt-r48",{"duree":20,"titre":"La motricité dirigée","accroche":"Un geste volontaire part du cortex.","intro":"Le mouvement volontaire suit une voie nerveuse précise.","objectifs":["décrire la commande motrice","expliquer le croisement","interpréter une paralysie"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>motricité dirigée</strong> est l'ensemble des mouvements volontaires commandés par le cortex moteur.</div>"},{"t":"La voie motrice","verrou":true},{"t":"Conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":48,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"À la suite d'un accident à Bamenda, un homme ne peut plus lever le bras gauche.","tache":"Indique une zone possible de la lésion et justifie."},"verrou":true,"nq":10,"labo":true});
