VRT_L("tle-d-svt-r50",{"duree":20,"titre":"Origine des cellules immunitaires","accroche":"Tout commence dans la moelle osseuse.","intro":"Les cellules immunitaires naissent dans la moelle osseuse et se répartissent dans l'organisme.","objectifs":["citer les cellules","préciser leur origine","réaliser un frottis"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>leucocytes</strong> proviennent de cellules souches de la moelle osseuse.</div>"},{"t":"Maturation","verrou":true},{"t":"Organes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":50,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un laborantin de Limbé réalise un frottis sanguin pour un examen de routine.","tache":"Dis ce qu'il observera."},"verrou":true,"nq":10,"labo":true});
