VRT_L("tle-d-svt-r68",{"duree":20,"titre":"La glycémie : régulation hormonale","accroche":"Insuline et glucagon, deux hormones antagonistes.","intro":"Le pancréas ajuste la glycémie grâce à deux hormones.","objectifs":["préciser les rôles","interpréter l'expérience du foie lavé","expliquer la régulation"],"parties":[{"t":"Les deux hormones","html":"<div class='def'><b>Définition</b>L'<strong>insuline</strong> est hypoglycémiante. Le <strong>glucagon</strong> est hyperglycémiant.</div>","labo":{"type":"glycemie"}},{"t":"Actions","verrou":true},{"t":"Le foie lavé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":68,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"En TP à Mbouda, on rince un foie frais jusqu'à ce que l'eau ne contienne plus de glucose (test négatif à la liqueur de Fehling) ; après 30 minutes à 37 °C, l'eau de rinçage redonne un test positif. Un foie bouilli ne redonne pas de glucose.","tache":"Interprète ces résultats."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r69",{"duree":20,"titre":"Diabète et hypoglycémie","accroche":"Une élévation permanente abîme les organes.","intro":"Le diabète résulte d'une régulation défaillante de la glycémie.","objectifs":["distinguer type 1 et type 2","citer les complications","prévenir"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>diabète</strong> se caractérise par une glycémie à jeun égale ou supérieure à 1,26 g/L, vérifiée à deux reprises.</div>"},{"t":"Les types","verrou":true},{"t":"Complications et prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":69,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Dans un quartier de Bafoussam, sur 300 adultes dépistés, 36 ont une glycémie à jeun supérieure à 1,26 g/L et 60 une tension supérieure à 14/9 ; la plupart mangent beaucoup de friture et marchent peu.","tache":"Calcule les pourcentages et rédige des conseils argumentés pour le quartier."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r70",{"duree":20,"titre":"Pression artérielle : mesure et facteurs","accroche":"Deux nombres essentiels.","intro":"La pression artérielle est la force exercée par le sang sur la paroi des artères.","objectifs":["définir systolique et diastolique","mesurer","citer les facteurs"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>pression artérielle</strong> s'exprime par deux valeurs : la pression systolique et la pression diastolique.</div>"},{"t":"Mesure","verrou":true},{"t":"Facteurs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":70,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Une infirmière de Foumban mesure 16/10 chez un commerçant au repos.","tache":"Interprète et conseille."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r71",{"duree":20,"titre":"Pression artérielle : régulation nerveuse","accroche":"Le barorécepteur surveille chaque battement.","intro":"Des circuits réflexes corrigent rapidement la pression artérielle.","objectifs":["citer les barorécepteurs","décrire la boucle","préciser les effets"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>barorécepteurs</strong>, situés dans le sinus carotidien et la crosse aortique, détectent la pression du sang.</div>"},{"t":"Le circuit","verrou":true},{"t":"La réponse","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":71,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Un élève se lève brusquement à Ebolowa et sent un court vertige avant que cela ne passe.","tache":"Explique ce rétablissement."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r72",{"duree":20,"titre":"Pression artérielle : régulation hormonale","accroche":"Le rein intervient sur le long terme.","intro":"Des hormones ajustent le volume sanguin et le calibre des vaisseaux.","objectifs":["citer les hormones","décrire la rénine","comparer aux effets nerveux"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>régulation hormonale</strong> de la pression met en jeu notamment la rénine, l'angiotensine, l'aldostérone et l'ADH.</div>"},{"t":"Le système rénine-angiotensine","verrou":true},{"t":"Comparaison","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":72,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Après une hémorragie à l'hôpital de Mbalmayo, le médecin explique que le rein réagit.","tache":"Explique sa réaction."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r73",{"duree":20,"titre":"Élévation et baisse permanentes de la tension","accroche":"L'hypertension est longtemps silencieuse.","intro":"Une tension anormale durable abîme les organes.","objectifs":["citer les conséquences","citer les facteurs de risque","prévenir"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>hypertension artérielle</strong> est une élévation persistante de la pression artérielle.</div>"},{"t":"Conséquences","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":73,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Un retraité de Douala arrête son traitement dès qu'il se sent bien.","tache":"Explique-lui le risque."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r74",{"duree":20,"titre":"Intégration : diabète et hypertension","accroche":"Deux maladies liées au mode de vie.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Le <strong>diabète de type 2</strong> et l'<strong>hypertension</strong> sont favorisés par une alimentation déséquilibrée et la sédentarité.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":74,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Une enquête à Bafoussam montre une hausse du diabète et de l'hypertension chez les commerçants.","tache":"Élabore une affiche de prévention."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r75",{"duree":20,"titre":"Arrêt cardiaque","accroche":"Chaque minute compte.","intro":"Devant un arrêt cardiaque, des gestes simples augmentent les chances de survie.","objectifs":["reconnaître l'arrêt","alerter","réaliser le massage cardiaque"],"parties":[{"t":"Reconnaître","html":"<div class='def'><b>Définition</b>Un <strong>arrêt cardiaque</strong> se reconnaît à une personne inconsciente, qui ne respire pas ou respire anormalement.</div>"},{"t":"Les gestes","html":"<ol><li>Sécuriser.</li><li>Alerter les secours.</li><li>Masser : mains au centre du thorax, 100 à 120 compressions par minute, 5 à 6 cm chez l'adulte.</li><li>Utiliser un défibrillateur si disponible.</li></ol>","labo":{"type":"etapes","items":[["Sécuriser","écarter le danger."],["Vérifier","conscience, respiration."],["Alerter","appeler les secours."],["Masser","100 à 120 par minute."],["Défibriller","si disponible."]]}},{"t":"Insufflations","html":"<p>Le secouriste formé alterne 30 compressions et 2 insufflations.</p>","retenir":"Masser sans attendre."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Les signes d'un arrêt cardiaque sont :</p><ol type='a'><li>toux, fièvre, frissons et douleurs musculaires</li><li>douleur au pied et boiterie</li><li>démangeaisons et boutons</li><li>absence de conscience et de respiration normale</li></ol><details><summary>Voir la réponse</summary><p><strong>absence de conscience et de respiration normale</strong>. Il faut agir immédiatement.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Quelle est la fréquence des compressions ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 100 à 120 par minute.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Lutter contre certaines maladies métaboliques et porter secours.</p><p><strong>Situation.</strong> Au stade, un spectateur s'effondre ; il ne répond pas et ne respire pas. On estime que chaque minute sans massage cardiaque réduit d'environ 10 % ses chances de survie.</p><p><strong>Consigne 1.</strong> Décris, dans l'ordre, les gestes de la chaîne de survie.</p><p><strong>Consigne 2.</strong> Estime ses chances après 5 minutes sans massage et conclus.</p><details><summary>Voir une réponse attendue</summary><p>Alerter les secours ; masser immédiatement (compressions thoraciques au centre de la poitrine, environ 100 à 120 par minute, avec ou sans insufflations, 30 compressions pour 2 insufflations) ; utiliser un défibrillateur dès qu'il est disponible ; continuer jusqu'à l'arrivée des secours. Après 5 minutes, les chances ont chuté d'environ 50 % : il faut commencer le massage sans attendre.</p></details></div>","retenir":"Savoir-être mobilisé : Sens de la responsabilité."}],"revision":["Reconnaître.","Alerter.","Masser.","100 à 120 par minute."],"exo":"<p>Quelle est la fréquence des compressions ? <em>(Réponse : 100 à 120 par minute.)</em></p>","quiz":[{"q":"Les signes d'un arrêt cardiaque sont :","r":["toux, fièvre, frissons et douleurs musculaires","douleur au pied et boiterie","démangeaisons et boutons","absence de conscience et de respiration normale"],"b":3,"e":"Il faut agir immédiatement."},{"q":"Face à un arrêt cardiaque, le premier geste est :","r":["alerter les secours puis commencer le massage cardiaque","mettre la victime en position latérale de sécurité et attendre","donner à boire","attendre que la victime se réveille"],"b":0,"e":"Chaque minute sans massage réduit les chances de survie."},{"q":"En cas d'arrêt cardiaque, le geste suivant n'est pas à réaliser en priorité :","r":["pratiquer le massage cardiaque","mettre la victime en position latérale de sécurité et attendre les secours","basculer la tête en arrière pour libérer les voies aériennes de la victime inconsciente","retirer un corps étranger visible dans la bouche"],"b":1,"e":"La PLS est réservée à une victime qui respire."},{"q":"Le massage cardiaque chez l'adulte se fait :","r":["sur le ventre, au-dessus du nombril","au rythme d'une compression toutes les cinq secondes, sur le côté gauche de la poitrine","au centre de la poitrine, à une fréquence de 100 à 120 compressions par minute","sur le côté gauche du cou"],"b":2,"e":"On enfonce le sternum de 5 à 6 cm."},{"q":"Le rapport compressions-insufflations recommandé chez l'adulte est :","r":["2 compressions pour 30 insufflations","10 compressions pour 10 insufflations","15 compressions pour 1 insufflation","30 compressions pour 2 insufflations"],"b":3,"e":"C'est la recommandation des secouristes."},{"q":"Le défibrillateur automatisé externe sert à :","r":["rétablir un rythme cardiaque normal par un choc électrique","mesurer la glycémie du malade avant de lui donner du sucre","prendre la tension artérielle","faire un pansement compressif"],"b":0,"e":"Il guide vocalement le sauveteur."},{"q":"Le numéro d'urgence des sapeurs-pompiers au Cameroun est :","r":["le 117","le 118","le 112 uniquement en Europe","le 100"],"b":1,"e":"Le 117 est celui de la police."},{"q":"Les lésions cérébrales irréversibles surviennent après environ :","r":["1 heure sans circulation","1 jour entier sans circulation","3 à 5 minutes sans circulation","30 secondes toujours"],"b":2,"e":"C'est pourquoi il faut masser sans attendre."},{"q":"La protection du sauveteur et de la victime consiste d'abord à :","r":["déplacer la victime sans réfléchir","fumer","partir","écarter tout danger persistant"],"b":3,"e":"On sécurise la zone avant d'intervenir."},{"q":"Le massage cardiaque permet :","r":["de faire circuler le sang vers le cerveau","de guérir le muscle cardiaque abîmé","de faire respirer seule la victime sans aide","de faire baisser la tension"],"b":0,"e":"Il maintient l'oxygénation des organes vitaux."}],"c":"Tle D","m":"svt","rang":75,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Au stade de Limbé, un spectateur s'effondre et ne respire plus.","tache":"Présente les gestes à accomplir."},"gratuit":true});
VRT_L("tle-d-svt-r76",{"duree":20,"titre":"Étouffement total","accroche":"Une bouchée coincée : on tape, puis on comprime.","intro":"Devant une obstruction totale des voies aériennes, le geste diffère selon la victime.","objectifs":["reconnaître l'étouffement","adapter le geste","savoir quand alerter"],"parties":[{"t":"Reconnaître","html":"<div class='def'><b>Définition</b>L'<strong>étouffement total</strong> : la victime ne peut ni parler, ni tousser, ni respirer.</div>"},{"t":"Les gestes","verrou":true},{"t":"Inconscience","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":76,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Un nourrisson avale un petit objet à la maison, à Bamenda, et ne respire plus.","tache":"Présente la conduite."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r77",{"duree":20,"titre":"Perte de connaissance","accroche":"Elle respire, mais ne répond pas.","intro":"Une personne inconsciente qui respire doit être protégée de l'obstruction des voies aériennes.","objectifs":["identifier la victime","libérer les voies aériennes","réaliser la PLS"],"parties":[{"t":"Reconnaître","html":"<div class='def'><b>Définition</b>Une <strong>perte de connaissance</strong> : la personne ne répond pas, ne réagit pas, mais respire normalement.</div>"},{"t":"Les gestes","verrou":true},{"t":"Pourquoi la PLS","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":77,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Un élève se blesse dans la cour, reste inconscient mais respire.","tache":"Présente la conduite à tenir."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r78",{"duree":20,"titre":"Intégration : porter secours à l'école","accroche":"Un élève formé peut sauver une vie.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Le <strong>secourisme</strong> repose sur la protection, l'alerte et les gestes adaptés.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":78,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Au lycée de Dschang, un élève s'étouffe avec un bonbon pendant la récréation.","tache":"Présente la conduite adaptée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r79",{"duree":20,"titre":"Morphologie des fonds océaniques","accroche":"Un relief sous l'océan.","intro":"Les fonds océaniques présentent des dorsales, des plaines et des fosses.","objectifs":["nommer les reliefs","lire un profil","interpréter"],"parties":[{"t":"Les reliefs","html":"<div class='def'><b>Définition</b>Le <strong>plancher océanique</strong> comprend le plateau continental, le talus, la plaine abyssale, la dorsale et les fosses océaniques.</div>"},{"t":"La dorsale","verrou":true},{"t":"La fosse","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":79,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Un navire océanographique traverse l'Atlantique de Rio de Janeiro vers Douala et mesure la profondeur : 200 m sur la côte ; 5 000 m sur une vaste plaine ; une chaîne centrale qui remonte à 2 500 m, creusée en son sommet d'un fossé de 1 500 m ; puis de nouveau 5 000 m et 200 m près de l'Afrique.","tache":"Identifie les reliefs traversés."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r80",{"duree":20,"titre":"Fonctionnement d'un rift","accroche":"L'océan s'ouvre lentement.","intro":"Au niveau de la dorsale, de la lithosphère nouvelle se forme.","objectifs":["décrire la divergence","citer les roches","expliquer l'âge croissant"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>rift</strong> est le sillon axial d'une dorsale où deux plaques s'écartent. Du magma s'y met en place et forme une nouvelle croûte.</div>"},{"t":"Les roches","verrou":true},{"t":"L'expansion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":80,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Lors de forages dans le fond de l'Atlantique, on date les basaltes : 0 Ma sur l'axe de la dorsale, 10 Ma à 200 km à l'est, 10 Ma aussi à 200 km à l'ouest, et 20 Ma à 400 km de part et d'autre.","tache":"Interprète ces âges et calcule la vitesse d'ouverture de l'océan."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r81",{"duree":20,"titre":"Mouvements de convergence : la subduction","accroche":"Une plaque plonge sous une autre.","intro":"La plaque océanique plus dense plonge sous une autre plaque.","objectifs":["définir la subduction","citer les roches","expliquer le volcanisme"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>subduction</strong> est le plongement d'une plaque océanique sous une autre plaque.</div>"},{"t":"Conséquences","verrou":true},{"t":"Roches","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":81,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Sous les Andes, au large du Chili, on relève des foyers de séismes : à 50 km de la fosse, 30 km de profondeur ; à 200 km, 150 km ; à 500 km, 400 km. Des volcans sont actifs dans la cordillère.","tache":"Interprète la répartition des foyers."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r82",{"duree":20,"titre":"Collision et obduction","accroche":"L'Himalaya, deux continents qui se heurtent.","intro":"La convergence peut aboutir à la formation de chaînes de montagnes.","objectifs":["définir la collision","définir l'obduction","citer des exemples"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>collision</strong> est l'affrontement de deux croûtes continentales. L'<strong>obduction</strong> est le chevauchement d'une croûte continentale par une portion de lithosphère océanique.</div>"},{"t":"Conséquences","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":82,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Un élève observe une photographie de roches pliées dans une chaîne de montagnes.","tache":"Dis ce que révèlent ces plis."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r83",{"duree":20,"titre":"Mouvements de coulissage","accroche":"Deux plaques glissent côte à côte.","intro":"Certaines limites de plaques ne créent ni ne détruisent de croûte.","objectifs":["définir la faille transformante","citer des exemples","relier au métamorphisme"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>faille transformante</strong> est une limite où deux plaques coulissent horizontalement.</div>"},{"t":"Conséquences","verrou":true},{"t":"Métamorphisme","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":83,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Sur une carte de l'Atlantique équatorial, au large du Cameroun, l'axe de la dorsale est décalé tous les 50 à 300 km par des failles perpendiculaires ; le long de ces failles se produisent des séismes peu profonds, sans volcanisme.","tache":"Identifie ces failles et le mouvement des plaques à leur niveau."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r84",{"duree":20,"titre":"Catastrophes naturelles et gestion","accroche":"Prévoir, prévenir, protéger.","intro":"Le Cameroun connaît volcanisme, glissements de terrain et inondations.","objectifs":["définir aléa et catastrophe","distinguer prévision et prévention","donner des exemples camerounais"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>aléa</strong> est un phénomène naturel possible. Une <strong>catastrophe</strong> est un événement qui cause de graves dommages à une société.</div>"},{"t":"Exemples","verrou":true},{"t":"Gestion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":84,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Des familles de Bafoussam construisent au pied d'une colline qui s'effondre à chaque pluie abondante.","tache":"Propose une conduite."},"verrou":true,"nq":10,"labo":true});
