VRT_L("tle-d-svt-r86",{"duree":20,"titre":"Les preuves de l'évolution de l'Homme","accroche":"Toumaï, découvert au Tchad.","intro":"Les fossiles et les données génétiques éclairent l'origine de l'espèce humaine.","objectifs":["citer des preuves","lire une frise","situer l'Afrique"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>évolution</strong> est la transformation des êtres vivants au cours du temps. Les fossiles en sont une preuve majeure.</div>"},{"t":"Les fossiles","verrou":true},{"t":"Autres preuves","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":86,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"En visite au musée, un élève s'étonne que l'Afrique soit citée comme berceau de l'humanité.","tache":"Justifie cette affirmation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r87",{"duree":20,"titre":"Les critères de l'hominisation","accroche":"Marcher debout a tout changé.","intro":"L'hominisation désigne l'ensemble des transformations qui ont conduit à l'Homme.","objectifs":["citer les critères","relier bipédie et squelette","relier cerveau et langage"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>hominisation</strong> désigne l'ensemble des modifications anatomiques et culturelles qui ont conduit à l'espèce humaine.</div>"},{"t":"Les critères","verrou":true},{"t":"Culture","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":87,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Au musée national de Yaoundé, un tableau compare trois crânes : chimpanzé, 400 cm³, trou occipital en arrière ; Australopithèque, 450 cm³, trou occipital avancé ; Homo sapiens, 1 400 cm³, trou occipital sous le crâne.","tache":"Présente les arguments qui distinguent l'Homme, en t'appuyant sur ces données."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-d-svt-r88",{"duree":20,"titre":"Adaptation de l'Homme à son environnement","accroche":"La culture permet de vivre partout.","intro":"L'Homme s'adapte biologiquement et culturellement à son environnement.","objectifs":["distinguer les adaptations","donner des exemples","discuter l'avenir"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>adaptation</strong> est l'ensemble des caractères qui permettent de survivre dans un milieu donné.</div>"},{"t":"Biologique","verrou":true},{"t":"Culturelle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":88,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Une enquête de santé montre qu'en zone de forte transmission du paludisme, au sud du Cameroun, 20 à 25 % des habitants sont porteurs AS de la drépanocytose, contre moins de 5 % dans des régions sans paludisme. Un élève de Maroua se demande pourquoi.","tache":"Explique cette différence de fréquence de l'allèle S."},"verrou":true,"nq":10,"labo":true});
