VRT_L("tle-d-svt-r95",{"duree":20,"titre":"Intégration : une énergie pour le village","accroche":"Déchets agricoles ou forêt ?","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Une <strong>énergie renouvelable</strong> doit préserver les ressources et les cultures alimentaires.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":95,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Une communauté de l'Est veut réduire le bois de chauffe pour protéger la forêt.","tache":"Propose une solution énergétique."},"verrou":true,"nq":10,"labo":true});
